INSERT INTO `dialogueline` (`dialogueID`, `npcID`, `narrativeID`, `sceneID`, `dialogueLine`, `sequenceOrder`) VALUES
(1, 1, 1, NULL, 'Tugasku sebagai Perdana Menteri Persekutuan Tanah Melayu ialah menjelaskan gagasan Malaysia dan meyakinkan Sarawak, Sabah dan Singapura melalui rundingan, bukan paksaan. Jika aku gagal mendengar, tiada Malaysia, {nama}.', 1),
(2, 1, 1, NULL, 'Aku belajar bahawa perpaduan dibina melalui permuafakatan: mendengar, berunding dan menghormati rakan. Kerana itu kita wajar menghargai jasa dan kebijaksanaan pemimpin.', 2),
(3, 1, 1, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Perdana Menteri Persekutuan Tanah Melayu. Setiap keputusan yang kau ambil akan menentukan nasib Sarawak, Sabah, Singapura dan Tanah Melayu. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(4, 10, 1, 'e1_n1_s1', 'Tuan, usah sentuh! Itu fail Pejabat Setiausaha Kolonial. Jikalau tersalah susun, akhbar esok menuduh kita mencuri dokumen British.', 1),
(5, NULL, 1, 'e1_n1_s1', 'Surat itu telah terkoyak, Ghazali. Lebih baik kita baca siapakah yang menulisnya sebelum ia hancur.', 2),
(6, 11, 1, 'e1_n1_s1', 'Tahun 1887. Saya Lord Brassey, Pengarah British North Borneo Company. Saya mencadangkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat digabungkan.', 3),
(7, NULL, 1, 'e1_n1_s1', 'Seorang pengarah syarikat British. Jadi idea ini bermula dari luar Tanah Melayu.', 4),
(8, 13, 1, 'e1_n1_s1', 'Tahun 1938. Saya Ibrahim Haji Yaakob. Bersama Harun Aminurrashid, kami memperjuangkan satu konsep penyatuan, Melayu Raya.', 5),
(9, 14, 1, 'e1_n1_s1', 'Melayu Raya meliputi Tanah Melayu, Singapura, Kalimantan, Kepulauan Filipina dan Kepulauan Indonesia.', 6),
(10, 10, 1, 'e1_n1_s1', 'Sebab itu mohor dan sampulnya mesti dipadankan dahulu, Tuan, sebelum sesiapa melihat kita menyusun semula sejarah.', 7),
(11, 17, 1, 'e1_n1_s1', 'Maaf, Tunku. Benarkah gagasan Malaysia ini idea Tunku seorang sahaja? Saya hendak menulis jawapan Tunku malam ini juga.', 8),
(12, 5, 1, 'e1_n1_s2', 'Parlimen akan bertanya siapakah yang mula-mula bercakap tentang penggabungan ini. Jikalau Tunku tersilap jawab, kita nampak seperti mencipta sejarah.', 1),
(13, NULL, 1, 'e1_n1_s2', 'Telegram 1951 ini menyebut seorang pegawai British berunding dengan pemimpin empat wilayah.', 2),
(14, 12, 1, 'e1_n1_s2', 'Saya, Malcolm MacDonald. Pada 1951 saya cuba menghidupkan semula idea lama itu dengan berunding terus dengan pemimpin Tanah Melayu, Sarawak, Sabah dan Singapura.', 3),
(15, 5, 1, 'e1_n1_s2', 'Maka empat draf ini ialah empat peringkat. Tugas kita menyusunnya agar Parlimen faham bagaimanakah idea ini bergerak sampai ke tangan Tunku.', 4),
(16, NULL, 1, 'e1_n1_s2', 'Dan pemimpin Persekutuan yang pertama menyebutnya ialah aku, pada 1955. Susun dahulu, Razak, lalu kita tentukan apa yang disebut.', 5),
(17, 5, 1, 'e1_n1_s2', 'Satu soalan lagi sebelum pencetak mengamuk, Tunku, dalam ucapan nanti, hendak sebut nama Brassey atau tidak?', 6),
(18, 5, 1, 'e1_n1_s3', 'Tengok pin merah itu, Tunku. Bukan hiasan. Setiap satu menandakan tempat ancaman pernah dilaporkan.', 1),
(19, NULL, 1, 'e1_n1_s3', 'Singapura di kiri, Sarawak di kanan. Kenapa pin di sana lebih banyak daripada di Tanah Melayu?', 2),
(20, 10, 1, 'e1_n1_s3', 'Kerana di sana belum ada pengalaman menghadapi komunis seperti kita di Persekutuan, Tuan. Kita telah belajar bertahun-tahun.', 3),
(21, 4, 1, 'e1_n1_s3', 'Itu sebabnya saya datang, Tunku. Jika Singapura berdiri sendiri, saya tidak yakin kami mampu mengawalnya.', 4),
(22, NULL, 1, 'e1_n1_s3', 'Jikalau begitu pengalaman kami boleh digunakan di sana juga. Cari empat petunjuk di bilik ini, Ghazali, yang boleh aku bawa ke Parlimen.', 5),
(23, 5, 1, 'e1_n1_s3', 'Satu perkara lagi sebelum kita naik. Akhbar hendak masuk ke bilik ini, Tunku. Bagaimanakah?', 6),
(24, 41, 1, 'e1_n1_s4', 'Saya wakil rakyat India, Tunku. Rakyat saya bertanya sama ada Malaysia akan menjadikan kami minoriti yang semakin kecil.', 1),
(25, 16, 1, 'e1_n1_s4', 'Begitu juga kerisauan rakyat Cina. Kami takut bilangan antara kaum tidak seimbang.', 2),
(26, NULL, 1, 'e1_n1_s4', 'Jika Sarawak, Sabah dan Singapura masuk, nisbah itu berubah. Itu salah satu sebabnya.', 3),
(27, 5, 1, 'e1_n1_s4', 'Namun rakyat biasa hendak tahu apa yang mereka dapat. Jalan, sekolah, klinik, dan bila negeri-negeri itu boleh merdeka sepenuhnya.', 4),
(28, 10, 1, 'e1_n1_s4', 'Jawapannya ada dalam empat kad ini, Tuan. Padankan sebab dengan penjelasannya sebelum mereka bosan menunggu.', 5),
(29, 41, 1, 'e1_n1_s4', 'Satu soalan terakhir, Tunku. Berani tak Tunku berjanji rakyat India tidak akan dipinggirkan?', 6),
(30, 10, 1, 'e1_n1_s5', 'Tuan, keratan akhbar ini hanya separuh. Wartawan pasti bertanya tarikh sebenar pengumuman ini.', 1),
(31, NULL, 1, 'e1_n1_s5', 'Aku tidak boleh menyebut tarikh yang salah di hadapan orang sebegini ramai.', 2),
(32, 10, 1, 'e1_n1_s5', 'Tarikhnya dikodkan dalam keratan, Tuan. Ayat terakhir berkata pengumuman ini mendahului lawatan ke Sarawak dan penubuhan JSKM.', 3),
(33, 4, 1, 'e1_n1_s5', 'Sebut nama Malaysia dengan jelas, Tunku. Usah beri ruang kepada salah faham.', 4),
(34, NULL, 1, 'e1_n1_s5', 'Aku akan menyebutnya. Namun dahulu, nyahkod keratan ini agar tarikhnya benar.', 5),
(35, 17, 1, 'e1_n1_s5', 'Tunku, adakah pengumuman ini telah muktamad? Sarawak dan Sabah telah bersetuju?', 6),
(36, 10, 1, 'e1_n1_s6', 'Tuan, di Sarawak tiada satu suara. Tiga lelaki ini mewakili tiga pihak yang berbeza.', 1),
(37, 2, 1, 'e1_n1_s6', 'Aku Temenggung Jugah, pemimpin PESAKA. Tunku datang untuk bercakap atau untuk memberitahu? Kami bukan anak kecil.', 2),
(38, NULL, 1, 'e1_n1_s6', 'Aku datang untuk belajar siapakah tuan hamba sebelum aku meminta tuan hamba percaya kepadaku.', 3),
(39, 6, 1, 'e1_n1_s6', 'Aku Stephen Kalong Ningkan dari SNAP. Pastikan Tunku tahu parti siapakah yang mana. Di sini orang tidak percaya pemimpin yang tidak mengenal mereka.', 4),
(40, 15, 1, 'e1_n1_s6', 'Saya Abang Haji Mustapha dari PANAS. Pasangkan pemimpin dengan partinya dahulu, Tunku. Lalu kami sudi mendengar.', 5),
(41, 2, 1, 'e1_n1_s6', 'Satu perkara lagi, Tunku. Adakah Sarawak sekadar menjadi tambahan kepada Tanah Melayu?', 6),
(42, 3, 1, 'e1_n1_s7', 'Tunku, mereka datang kerana Tunku berjanji akan ada jawatankuasa terbuka. Usah hampakan.', 1),
(43, 2, 1, 'e1_n1_s7', 'Ketahuilah, di rumah panjang kami, keputusan dibuat bersama. Jawatankuasa ini mesti begitu juga.', 2),
(44, 9, 1, 'e1_n1_s7', 'Saya, Mustapha Harun, mewakili Sabah di meja ini. Kami hendak syarat kami didengar sebelum apa-apa dimuktamadkan.', 3),
(45, 10, 1, 'e1_n1_s7', 'Tuan, semua yang membuktikan jawatankuasa ini sah ada di atas dan sekeliling meja. Cari semuanya sebelum mesyuarat bermula.', 4),
(46, NULL, 1, 'e1_n1_s7', 'Dokumen Donald itu, ia cadangan syarat Sabah? Biar aku lihat sendiri sebelum menjawab sesiapa.', 5),
(47, 3, 1, 'e1_n1_s7', 'Tunku, jawab dengan jujur. Bersediakah Tunku menerima syarat yang kami sendiri tulis?', 6),
(48, 10, 1, 'e1_n1_s8', 'Tuan, jikalau ada fail yang tercicir, nama saya yang dipersoalkan di London.', 1),
(49, 16, 1, 'e1_n1_s8', 'Saya wakil Persekutuan. Saya akan pastikan tiada suara yang dibisukan.', 2),
(50, NULL, 1, 'e1_n1_s8', 'Berapa lama masa yang ada sebelum British menunggu jawapan?', 3),
(51, 5, 1, 'e1_n1_s8', 'Suruhanjaya mula pada Januari. Laporan mesti sampai ke tangan mereka sebelum pertengahan tahun.', 4),
(52, 10, 1, 'e1_n1_s8', 'Tolong pasangkan sampul ini dahulu, Tuan. Setiap orang dan setiap tarikh ada tugasnya dalam laporan.', 5),
(53, 16, 1, 'e1_n1_s8', 'Satu soalan sebelum kita mula, Tunku. Hendak membaca laporan sebelum diserahkan kepada British?', 6),
(54, 7, 1, 'e1_n1_s9', 'Dua pertiga menyokong. Kami satu pertiga yang tidak. Usah sebut ia sebagai suara semua.', 1),
(55, NULL, 1, 'e1_n1_s9', 'Aku tidak pernah berkata semua. Apa yang tuan hamba mahu?', 2),
(56, 7, 1, 'e1_n1_s9', 'Kami tidak mahu sekadar menjadi wilayah kecil di bawah Kuala Lumpur. Kami mahu persekutuan sendiri bersama Brunei dan Borneo Utara.', 3),
(57, 10, 1, 'e1_n1_s9', 'Tuan, halaman itu menyebut parti yang menolak, namun dikodkan. Teliti dahulu parti yang tidak menolak, agar kita tidak menuduh sesiapa.', 4),
(58, NULL, 1, 'e1_n1_s9', 'Nyahkod dengan teliti, usah terburu-buru menuduh.', 5),
(59, 7, 1, 'e1_n1_s9', 'Tunku, bagaimanakah Tunku akan melayan suara yang menolak ini?', 6),
(60, 3, 1, 'e1_n1_s10', 'Tunku, kami tidak hendak janji lisan lagi. Kami hendak tulis.', 1),
(61, 15, 1, 'e1_n1_s10', 'Saya mewakili Sarawak. Siapakah yang duduk di meja ini dan atas nama siapakah?', 2),
(62, 10, 1, 'e1_n1_s10', 'Ada empat pihak di sini, Tuan. Tarikh mesyuarat dan tujuannya mesti ditulis dengan tepat, agar dokumen ini sah.', 3),
(63, NULL, 1, 'e1_n1_s10', 'Susun butirannya dahulu. Jikalau satu pihak tertinggal, mesyuarat ini boleh dipersoalkan.', 4),
(64, 5, 1, 'e1_n1_s10', 'Pihak British membantu menyusun, namun keputusan tetap pada pihak yang terlibat.', 5),
(65, 15, 1, 'e1_n1_s10', 'Tunku, bolehkah Sarawak menyemak draf ini sebelum dimuktamadkan?', 6),
(66, 4, 1, 'e1_n1_s11', 'Tunku, orang bertanya mengapakah kami mengundi selepas semua yang telah diputuskan di Kuala Lumpur.', 1),
(67, NULL, 1, 'e1_n1_s11', 'Kerana rakyat Singapura berhak menjawab sendiri, Lee.', 2),
(68, 10, 1, 'e1_n1_s11', 'Tuan, wartawan dari London telah bertanya langkah-langkah 1962. Susun dari yang paling awal, usah sampai mereka kata kita memutar belit.', 3),
(69, NULL, 1, 'e1_n1_s11', 'Jawapan hari ini bermula daripada satu suruhanjaya yang bertanya kepada rakyat.', 4),
(70, 4, 1, 'e1_n1_s11', 'Tunku, hendak menunggu bersama kami sehingga undi dikira?', 5),
(71, 2, 1, 'e1_n1_s12', 'Di kampung kami, apabila tanda tangan ditulis, ia dipegang sepanjang hayat. Ini bukan upacara kosong.', 1),
(72, 15, 1, 'e1_n1_s12', 'Saya pun begitu. Usah tergesa-gesa.', 2),
(73, NULL, 1, 'e1_n1_s12', 'Sebelum sesiapa menandatangani, aku hendak yakin dokumen yang benar berada di meja yang benar.', 3),
(74, 10, 1, 'e1_n1_s12', 'Empat benda di meja ini membuktikan ia tempat dan hari yang sah, Tuan. Cari semuanya sebelum pegawai British bertanya.', 4),
(75, 5, 1, 'e1_n1_s12', 'Tarikhnya mesti tepat pada dokumen itu, Tunku. Tiada ruang untuk silap.', 5),
(76, 2, 1, 'e1_n1_s12', 'Tunku, adakah tandatangan ini membebaskan Sarawak daripada tanggungjawab lama?', 6),
(77, 3, 1, 'e1_n1_s13', 'Tunku, penduduk bertanya sama ada pegawai ini diupah British untuk memaksa jawapan.', 1),
(78, 4, 1, 'e1_n1_s13', 'Singapura sudah mengundi dalam cara lain. Usah campur aduk dengan misi ini.', 2),
(79, NULL, 1, 'e1_n1_s13', 'Catatan misi mesti menyebut dengan jelas siapakah yang ditemui.', 3),
(80, 10, 1, 'e1_n1_s13', 'Petikan misi ada di tangan saya, Tuan. Ia menyebut tarikh dan tujuan, namun pihak yang ditemui dikodkan. Baca benar-benar.', 4),
(81, 3, 1, 'e1_n1_s13', 'Seorang penghulu bertanya, Tunku, jika mereka menolak, adakah Tunku akan menghormati keputusan itu?', 5),
(82, 5, 1, 'e1_n1_s14', 'Tunku, dua dokumen telah ada di atas mimbar. Satu telah ditandatangani di London. Satu lagi untuk hari ini.', 1),
(83, NULL, 1, 'e1_n1_s14', 'Yang mana satu patut aku baca kepada rakyat?', 2),
(84, 10, 1, 'e1_n1_s14', 'Yang menyebut mulai 16 September, Tuan. Dokumen London tidak berkata begitu.', 3),
(85, 3, 1, 'e1_n1_s14', 'Salah ambil dokumen, ucapan malam ini jadi sia-sia, Tunku.', 4),
(86, NULL, 1, 'e1_n1_s14', 'Nyahkod petikan itu dahulu sebelum aku melangkah ke mikrofon.', 5),
(87, 5, 1, 'e1_n1_s14', 'Satu soalan sebelum Tunku naik ke pentas, adakah Tunku hendak menyebut cabaran yang menanti selepas ini?', 6),
(88, 10, 1, 'e1_n1_s15', 'Tuan, kad nama telah dicetak. Sebelum bergabung, Persekutuan Tanah Melayu ada sebelas negeri, termasuk Pahang dan Melaka.', 1),
(89, NULL, 1, 'e1_n1_s15', 'Dan selepas 16 September 1963, berapa semuanya, Razak?', 2),
(90, 5, 1, 'e1_n1_s15', 'Empat belas negeri, Tunku, apabila Singapura, Sabah dan Sarawak bergabung. Dalam perjanjian 1963, Sabah disebut Borneo Utara.', 3),
(91, NULL, 1, 'e1_n1_s15', 'Sarawak pula aku sendiri lawat pada Julai 1961. Dan Brunei?', 4),
(92, 5, 1, 'e1_n1_s15', 'Brunei menolak penyertaan, Tunku. Kad mereka tidak akan duduk di meja ini.', 5),
(93, NULL, 1, 'e1_n1_s15', 'Jikalau begitu susun semua kad sebelum tetamu masuk.', 6),
(94, 4, 1, 'e1_n1_s15', 'Tunku, di mana wakil Singapura patut duduk di dewan ini?', 7),
(95, 5, 1, 'e1_n1_s16', 'Telegram telah sampai, Tunku. SUPP masih menolak kerana mahu persekutuan sendiri.', 1),
(96, NULL, 1, 'e1_n1_s16', 'Dan negara jiran kita?', 2),
(97, 10, 1, 'e1_n1_s16', 'Indonesia melancarkan konfrontasi terhadap Malaysia dari 1963 hingga 1966, Tuan. Filipina pula mendakwa Sabah sebahagian daripada wilayahnya.', 3),
(98, 5, 1, 'e1_n1_s16', 'Dan Singapura, Tunku, berpisah daripada Malaysia pada 1965.', 4),
(99, NULL, 1, 'e1_n1_s16', 'Pasangkan semuanya dahulu. Salah tuduh hanya menambah musuh di meja rundingan.', 5),
(100, 5, 1, 'e1_n1_s16', 'Tunku, bagaimanakah kita mahu menghadapi Indonesia dan Filipina?', 6),
(101, 5, 1, 'e1_n1_s17', 'Arkib hanya menyimpan sejarah yang tersusun, Tunku. Lapan langkah ini mesti rapi.', 1),
(102, NULL, 1, 'e1_n1_s17', 'Sepanjang perjalanan ini aku bertemu fail, wajah dan tandatangan. Tak sangka semuanya boleh disusun.', 2),
(103, 10, 1, 'e1_n1_s17', 'Ada tiga kad dalam tahun 1961, dua dalam 1962 dan tiga dalam 1963, Tuan. Kumpulkan mengikut tahun dahulu.', 3),
(104, NULL, 1, 'e1_n1_s17', 'Mulakan dari Adelphi dan berakhir dengan Pemasyhuran.', 4),
(105, 5, 1, 'e1_n1_s17', 'Satu soalan terakhir untuk rekod, Tunku. Nama siapakah patut ditulis sebagai pembentuk Malaysia?', 5),
(106, 3, 2, NULL, 'Aku Donald Stephens, pemimpin UNKO di Sabah. Tugasku menyuarakan harapan dan kebimbangan rakyat Sabah, dan meyakinkan mereka dengan bukti, bukan janji kosong, {nama}.', 1),
(107, 3, 2, NULL, 'Aku belajar bahawa permuafakatan lahir apabila suara rakyat didengar dan setiap langkah dijelaskan dengan jujur. Kerana itu pemimpin wajar dihargai.', 2),
(108, 3, 2, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemimpin UNKO di Sabah. Rakyatmu mahu tahu apa untung dan rugi Malaysia. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(109, 9, 2, 'e1_n2_s1', 'Donald, di pekan orang berbisik Tanah Melayu hendak mengambil Borneo. Jikalau engkau tidak menjawab malam ini, esok mereka telah percaya.', 1),
(110, NULL, 2, 'e1_n2_s1', 'Itu cakap kosong, Datu. Tiada siapakah pernah menyebutnya kepada kita.', 2),
(111, 9, 2, 'e1_n2_s1', 'Jikalau begitu fail berhabuk itu apa? Cop di atasnya syarikat British, bukan Tanah Melayu.', 3),
(112, 11, 2, 'e1_n2_s1', 'Tahun 1887. Saya Lord Brassey, Pengarah British North Borneo Company. Saya mencadangkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat digabungkan dalam satu pentadbiran.', 4),
(113, NULL, 2, 'e1_n2_s1', 'Fail Lord Brassey, tahun 1887. Dia mencadangkan penggabungan Sarawak, Sabah, Negeri-negeri Melayu dan satu lagi kumpulan negeri di Selat Melaka. Aku belum membaca senarai penuhnya.', 5),
(114, 9, 2, 'e1_n2_s1', 'Nyahkod petikannya kini. Orang kampung akan tanya wilayah mana lagi yang disebut, dan engkau mesti tahu jawapannya.', 6),
(115, 8, 2, 'e1_n2_s1', 'Pak Donald, jikalau benar idea ini telah lama, mengapakah kami baru mendengarnya kini?', 7),
(116, 9, 2, 'e1_n2_s2', 'Empat tarikh, empat nama. Orang kampung akan keliru, Donald.', 1),
(117, NULL, 2, 'e1_n2_s2', 'Ketahuilah, mereka tidak perlu menghafal. Mereka perlu nampak talinya, iaitu syarikat British dahulu, lalu tokoh tempatan, lalu pegawai British, barulah Tunku.', 2),
(118, 12, 2, 'e1_n2_s2', 'Maka pada 1951 saya, Malcolm MacDonald, berbincang dengan pemimpin empat wilayah tentang penggabungan. Saya hanya menghidupkan semula idea lama.', 3),
(119, 9, 2, 'e1_n2_s2', 'Maka pasangkan setiap tahun dengan orangnya sebelum pemuda-pemuda UNKO tiba.', 4),
(120, 20, 2, 'e1_n2_s2', 'Encik Stephens, jikalau kita beritahu kampung bahawa ini idea lama, adakah itu bermakna kita tidak perlu bertanya pendapat mereka lagi?', 5),
(121, 5, 2, 'e1_n2_s3', 'Donald, aku tidak datang membawa tarikh. Aku datang membawa kebimbangan. Ancaman komunis di Singapura dan Sarawak makin serius.', 1),
(122, NULL, 2, 'e1_n2_s3', 'Sabah tenang. Mengapakah kami perlu risau tentang komunis?', 2),
(123, 5, 2, 'e1_n2_s3', 'Kerana Borneo sebuah pulau. Jika Sarawak lemah, Sabah di sebelahnya turut terdedah. Persekutuan telah lama menghadapi komunis dan ada pengalamannya.', 3),
(124, NULL, 2, 'e1_n2_s3', 'Aku akan lihat sendiri buktinya. Laporan Singapura, laporan Sarawak, dan nota pengalaman Persekutuan itu.', 4),
(125, 5, 2, 'e1_n2_s3', 'Cari ketiga-tiganya di atas meja. Aku hendak engkau yakin dengan bukti, bukan dengan kata-kataku.', 5),
(126, 5, 2, 'e1_n2_s3', 'Satu soalan yang kuharap engkau fikirkan, Donald. Jika ancaman di Sarawak merebak, siapakah yang akan menjaga Sabah?', 6),
(127, 8, 2, 'e1_n2_s4', 'Datu, Pak Donald, usah berkisah tentang komunis sahaja. Apa untungnya kepada kami yang berkebun dan menangkap ikan?', 1),
(128, 9, 2, 'e1_n2_s4', 'Keselamatan bukan satu-satunya sebab. Aku ada risalah dengan empat sebab, namun sebahagian sudah tercampur dengan risalah salah.', 2),
(129, NULL, 2, 'e1_n2_s4', 'Pilih risalah yang menyenaraikan keempat-empat sebab dengan benar. Usah ada yang diselit palsu.', 3),
(130, 9, 2, 'e1_n2_s4', 'Orang kampung tidak suka cakap yang bengkok, Donald. Pilih dengan teliti.', 4),
(131, 8, 2, 'e1_n2_s4', 'Pak Donald, jikalau kami menyokong, siapakah yang menjamin tanah dan adat kami tidak diambil?', 5),
(132, 9, 2, 'e1_n2_s5', 'Donald! Kita masih menyusun hujah, dan Tunku telah bercakap. Sabah akan kelihatan terlewat.', 1),
(133, NULL, 2, 'e1_n2_s5', 'Enam tahun idea itu tidur sejak 1955. Hari ini ia bangun. Tarikh tepat pengumuman itu?', 2),
(134, 9, 2, 'e1_n2_s5', 'Keratan akhbar ini yang menyebut. Ayat terakhir berkata pengumuman ini mendahului JSKM, Cobbold dan Perjanjian Malaysia.', 3),
(135, NULL, 2, 'e1_n2_s5', 'Maka ia mesti jauh lebih awal daripada semua itu. Nyahkod tarikhnya.', 4),
(136, 17, 2, 'e1_n2_s5', 'Encik Stephens, wartawan dari Jesselton bertanya. Adakah UNKO menyokong atau menolak cadangan Tunku?', 5),
(137, 1, 2, 'e1_n2_s6', 'Saya datang bukan untuk memaksa. Saya datang untuk menerangkan idea penggabungan ini kepada anda.', 1),
(138, 6, 2, 'e1_n2_s6', 'Tunku, ramai bertanya kepentingan kami. Kami bukan hanya wilayah tambahan.', 2),
(139, 15, 2, 'e1_n2_s6', 'Saya Datu Bandar Abang Haji Mustapha. Kami hendak dengar sendiri daripada Tunku, bukan hanya daripada akhbar.', 3),
(140, 2, 2, 'e1_n2_s6', 'Dengar baik-baik. Di tebing ini ada tiga petanda lawatan ini, iaitu pemimpin yang mendengar, penduduk yang bertanya, dan bot dengan bendera yang membawa Tunku.', 4),
(141, NULL, 2, 'e1_n2_s6', 'Aku mencari ketiga-tiga petanda itu. Itulah yang akan aku ceritakan kepada Sabah.', 5),
(142, 2, 2, 'e1_n2_s6', 'Tuan hamba datang dari Sabah, Donald. Adakah Sabah juga hendak meletakkan syarat sebelum bersetuju?', 6),
(143, 1, 2, 'e1_n2_s7', 'Donald dari UNKO, engkau mencadangkan jawatankuasa ini. Aku, wakil UMNO, hendak kita membinanya bersama.', 1),
(144, NULL, 2, 'e1_n2_s7', 'Tujuannya satu, iaitu meyakinkan pemimpin Sarawak dan Sabah tentang pembentukan Malaysia.', 2),
(145, 2, 2, 'e1_n2_s7', 'Aku Temenggung Jugah dari PESAKA. Jikalau begitu pastikan setiap orang di meja ini dikenali dengan parti masing-masing, agar tiada siapakah dituduh bercakap bagi pihak orang lain.', 3),
(146, 9, 2, 'e1_n2_s7', 'Aku, Mustapha Harun, mewakili USNO. Stephen Kalong Ningkan dari SNAP dan Datu Bandar Abang Haji Mustapha dari PANAS pun ada di sini. Pastikan kad kita benar, usah sampai tertukar.', 4),
(147, 1, 2, 'e1_n2_s7', 'Donald, apa yang paling engkau harapkan daripada jawatankuasa ini?', 5),
(148, 10, 2, 'e1_n2_s8', 'Suruhanjaya ini dibentuk untuk mendapatkan reaksi penduduk Sarawak dan Sabah. Setiap surat dan suara dicatat.', 1),
(149, 16, 2, 'e1_n2_s8', 'Saya menemu ramah penduduk dan meneliti memorandum mereka tentang pembentukan Malaysia. Saya mencari satu surat yang mencatat pendirian mereka.', 2),
(150, NULL, 2, 'e1_n2_s8', 'Surat itu bukan laporan kerana laporan belum ditulis, dan bukan perjanjian kerana perjanjian belum wujud.', 3),
(151, 16, 2, 'e1_n2_s8', 'Benar. Pilih dokumen yang benar-benar datang daripada penduduk.', 4),
(152, 16, 2, 'e1_n2_s8', 'Encik Stephens, apa yang patut saya sampaikan kepada penduduk yang takut bersuara di hadapan pegawai?', 5),
(153, 9, 2, 'e1_n2_s9', 'Laporan siap. Dua pertiga penduduk Sarawak dan Sabah menyokong pembentukan Malaysia.', 1),
(154, NULL, 2, 'e1_n2_s9', 'Dua pertiga bukan semua. Satu pertiga lagi masih ragu.', 2),
(155, 6, 2, 'e1_n2_s9', 'Aku, Ningkan, tidak hendak hasil ini dikatakan tanda semua telah bersetuju. Wakil SUPP di luar itu akan bercakap lantang.', 3),
(156, 9, 2, 'e1_n2_s9', 'Sebelum dia masuk, susun dahulu langkah dari Adelphi hingga laporan. Kita mesti tunjuk perjalanan ini teratur.', 4),
(157, 7, 2, 'e1_n2_s9', 'Encik Stephens, jika satu pertiga tidak bersetuju, adakah suara kami tidak berharga?', 5),
(158, 5, 2, 'e1_n2_s10', 'Wakil British, Persekutuan Tanah Melayu, Sarawak dan Sabah duduk di sisi meja yang sama. Tidak ada pihak yang dipinggirkan.', 1),
(159, NULL, 2, 'e1_n2_s10', 'Janji lisan mudah dilupakan. Kami hendak tulisan.', 2),
(160, 6, 2, 'e1_n2_s10', 'Aku hendak perlindungan untuk Sarawak dinyatakan jelas dalam rangka perlembagaan, bukan diserahkan kepada budi bicara orang lain.', 3),
(161, 5, 2, 'e1_n2_s10', 'Itulah sebab mesyuarat ini diadakan. Nyahkod nama badan yang dibentuk untuk tugas itu.', 4),
(162, 5, 2, 'e1_n2_s10', 'Donald, apa yang paling perlu dilindungi dalam rangka perlembagaan bagi Sabah?', 5),
(163, 4, 2, 'e1_n2_s11', 'Rundingan antara Persekutuan Tanah Melayu dan Singapura telah selesai. Rakyat telah mengundi.', 1),
(164, NULL, 2, 'e1_n2_s11', 'Mengapakah pemimpin PAP menyokong?', 2),
(165, 4, 2, 'e1_n2_s11', 'Ketahuilah, kerana kami yakin gabungan membawa keselamatan dan kemajuan. Namun dokumen keputusan itu hilang di antara timbunan ini.', 3),
(166, 5, 2, 'e1_n2_s11', 'Pilih dokumen yang betul, Donald. Usah tersalah ambil laporan Cobbold atau perjanjian yang belum wujud.', 4),
(167, 4, 2, 'e1_n2_s11', 'Rakyat Singapura telah menjawab. Bila pula Sarawak dan Sabah memberi jawapan akhir?', 5),
(168, 9, 2, 'e1_n2_s12', 'Donald, tiga telegram sampai serentak. Satu berkata London, satu berkata Singapura, satu lagi berkata Kuala Lumpur.', 1),
(169, NULL, 2, 'e1_n2_s12', 'Datu, usah baca yang salah. Orang akan mengingati tarikh yang engkau sebut.', 2),
(170, 8, 2, 'e1_n2_s12', 'Mana satu yang betul, Datu? Kami telah menunggu sejak pagi.', 3),
(171, 9, 2, 'e1_n2_s12', 'Pilih telegram yang menyebut tempat dan tarikh perjanjian dengan tepat.', 4),
(172, 9, 2, 'e1_n2_s12', 'Donald, orang ramai menunggu. Apa yang engkau hendak aku umumkan kepada mereka?', 5),
(173, 9, 2, 'e1_n2_s13', 'Mengapakah PBB perlu bertanya lagi? Cobbold telah bertanya.', 1),
(174, NULL, 2, 'e1_n2_s13', 'Cobbold mendapat reaksi penduduk dan melapor kepada British dan Persekutuan. UNMM pula datang untuk mengesahkan.', 2),
(175, 19, 2, 'e1_n2_s13', 'Benar, Encik Stephens. Cari tiga tanda bilik ini, iaitu pegawai berbaret biru, sepanduk misi dan peti undi pandangan penduduk.', 3),
(176, NULL, 2, 'e1_n2_s13', 'Aku akan menunjukkan kepada Datu agar dia faham kerja PBB dengan mata sendiri.', 4),
(177, 19, 2, 'e1_n2_s13', 'Encik Stephens, mengapakah penduduk perlu ditanya sekali lagi oleh PBB selepas Cobbold?', 5),
(178, 2, 2, 'e1_n2_s14', 'Pemasyhuran diadakan serentak di empat tempat. Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall, Singapura.', 1),
(179, NULL, 2, 'e1_n2_s14', 'Dokumen itu menyebut perjanjian 9 Julai 1963 antara Persekutuan Tanah Melayu, Sarawak, Sabah dan Singapura.', 2),
(180, 9, 2, 'e1_n2_s14', 'Padankan setiap tempat dengan negeri atau wilayah yang bergabung. Murid-murid hendak tahu.', 3),
(181, 18, 2, 'e1_n2_s14', 'Pak Donald, mengapakah pemasyhuran diadakan di empat tempat, bukan satu tempat sahaja?', 4),
(182, 9, 2, 'e1_n2_s15', 'Brunei menolak penyertaan dalam Malaysia. Singapura datang, Sabah dan Sarawak datang. Namun masih ada yang tidak senang.', 1),
(183, NULL, 2, 'e1_n2_s15', 'Namun itu bukan masalah terbesar.', 2),
(184, 9, 2, 'e1_n2_s15', 'Surat ini daripada Filipina. Ia menuntut wilayah tempat kita berkhidmat. Baca dengan teliti dan nyahkod wilayahnya.', 3),
(185, 20, 2, 'e1_n2_s15', 'Encik Stephens, wilayah yang dimaksudkan itu rumah kami semua.', 4),
(186, 20, 2, 'e1_n2_s15', 'Jikalau Filipina mendakwa wilayah itu, adakah kita akan keluar daripada Malaysia?', 5),
(187, 9, 2, 'e1_n2_s16', 'Pemasyhuran telah lama berlalu. Namun kisah tidak habis di situ. Singapura, Brunei, Filipina, semuanya meninggalkan kesan.', 1),
(188, NULL, 2, 'e1_n2_s16', 'Dan Brunei tidak menyertai. Walau begitu, dahulu aku tidak yakin Malaysia akan lahir.', 2),
(189, 18, 2, 'e1_n2_s16', 'Pak Donald, murid-murid hendak tahu bagaimanakah Malaysia dibentuk daripada awal hingga akhir.', 3),
(190, 9, 2, 'e1_n2_s16', 'Susun lapan langkah itu dahulu, Donald, agar ucapanmu kemas dan tidak ada tarikh tertinggal.', 4),
(191, 9, 2, 'e1_n2_s16', 'Donald, bagaimanakah engkau hendak menutup ucapan ini?', 5),
(192, 10, 3, NULL, 'Aku Ghazali Shafie. Aku bukan di pentas, aku di bilik fail. Tugasku memastikan setiap tarikh, dokumen dan nama tepat, {nama}.', 1),
(193, 10, 3, NULL, 'Aku belajar bahawa kejayaan besar bergantung pada kerja teliti di sebalik tabir. Satu tarikh yang salah boleh menggoyahkan sebuah rundingan.', 2),
(194, 10, 3, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pegawai yang menyusun fail di sebalik tabir. Setiap dokumen mesti tepat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(195, 5, 3, 'e1_n3_s1', 'Ghazali, fail ini baru muncul dari stor. Tiada siapakah tahu isinya, namun esok Tunku hendak menyebut tahun ini dalam ucapan.', 1),
(196, NULL, 3, 'e1_n3_s1', 'Tulisan di dalamnya kabur, Tun. Aku nampak dua nama, Ibrahim Yaakob dan Harun Aminurrashid, dan satu konsep yang menyatukan beberapa tanah.', 2),
(197, 13, 3, 'e1_n3_s1', 'Pada 1938 kami memperjuangkan penyatuan Tanah Melayu, Singapura, Kalimantan, Filipina dan Indonesia dalam satu konsep.', 3),
(198, 14, 3, 'e1_n3_s1', 'Kami perlukan nama untuk impian itu, namun nama itu bukan Malaysia.', 4),
(199, NULL, 3, 'e1_n3_s1', 'Nyahkod konsep itu dahulu. Tun hendak aku bercakap dengan tepat, bukan menekan hati.', 5),
(200, 5, 3, 'e1_n3_s1', 'Ghazali, jikalau Tunku bertanya mengapakah fail ini disimpan di stor selama ini, apa yang patut kita jawab?', 6),
(201, 5, 3, 'e1_n3_s2', 'Empat fail, empat idea. Jikalau satu tahun tersalah, ucapan Tunku esok akan dikoreksi oleh wartawan.', 1),
(202, NULL, 3, 'e1_n3_s2', 'Aku tahu urutannya. Brassey dahulu, kemudian Melayu Raya, kemudian MacDonald, dan barulah Tunku.', 2),
(203, 11, 3, 'e1_n3_s2', 'Pada 1887 saya, Lord Brassey, Pengarah British North Borneo Company, mencadangkan Sarawak, Sabah, Negeri-negeri Melayu dan Negeri-negeri Selat digabungkan.', 3),
(204, 12, 3, 'e1_n3_s2', 'Pada 1951 saya, Malcolm MacDonald, berbincang dengan pemimpin Tanah Melayu, Sarawak, Sabah dan Singapura tentang penggabungan.', 4),
(205, 1, 3, 'e1_n3_s2', 'Dan pada 1955 aku sendiri mencadangkan Sarawak, Sabah, Singapura dan Brunei bersama Persekutuan Tanah Melayu, Ghazali.', 5),
(206, 5, 3, 'e1_n3_s2', 'Itu yang ditulis dalam fail. Namun susun bukan hanya ingatan. Susun benar-benar, Ghazali.', 6),
(207, 5, 3, 'e1_n3_s2', 'Satu soalan sebelum engkau mula. Bolehkah kita menyebut dalam ucapan bahawa idea ini milik Tunku seorang?', 7),
(208, 5, 3, 'e1_n3_s3', 'Singapura dan Sarawak sama-sama dilanda ancaman komunis. Persekutuan telah ada pengalaman menghadapinya.', 1),
(209, NULL, 3, 'e1_n3_s3', 'Jadi jikalau Malaysia dibentuk, pengalaman itu boleh dikongsi.', 2),
(210, 5, 3, 'e1_n3_s3', 'Tepat. Namun Lee akan bertanya bukti. Cari empat bukti di bilik ini, iaitu dua peta, kertas laporan dan papan strategi.', 3),
(211, NULL, 3, 'e1_n3_s3', 'Peta Singapura dan peta Borneo di dinding, laporan di atas meja, dan papan strategi di bahagian atas. Aku akan menyemaknya.', 4),
(212, 4, 3, 'e1_n3_s3', 'Ghazali, adakah Persekutuan benar-benar bersungguh-sungguh menolong Singapura, atau hanya hendak menambah kuasa sendiri?', 5),
(213, 16, 3, 'e1_n3_s4', 'Ghazali, empat perkataan ini nampak indah di papan hitam. Namun apa maksudnya untuk rakyat biasa?', 1),
(214, 41, 3, 'e1_n3_s4', 'Rakyat India bertanya sama ada bilangan mereka akan menjadi semakin kecil. Jelaskan, usah berselindung.', 2),
(215, NULL, 3, 'e1_n3_s4', 'Setiap perkataan ada pasangannya. Aku akan padankan keempat-empatnya agar jelas, satu demi satu.', 3),
(216, 5, 3, 'e1_n3_s4', 'Padankan dengan teliti, Ghazali. Jikalau tersilap, Wong dan Sambanthan pulang tanpa yakin.', 4),
(217, 41, 3, 'e1_n3_s4', 'Ghazali, mengapakah Sarawak, Sabah dan Brunei perlu diajak sama, bukan hanya Singapura?', 5),
(218, 1, 3, 'e1_n3_s5', 'Ghazali, teks ucapan itu mesti dijumpai malam ini. Esok seluruh dewan akan menunggu.', 1),
(219, NULL, 3, 'e1_n3_s5', 'Tuan, ada beberapa teks bercampur dalam timbunan ini. Perjanjian, laporan, dan ucapan. Aku akan memilih satu yang betul.', 2),
(220, 5, 3, 'e1_n3_s5', 'Pilih dengan teliti, Ghazali. Teks yang salah boleh memalukan Tunku di hadapan wartawan dari beberapa negara.', 3),
(221, 1, 3, 'e1_n3_s5', 'Ingat, Ghazali, pengumuman esok ialah cadangan pertama. Perjanjian dan laporan belum wujud lagi.', 4),
(222, 1, 3, 'e1_n3_s5', 'Satu perkara lagi. Jikalau wartawan bertanya sama ada Sarawak dan Sabah telah bersetuju, apa yang patut aku jawab?', 5),
(223, 5, 3, 'e1_n3_s6', 'Nota ini datang dari Kuching, Ghazali. Tunku berada di sana. Baca tujuan lawatan itu.', 1),
(224, 2, 3, 'e1_n3_s6', 'Aku Temenggung Jugah. Tunku datang untuk menerangkan, namun kami hendak lihat bukti sebelum percaya.', 2),
(225, 15, 3, 'e1_n3_s6', 'Saya Datu Bandar Abang Haji Mustapha. Kami hendak pemimpin Sarawak didengar sebelum apa-apa diputuskan.', 3),
(226, NULL, 3, 'e1_n3_s6', 'Nota ini menyebut Tunku bertemu pemimpin Sarawak dan menjelaskan satu idea kepada mereka. Aku perlu menyahkod idea itu.', 4),
(227, 5, 3, 'e1_n3_s6', 'Teliti, Ghazali. Bukan perjanjian, bukan laporan. Pilih dengan tepat apa yang Tunku jelaskan di sana.', 5),
(228, NULL, 3, 'e1_n3_s6', 'Tunku tidak membawa dokumen untuk ditandatangani. Dia membawa penerangan.', 6),
(229, 5, 3, 'e1_n3_s6', 'Jikalau pemimpin Sarawak menolak, apa yang patut Tunku lakukan, Ghazali?', 7),
(230, 3, 3, 'e1_n3_s7', 'Ghazali, delegasi Sabah telah duduk. Kami hendak pastikan semuanya sah dan jelas.', 1),
(231, 6, 3, 'e1_n3_s7', 'Delegasi Sarawak juga telah hadir. Tunjukkan kami dokumen mesyuarat dan peta wilayah.', 2),
(232, 9, 3, 'e1_n3_s7', 'Aku Mustapha Harun dari USNO, mewakili Sabah bersama Donald. Kami hadir agar JSKM bukan satu suara sahaja.', 3),
(233, 2, 3, 'e1_n3_s7', 'Aku Temenggung Jugah dari Sarawak. Kami hendak bukti bahawa suara kami dihormati, bukan janji.', 4),
(234, NULL, 3, 'e1_n3_s7', 'Bilik ini mesti menunjukkan empat perkara, iaitu delegasi Sabah, delegasi Sarawak, dokumen mesyuarat di tengah meja dan peta wilayah di dinding.', 5),
(235, 5, 3, 'e1_n3_s7', 'Cari semuanya, Ghazali. Aku hendak bukti bahawa JSKM benar-benar mewakili semua pihak.', 6),
(236, 3, 3, 'e1_n3_s7', 'Ghazali, apa tugas jawatankuasa ini sebenarnya? Orang kampung bertanya kepada saya.', 7),
(237, 16, 3, 'e1_n3_s8', 'Kertas arahan ini baru dikeluarkan, Ghazali. Ia menyebut tugas suruhanjaya ini dengan jelas.', 1),
(238, NULL, 3, 'e1_n3_s8', 'Aku membacanya. Suruhanjaya dibentuk untuk menemu ramah penduduk dan meneliti memorandum mereka di Sarawak dan Sabah.', 2),
(239, 5, 3, 'e1_n3_s8', 'Maka tugasnya bukan menyediakan perlembagaan dan bukan mengesahkan persetujuan. Nyahkod tugas yang benar.', 3),
(240, NULL, 3, 'e1_n3_s8', 'Aku faham. Tugas itu pula menentukan siapakah yang kita jumpa dan apa yang kita tulis dalam laporan.', 4),
(241, 16, 3, 'e1_n3_s8', 'Ghazali, jikalau penduduk takut bersuara di hadapan pegawai, apa yang patut kita lakukan?', 5),
(242, 41, 3, 'e1_n3_s9', 'Ghazali, tiga laporan di atas meja ini nampak serupa namun isinya bercanggah. Satu berkata semua setuju, satu berkata semua menolak.', 1),
(243, NULL, 3, 'e1_n3_s9', 'Laporan Cobbold yang sebenar menyebut dua pertiga menyokong. Tidak semua, dan tidak ada yang menolak sepenuhnya.', 2),
(244, 5, 3, 'e1_n3_s9', 'Pilih laporan yang betul, Ghazali. Satu kesilapan akan dibangkitkan oleh akhbar esok pagi.', 3),
(245, 7, 3, 'e1_n3_s9', 'Dua pertiga bukan semua. Kami, SUPP, menolak dan kami hendak suara kami dicatat.', 4),
(246, 7, 3, 'e1_n3_s9', 'Ghazali, adakah laporan itu akan menyebut kami menolak?', 5),
(247, 5, 3, 'e1_n3_s10', 'Setiap pihak duduk di tempat masing-masing. Ghazali, pastikan kerusi dan dokumen benar.', 1),
(248, NULL, 3, 'e1_n3_s10', 'Tempat duduk wakil British, tempat duduk wakil Persekutuan, dan rangka perlembagaan di atas meja. Itulah tiga bukti yang aku cari.', 2),
(249, 6, 3, 'e1_n3_s10', 'Sarawak hendak rangka ini melindungi kepentingan kami. Tulis jelas, usah abaikan.', 3),
(250, 3, 3, 'e1_n3_s10', 'Sabah pun begitu. Kami tidak hendak hanya janji lisan.', 4),
(251, 5, 3, 'e1_n3_s10', 'Ghazali, jikalau satu pihak menolak membaca rangka itu, apa yang patut kita buat?', 5),
(252, 4, 3, 'e1_n3_s11', 'Ghazali, rakyat Singapura telah menyatakan pendirian mereka. Nota ini mencatat bagaimanakah mereka berbuat demikian.', 1),
(253, NULL, 3, 'e1_n3_s11', 'Nota menyebut mereka mengundi untuk menyatakan pendirian tentang pembentukan Malaysia. Aku perlu menamakan cara itu dengan tepat.', 2),
(254, 5, 3, 'e1_n3_s11', 'Ingat, bukan pemasyhuran dan bukan perjanjian. Nama yang benar sahaja, Ghazali.', 3),
(255, NULL, 3, 'e1_n3_s11', 'Ia kaedah rakyat sendiri menyatakan pendirian secara terus, lalu angkanya dikira.', 4),
(256, 4, 3, 'e1_n3_s11', 'Ghazali, apa yang dicatat jikalau rakyat Singapura menolak?', 5),
(257, 5, 3, 'e1_n3_s12', 'Tiga fail serupa, Ghazali. Hanya satu yang betul untuk Perjanjian Malaysia.', 1),
(258, NULL, 3, 'e1_n3_s12', 'Satu berlabel Adelphi, satu berlabel UNMM, satu lagi berlabel Marlborough House. Aku perlu memilih yang betul.', 2),
(259, 5, 3, 'e1_n3_s12', 'Fail yang salah akan dihantar ke London, dan Tunku akan memalukan kita di hadapan British.', 3),
(260, NULL, 3, 'e1_n3_s12', 'Aku telah pasti. Fail perjanjian mesti menyebut tempat dan tarikh penandatanganan.', 4),
(261, 5, 3, 'e1_n3_s12', 'Satu soalan lagi, Ghazali. Selepas perjanjian ini ditandatangani, siapakah lagi yang perlu mengesahkannya?', 5),
(262, 5, 3, 'e1_n3_s13', 'Empat badan, iaitu JSKM, Suruhanjaya Cobbold, JAK dan UNMM. Tiap-tiap satu ada tugas berbeza.', 1),
(263, NULL, 3, 'e1_n3_s13', 'JSKM meyakinkan pemimpin. Cobbold bertanya kepada penduduk. JAK menyediakan perlembagaan. UNMM mengesahkan persetujuan.', 2),
(264, 5, 3, 'e1_n3_s13', 'Engkau telah tahu, namun padankan dengan benar. Ahli UNMM akan menyemaknya.', 3),
(265, 19, 3, 'e1_n3_s13', 'Encik Ghazali, saya dari UNMM. Mengapakah tugas kami berbeza daripada Cobbold?', 4),
(266, 5, 3, 'e1_n3_s14', 'Pemasyhuran diadakan serentak di empat tempat. Ghazali, tunjukkan empat tempat itu pada peta.', 1),
(267, NULL, 3, 'e1_n3_s14', 'Kuala Lumpur, Kuching, Kota Kinabalu dan City Hall di Singapura. Aku akan menandakan keempat-empatnya pada peta.', 2),
(268, 1, 3, 'e1_n3_s14', 'Ghazali, setiap tempat mesti benar. Bukan mudah menyatukan empat wilayah dalam satu hari.', 3),
(269, 18, 3, 'e1_n3_s14', 'Encik Ghazali, kenapa Pemasyhuran perlu diadakan di empat tempat?', 4),
(270, 5, 3, 'e1_n3_s15', 'Ghazali, Malaysia baru dilahirkan, namun telah ada yang mahu merobohkannya. Padankan siapakah dengan cabaran apa.', 1),
(271, NULL, 3, 'e1_n3_s15', 'SUPP mahu persekutuan sendiri. Indonesia melancarkan konfrontasi dari 1963 hingga 1966. Filipina menuntut Sabah. Brunei menolak penyertaan.', 2),
(272, 5, 3, 'e1_n3_s15', 'Benar, namun pasangkan dengan tepat. Jikalau tersilap, kita menuduh pihak yang salah.', 3),
(273, 1, 3, 'e1_n3_s15', 'Ghazali, adakah semua cabaran ini bermakna Malaysia gagal?', 4),
(274, 5, 3, 'e1_n3_s16', 'Lapan langkah dari Adelphi hingga Pemasyhuran. Susun, Ghazali, agar sejarah ini kemas.', 1),
(275, NULL, 3, 'e1_n3_s16', 'Adelphi, JSKM, Cobbold dibentuk, laporan Cobbold, JAK, Perjanjian Malaysia, UNMM dan Pemasyhuran. Tarikhnya aku telah hafal.', 2),
(276, 5, 3, 'e1_n3_s16', 'Engkau tahu, Ghazali. Selama ini aku tidak pernah berterima kasih kerana engkau yang menyimpan semua ini.', 3),
(277, 5, 3, 'e1_n3_s16', 'Ghazali, apa yang paling engkau pelajari daripada perjalanan ini?', 4),
(278, 21, 201, NULL, 'Aku Tok Penglipur Lara. Tugasku mencatat dan menurunkan cerita negeri, dan setiap negeri ada lebih daripada satu cerita yang mesti aku sebut dengan jujur, {nama}.', 1),
(279, 21, 201, NULL, 'Aku belajar bahawa nama negeri, ketuanya, pusatnya dan lagunya menyimpan sejarah dan kemegahan. Mengenalinya menjadikan kita bangga akan warisan negeri.', 2),
(280, 21, 201, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pencerita tua yang membawa sebuah buku kosong. Setiap negeri akan berbalah tentang ceritanya. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(281, 28, 201, 'e2_n1_s1', 'Tok, datuk saya kata Perlis dari perkataan Siam. Orang sebelah kata dari peristiwa Raja Syed Hussin. Siapakah benar?', 1),
(282, 18, 201, 'e2_n1_s1', 'Tok, kelapa itu hanyut dari hulu parit. Tulisan di catatan ini pun pudar.', 2),
(283, NULL, 201, 'e2_n1_s1', 'Kedua-duanya ada dalam catatan. Baca dahulu, usah teka.', 3),
(284, 28, 201, 'e2_n1_s1', 'Jikalau Tok salah tulis, satu kampung akan menghafal yang salah.', 4),
(285, 18, 201, 'e2_n1_s1', 'Selepas ini kita ke selatan, Tok. Di sana orang pernah memasang perangkap besar.', 5),
(286, 28, 201, 'e2_n1_s1', 'Tok, apa lagi cerita tentang nama Perlis selain perkataan Siam itu?', 6),
(287, 29, 201, 'e2_n1_s2', 'Kedah dari ''kheddah'', perangkap gajah! Datuk saya memburu gajah di sini.', 1),
(288, 30, 201, 'e2_n1_s2', 'Salah! Dari ''qadah'', cawan berkaki yang pedagang Arab jual di Alam Melayu!', 2),
(289, 18, 201, 'e2_n1_s2', 'Tok, di dinding itu ada tulisan Tamil. Nama dalam tulisan itu lain pula.', 3),
(290, NULL, 201, 'e2_n1_s2', 'Tiga catatan, tiga bahasa. Kita padankan agar tiada yang tersisih.', 4),
(291, 18, 201, 'e2_n1_s2', 'Selepas ini kita ke pulau yang banyak pokok dan pinang, Tok.', 5),
(292, 29, 201, 'e2_n1_s2', 'Tok, apa nama Kedah dalam tulisan Tamil itu?', 6),
(293, 27, 201, 'e2_n1_s3', 'Orang Kedah panggil pulau ini Tanjong Penaga kerana banyak pokok penaga. Nama asalnya Pulo Ka Satu!', 1),
(294, 30, 201, 'e2_n1_s3', 'Salah! Pulau pinang, buah pinang itu barang dagangan kami!', 2),
(295, 56, 201, 'e2_n1_s3', 'Di Perak, nama negeri dari kilat ikan dalam air. Atau dari bijih timah putih berkilat!', 3),
(296, 18, 201, 'e2_n1_s3', 'Tok, ada dua negeri di jeti ini. Usah bercampur.', 4),
(297, NULL, 201, 'e2_n1_s3', 'Padankan, agar tiada negeri bercampur.', 5),
(298, 27, 201, 'e2_n1_s3', 'Tok, peribahasa apa untuk kenal negeri sendiri?', 6),
(299, 40, 201, 'e2_n1_s4', 'Tok, murid-murid keliru. Mana ibu negeri dan mana bandar diraja?', 1),
(300, 18, 201, 'e2_n1_s4', 'Tok, titik merah ialah ibu negeri dan titik kuning bandar diraja, kata legenda peta ini.', 2),
(301, NULL, 201, 'e2_n1_s4', 'Ibu negeri pusat pentadbiran. Bandar diraja ada warisan sejarah seperti istana, bangunan pembesar, kedai lama, muzium dan monumen.', 3),
(302, 40, 201, 'e2_n1_s4', 'Jikalau tersilap, anak murid akan menghafal yang salah.', 4),
(303, 18, 201, 'e2_n1_s4', 'Esok kita dengar radio kampung, Tok. Ada lagu yang dimainkan setiap pagi.', 5),
(304, 18, 201, 'e2_n1_s4', 'Seingat saya, Kangar (Perlis) berpasangan dengan Arau, Alor Setar (Kedah) berpasangan dengan Anak Bukit, Ipoh (Perak) berpasangan dengan Kuala Kangsar.', 6),
(305, 40, 201, 'e2_n1_s4', 'Tok, bagaimanakah kita memelihara istana atau bangunan pentadbiran lama?', 7),
(306, 39, 201, 'e2_n1_s5', 'Tok, majlis bermula sekejap lagi. Lagu Kedah mesti dimainkan dahulu.', 1),
(307, 18, 201, 'e2_n1_s5', 'Tok, ada kaset bertulis empat tajuk di atas rak.', 2),
(308, NULL, 201, 'e2_n1_s5', 'Tajuk lagu negeri tidak boleh ditukar. Itu lambang kemegahan.', 3),
(309, 39, 201, 'e2_n1_s5', 'Jikalau saya main lagu negeri lain, tetamu akan rasa dihina.', 4),
(310, 18, 201, 'e2_n1_s5', 'Selepas ini kita ke kuala sungai. Di sana ada bunyi pedagang lama, Tok.', 5),
(311, 39, 201, 'e2_n1_s5', 'Tok, lagu Perak, Perlis dan Pulau Pinang pula, apa tajuknya?', 6),
(312, 27, 201, 'e2_n1_s6', 'Selangor dari pokok mentagau! Pedagang menyebut kuala selangau, lalu jadi Kuala Selangor.', 1),
(313, 8, 201, 'e2_n1_s6', 'Bukan, dari serangga selangur yang banyak di sungai!', 2),
(314, 54, 201, 'e2_n1_s6', 'Negeri kami dari sembilan luak. Kata ''negeri'' pun dari ''nagari''.', 3),
(315, 18, 201, 'e2_n1_s6', 'Tok, ada tahun tertulis di piagam penghulu itu.', 4),
(316, NULL, 201, 'e2_n1_s6', 'Padankan, usah tinggalkan satu pun.', 5),
(317, 8, 201, 'e2_n1_s6', 'Seingat saya, Nagari berpasangan dengan Wilayah dalam dialek Minangkabau.', 6),
(318, 54, 201, 'e2_n1_s6', 'Tok, sebut luak-luak asal Negeri Sembilan itu.', 7),
(319, 30, 201, 'e2_n1_s7', 'Melaka dari ''Malakat'', tempat pedagang berhimpun!', 1),
(320, 8, 201, 'e2_n1_s7', 'Dari pokok tempat Parameswara berehat, ketika pelanduk putih kecil menendang anjing pemburuannya!', 2),
(321, 55, 201, 'e2_n1_s7', 'Dan Johor dari ''jauhar'', batu permata. Dalam Sulalatus Salatin pula Ujong Tanah!', 3),
(322, 18, 201, 'e2_n1_s7', 'Tok, empat cerita, dua negeri.', 4),
(323, NULL, 201, 'e2_n1_s7', 'Padankan, agar halaman buku tidak salah.', 5),
(324, 55, 201, 'e2_n1_s7', 'Tok, ''Malakat'' itu daripada bahasa apa?', 6),
(325, 40, 201, 'e2_n1_s8', 'Tok, fail ini habis bercampur. Saya hampir menghantar Klang sebagai ibu negeri.', 1),
(326, 18, 201, 'e2_n1_s8', 'Tok, Klang ada istana dan bangunan lama. Ibu negerinya pusat pentadbiran.', 2),
(327, NULL, 201, 'e2_n1_s8', 'Bandar Melaka ialah ibu negeri. Peta tidak menandakan bandar diraja di sana.', 3),
(328, 40, 201, 'e2_n1_s8', 'Jikalau tersilap, majlis tersasar.', 4),
(329, 18, 201, 'e2_n1_s8', 'Esok kita dengar kaset lagi, Tok. Empat lagu dari empat negeri.', 5),
(330, 18, 201, 'e2_n1_s8', 'Seingat saya, Shah Alam (Selangor) berpasangan dengan Klang.', 6),
(331, 40, 201, 'e2_n1_s8', 'Tok, mengapakah ibu negeri berkembang?', 7),
(332, 39, 201, 'e2_n1_s9', 'Tok, saya perlukan lagu Johor. Dua kaset ini kelihatan serupa.', 1),
(333, 18, 201, 'e2_n1_s9', 'Tok, satu kaset ada nama pengganti. Pandang tajuknya betul-betul.', 2),
(334, NULL, 201, 'e2_n1_s9', 'Tajuk lagu Johor menyebut nama negerinya.', 3),
(335, 39, 201, 'e2_n1_s9', 'Jikalau tersilap, Sultan Johor tersinggung.', 4),
(336, 18, 201, 'e2_n1_s9', 'Sesungguhnya, kita ke pantai timur selepas ini. Di sana ada pelangi dan taring besar, kata orang.', 5),
(337, 39, 201, 'e2_n1_s9', 'Tok, tiga lagu lain itu milik negeri mana?', 6),
(338, 8, 201, 'e2_n1_s10', 'Pahang dari pokok mahang! Dalam Sulalatus Salatin ia Inderapura atau Pura, dan pura itu bandar.', 1),
(339, 27, 201, 'e2_n1_s10', 'Terengganu dari ''taring anu'', taring besar di Pulau Duyong! Atau ''terangnya ganu'', pelangi!', 2),
(340, 55, 201, 'e2_n1_s10', 'Kelantan dari ''kilatan'', cahaya terang yang orang Patani nampak. Orang pantai kata gelam hutan!', 3),
(341, 18, 201, 'e2_n1_s10', 'Tok, enam cerita dalam satu pantai.', 4),
(342, NULL, 201, 'e2_n1_s10', 'Padankan satu persatu.', 5),
(343, 27, 201, 'e2_n1_s10', 'Seingat saya, Terangnya ganu berpasangan dengan Pelangi.', 6),
(344, 55, 201, 'e2_n1_s10', 'Tok, ''kilatan'' itu cahaya yang dilihat oleh siapakah?', 7),
(345, 40, 201, 'e2_n1_s11', 'Tok, empat kad ini bercampur. Pekan bukan pusat pentadbiran.', 1),
(346, 18, 201, 'e2_n1_s11', 'Tok, Pekan berwarna kuning di peta, ada istana. Kuantan merah.', 2),
(347, NULL, 201, 'e2_n1_s11', 'Terengganu dan Kelantan hanya ada ibu negeri pada peta.', 3),
(348, 40, 201, 'e2_n1_s11', 'Jadi hanya Pahang ada kedua-duanya?', 4),
(349, 18, 201, 'e2_n1_s11', 'Selepas ini lagu, Tok. Kata orang, dua negeri berkongsi tajuk yang sama.', 5),
(350, 40, 201, 'e2_n1_s11', 'Tok, apa yang ada di bandar diraja?', 6),
(351, 27, 201, 'e2_n1_s12', 'Lagu ini lagu negeri saya, ''Selamat Sultan''!', 1),
(352, 8, 201, 'e2_n1_s12', 'Salah! Lagu negeri saya juga ''Selamat Sultan''!', 2),
(353, 18, 201, 'e2_n1_s12', 'Tok, Pahang pun ada lagu, ''Allah Selamatkan Sultan Kami''.', 3),
(354, NULL, 201, 'e2_n1_s12', 'Semua benar. Ini nota yang mesti dinyahkod.', 4),
(355, 18, 201, 'e2_n1_s12', 'Kita menyeberang laut selepas ini, Tok. Ke Borneo, ke tanah yang ada gunung.', 5),
(356, 27, 201, 'e2_n1_s12', 'Tok, lagu Pahang itu tajuknya apa?', 6),
(357, 55, 201, 'e2_n1_s13', 'Tok, orang tanya nama Sarawak dan Sabah. Dokumen lama bercampur.', 1),
(358, 34, 201, 'e2_n1_s13', 'Sarawak dari Sungai Serak yang berubah menjadi Sungai Sarawak, bersempena sejenis bijih galian!', 2),
(359, 18, 201, 'e2_n1_s13', 'Tok, ada logam ''cerava'' juga, panggilan Portugis.', 3),
(360, NULL, 201, 'e2_n1_s13', 'Pilih dokumen yang betul.', 4),
(361, 55, 201, 'e2_n1_s13', 'Sabah tercatat dalam dokumen ''Maharajah of Sabah'' pada tahun tertentu, dan dikaitkan dengan sejenis buah.', 5),
(362, 55, 201, 'e2_n1_s13', 'Tok, yang mana dokumen yang betul?', 6),
(363, 8, 201, 'e2_n1_s14', 'Mengapakah ''Kuala Lumpur''? Bukankah bunyinya pelik?', 1),
(364, 30, 201, 'e2_n1_s14', 'Dan mengapakah ''Labuan''?', 2),
(365, 18, 201, 'e2_n1_s14', 'Tok, ada kotak ''Tahukah anda'' di buku. Tiga nama, tiga cerita.', 3),
(366, NULL, 201, 'e2_n1_s14', 'Padankan dahulu. Dan ingat, Wilayah Persekutuan tiada ibu negeri dan bandar diraja.', 4),
(367, 30, 201, 'e2_n1_s14', 'Seingat saya, Kuala Lumpur berpasangan dengan Muara berlumpur akibat melombong bijih timah.', 5),
(368, 34, 201, 'e2_n1_s14', 'Tok, siapakah yang bernama Putra pada Putrajaya itu?', 6),
(369, 40, 201, 'e2_n1_s15', 'Ibu negeri kami Kuching. Pusat pentadbiran.', 1),
(370, 53, 201, 'e2_n1_s15', 'Kami Kota Kinabalu, pusat pekerjaan dan pendidikan.', 2),
(371, 18, 201, 'e2_n1_s15', 'Tok, di peta ada titik merah di Kuching dan Kota Kinabalu, namun tiada titik kuning.', 3),
(372, NULL, 201, 'e2_n1_s15', 'Peta hanya menanda ibu negeri bagi kedua-duanya.', 4),
(373, 18, 201, 'e2_n1_s15', 'Selepas ini lagu terakhir, Tok. Satu tentang tanah air, satu tentang ibu pertiwi.', 5),
(374, 53, 201, 'e2_n1_s15', 'Seingat saya, Ibu negeri berkembang kerana berpasangan dengan Pembangunan pentadbiran, kemudahan asas dan institusi pendidikan.', 6),
(375, 40, 201, 'e2_n1_s15', 'Tok, bagaimanakah kita menghargai pusat pentadbiran dan kota warisan?', 7),
(376, 39, 201, 'e2_n1_s16', 'Tok, saya perlukan lagu Sabah. Tiga kaset lagi bercampur.', 1),
(377, 18, 201, 'e2_n1_s16', 'Tok, satu tajuk menyebut ''Tanah Airku''. Satu lagi ''Ibu Pertiwiku''.', 2),
(378, NULL, 201, 'e2_n1_s16', 'Satu daripada itu milik Sarawak. Satu lagi milik Sabah.', 3),
(379, 39, 201, 'e2_n1_s16', 'Dan Wilayah Persekutuan?', 4),
(380, 18, 201, 'e2_n1_s16', 'Selepas ini kita ke istana. Para ketua negeri telah tiba.', 5),
(381, 18, 201, 'e2_n1_s16', 'Seingat saya, jawapannya ialah Sabah Tanah Airku.', 6),
(382, 39, 201, 'e2_n1_s16', 'Tok, Ibu Pertiwiku dan Maju dan Sejahtera itu milik siapakah?', 7),
(383, 40, 201, 'e2_n1_s17', 'Tok, ketua-ketua negeri akan tiba. Kad gelaran bercampur. Satu kesilapan dan kita memalukan negara.', 1),
(384, 18, 201, 'e2_n1_s17', 'Tok, ada gambar upacara pertabalan di dinding. Setiap ketua negeri ada gelaran tersendiri.', 2),
(385, NULL, 201, 'e2_n1_s17', 'Ketua negeri tonggak utama pemerintahan. Gelaran yang berbeza menunjukkan keunikan negara kita.', 3),
(386, 40, 201, 'e2_n1_s17', 'Dan ketua Wilayah Persekutuan? Siapakah dia?', 4),
(387, 18, 201, 'e2_n1_s17', 'Selepas ini kita ke pentas pesta, Tok. Buku mesti dilengkapkan.', 5),
(388, 18, 201, 'e2_n1_s17', 'Seingat saya, Sultan berpasangan dengan Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan, Yang di-Pertua Negeri berpasangan dengan Pulau Pinang, Melaka, Sarawak dan Sabah.', 6),
(389, 40, 201, 'e2_n1_s17', 'Tok, mengapakah kita perlu mengenali ketua negeri?', 7),
(390, 17, 201, 'e2_n1_s18', 'Tok, buku ini mencatat dua cerita bagi setiap negeri. Mengapakah?', 1),
(391, NULL, 201, 'e2_n1_s18', 'Kerana nama negeri dicatat secara lisan dan tulisan.', 2),
(392, 18, 201, 'e2_n1_s18', 'Tok, ada tiga petunjuk di pentas, jata, bendera dan radio lagu negeri.', 3),
(393, 17, 201, 'e2_n1_s18', 'Tok perlu tunjukkan kepada penonton. Ini lambang kemegahan dan kedaulatan negeri.', 4),
(394, NULL, 201, 'e2_n1_s18', '''Tak kenal maka tak cinta.'' Mengenali nama, bendera dan jata menyuburkan rasa sayang akan negara.', 5),
(395, 17, 201, 'e2_n1_s18', 'Tok, mengapakah kita perlu menghormati lambang negeri?', 6),
(396, 58, 202, NULL, 'Aku Pegawai Istiadat Negara. Tiga hari lagi majlis bermula dan seseorang cuba memalukan aku, {nama}. Setiap kad dan kaset mesti betul.', 1),
(397, 58, 202, NULL, 'Aku belajar bahawa nama negeri, ketua, ibu negeri, lagu dan lambangnya ialah identiti. Satu kesilapan boleh memalukan sebuah negeri.', 2),
(398, 58, 202, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pegawai yang diburu waktu. Ada orang menyabot istiadat. Teliti setiap kad dan dengar bisikan Tok.', 3),
(399, 57, 202, 'e2_n2_s1', 'Pegawai Istiadat, kad ketua Wilayah Persekutuan hilang. Tiga hari lagi istiadat. Tuan hamba sanggup?', 1),
(400, 21, 202, 'e2_n2_s1', 'Dia tersenyum terlalu lebar. Perhatikan jarinya.', 2),
(401, NULL, 202, 'e2_n2_s1', 'Saya akan nyahkod nota sisa dalam fail ini.', 3),
(402, 57, 202, 'e2_n2_s1', 'Jikalau tersilap, tuan hamba yang malu.', 4),
(403, 21, 202, 'e2_n2_s1', 'Esok kita ke bilik penyusun gelaran. Banyak kad bakal bercampur.', 5),
(404, 21, 202, 'e2_n2_s1', 'Seingat saya, jawapannya ialah Yang di-Pertuan Agong.', 6),
(405, 57, 202, 'e2_n2_s1', 'Dan ibu negeri Wilayah Persekutuan pula, apa nama bandarnya?', 7),
(406, 59, 202, 'e2_n2_s2', 'Pegawai, papan nama Kuala Lumpur, Labuan dan Putrajaya tercabut dan bercampur.', 1),
(407, 21, 202, 'e2_n2_s2', 'Setiap nama ada kisahnya. Padankan, usah tebak.', 2),
(408, NULL, 202, 'e2_n2_s2', 'Siapakah yang membuka papan ini?', 3),
(409, 59, 202, 'e2_n2_s2', 'Seseorang dengan kunci pejabat.', 4),
(410, 21, 202, 'e2_n2_s2', 'Kunci itu bukan kunci biasa. Jejaknya ke selatan.', 5),
(411, 21, 202, 'e2_n2_s2', 'Seingat saya, Kuala Lumpur berpasangan dengan Muara berlumpur akibat melombong bijih timah, Putrajaya berpasangan dengan Tunku Abdul Rahman Putra, jaya bermaksud kemenangan atau menuju ke puncak.', 6),
(412, 59, 202, 'e2_n2_s2', 'Jadi Putrajaya diambil daripada seorang pemimpin?', 7),
(413, 40, 202, 'e2_n2_s3', 'Gelaran ketua negeri bercampur. Sultan, Raja, Yang di-Pertuan Besar, Yang di-Pertua Negeri.', 1),
(414, 21, 202, 'e2_n2_s3', 'Ketua negeri ialah tonggak pemerintahan. Gelaran berbeza menunjukkan keunikan negara kita.', 2),
(415, NULL, 202, 'e2_n2_s3', 'Satu kad salah dan satu negeri tersinggung.', 3),
(416, 21, 202, 'e2_n2_s3', 'Usah serahkan kad kepadanya. Esok kita mohon pertolongan seorang pembantu Yang di-Pertua Negeri.', 4),
(417, 21, 202, 'e2_n2_s3', 'Seingat saya, Sultan berpasangan dengan Kedah, Perak, Selangor, Johor, Pahang, Terengganu dan Kelantan, Yang di-Pertua Negeri berpasangan dengan Pulau Pinang, Melaka, Sarawak dan Sabah.', 5),
(418, 57, 202, 'e2_n2_s3', 'Mengapakah gelaran itu penting? Saya boleh tolong susun.', 6),
(419, 40, 202, 'e2_n2_s4', 'Tuan Pegawai, tuan saya ialah Yang di-Pertua Negeri. Saya perlukan dokumen senarai negeri yang menggunakan gelaran itu.', 1),
(420, 21, 202, 'e2_n2_s4', 'Hati-hati. Dokumen palsu pun ada di atas meja.', 2),
(421, NULL, 202, 'e2_n2_s4', 'Saya semak sendiri.', 3),
(422, 40, 202, 'e2_n2_s4', 'Jikalau salah, tuan saya tidak dijemput ke tempat yang benar.', 4),
(423, 21, 202, 'e2_n2_s4', 'Esok kita ke Selangor. Seseorang meninggalkan jejak di kuala sungai.', 5),
(424, 21, 202, 'e2_n2_s4', 'Seingat saya, jawapannya ialah Pulau Pinang, Melaka, Sarawak dan Sabah.', 6),
(425, 40, 202, 'e2_n2_s4', 'Wilayah Persekutuan pula, siapakah ketuanya?', 7),
(426, 27, 202, 'e2_n2_s5', 'Selangor dari pokok mentagau! Pedagang menyebut kuala selangau.', 1),
(427, 54, 202, 'e2_n2_s5', 'Negeri kami sembilan luak, dan ''negeri'' dari ''nagari''.', 2),
(428, 21, 202, 'e2_n2_s5', 'Jejak Zahar berhenti di sini. Nyahkod piagam itu, mungkin dia meninggalkan sesuatu.', 3),
(429, NULL, 202, 'e2_n2_s5', 'Saya perlu nama yang tepat untuk kad pengacara.', 4),
(430, 21, 202, 'e2_n2_s5', 'Selepas ini kita ke Melaka. Seseorang meninggalkan tanda di bawah sebatang pokok.', 5),
(431, 54, 202, 'e2_n2_s5', 'Sebut luak asal Negeri Sembilan!', 6),
(432, 30, 202, 'e2_n2_s6', 'Melaka dari Malakat, tempat pedagang berhimpun.', 1),
(433, 8, 202, 'e2_n2_s6', 'Dari pokok tempat Parameswara berehat melihat pelanduk putih.', 2),
(434, 21, 202, 'e2_n2_s6', 'Nota di akar ini milik Zahar. Nyahkod sebelum dia kembali.', 3),
(435, NULL, 202, 'e2_n2_s6', 'Ia menyebut Johor.', 4),
(436, 21, 202, 'e2_n2_s6', 'Kita ke bilik pejabat daerah. Ada fail yang dicuri.', 5),
(437, 8, 202, 'e2_n2_s6', 'Seingat saya, jawapannya ialah Ujong Tanah.', 6),
(438, 30, 202, 'e2_n2_s6', 'Dan Jauhar? Apa maksudnya?', 7),
(439, 40, 202, 'e2_n2_s7', 'Pegawai, fail ibu negeri dan bandar diraja bercampur selepas Zahar datang.', 1),
(440, 21, 202, 'e2_n2_s7', 'Ibu negeri pusat pentadbiran. Bandar diraja ada istana, bangunan pembesar, kedai lama, muzium dan monumen.', 2),
(441, NULL, 202, 'e2_n2_s7', 'Saya padankan semula.', 3),
(442, 40, 202, 'e2_n2_s7', 'Dan Bandar Melaka tiada bandar diraja pada peta.', 4),
(443, 21, 202, 'e2_n2_s7', 'Lalu kaset lagu di bilik radio. Tolong periksa suis.', 5),
(444, 21, 202, 'e2_n2_s7', 'Seingat saya, Shah Alam (Selangor) berpasangan dengan Klang, Seremban (Negeri Sembilan) berpasangan dengan Seri Menanti, Johor Bahru (Johor) berpasangan dengan Bandar Maharani.', 6),
(445, 40, 202, 'e2_n2_s7', 'Mengapakah ibu negeri berkembang?', 7),
(446, 39, 202, 'e2_n2_s8', 'Pegawai, kaset ini tiada label. Zahar baru keluar dari bilik ini.', 1),
(447, 21, 202, 'e2_n2_s8', 'Lagu negeri lambang kemegahan. Padankan label dengan negeri.', 2),
(448, NULL, 202, 'e2_n2_s8', 'Tengah dan selatan, iaitu Selangor, Negeri Sembilan, Melaka, Johor.', 3),
(449, 39, 202, 'e2_n2_s8', 'Jikalau tersilap, tetamu terhina.', 4),
(450, 21, 202, 'e2_n2_s8', 'Esok kita ke utara. Ada sebuah peti pos yang menyimpan nota.', 5),
(451, 21, 202, 'e2_n2_s8', 'Seingat saya, Duli Yang Maha Mulia berpasangan dengan Selangor, Melaka Maju Jaya berpasangan dengan Melaka.', 6),
(452, 39, 202, 'e2_n2_s8', 'Mengapakah lagu negeri penting?', 7),
(453, 28, 202, 'e2_n2_s9', 'Perlis dari ''prow-lowy'', kelapa hanyut. Ada juga cerita ''peroleh''.', 1),
(454, 56, 202, 'e2_n2_s9', 'Perak dari kilatan ikan atau bijih timah putih berkilat.', 2),
(455, 21, 202, 'e2_n2_s9', 'Nota di peti pos itu mempunyai empat kad. Padankan.', 3),
(456, NULL, 202, 'e2_n2_s9', 'Zahar hendak saya tersilap di hadapan tetamu.', 4),
(457, 21, 202, 'e2_n2_s9', 'Jam hampir tengah hari. Sebuah jeti menanti.', 5),
(458, 56, 202, 'e2_n2_s9', 'Seingat saya, Peroleh berpasangan dengan Mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail.', 6),
(459, 28, 202, 'e2_n2_s9', 'Siapakah Raja Syed Hussin itu?', 7),
(460, 30, 202, 'e2_n2_s10', 'Kedah dari ''qadah'', cawan dagang Arab. Orang kata juga dari ''kheddah'', perangkap gajah.', 1),
(461, 27, 202, 'e2_n2_s10', 'Pulau ini dahulu Pulo Ka Satu. Orang Kedah panggil Tanjong Penaga.', 2),
(462, 21, 202, 'e2_n2_s10', 'Seseorang menyembunyikan sampul di jeti ini. Padankan nama-nama itu, pasti sampul itu berdekatan.', 3),
(463, NULL, 202, 'e2_n2_s10', 'Pinang juga barang dagangan penting.', 4),
(464, 21, 202, 'e2_n2_s10', 'Maka selepas ini kita ke pejabat daerah. Pegawai itu mengesyaki Zahar.', 5),
(465, 27, 202, 'e2_n2_s10', 'Seingat saya, Qadah berpasangan dengan Cawan atau gelas berkaki yang dijual pedagang Arab.', 6),
(466, 27, 202, 'e2_n2_s10', 'Mengapakah pinang penting pada nama pulau?', 7),
(467, 40, 202, 'e2_n2_s11', 'Pegawai Istiadat, saya perlukan dokumen ibu negeri dan bandar diraja Perlis, Kedah, Perak dan Pulau Pinang.', 1),
(468, 21, 202, 'e2_n2_s11', 'Salah satu fail mempunyai cop Zahar. Berhati-hati.', 2),
(469, NULL, 202, 'e2_n2_s11', 'Saya semak setiap baris.', 3),
(470, 40, 202, 'e2_n2_s11', 'Jikalau salah, kami menghantar jemputan ke bandar yang salah.', 4),
(471, 21, 202, 'e2_n2_s11', 'Selepas ini kita periksa kaset lagu utara. Zahar belum selesai.', 5),
(472, 21, 202, 'e2_n2_s11', 'Seingat saya, jawapannya ialah Kangar dan Arau, Alor Setar dan Anak Bukit, Ipoh dan Kuala Kangsar, George Town.', 6),
(473, 40, 202, 'e2_n2_s11', 'Mengapakah bandar diraja penting?', 7),
(474, 39, 202, 'e2_n2_s12', 'Kaset ini bertajuk ''Aamiin-Aamiin''. Tidak ada label negeri.', 1),
(475, 21, 202, 'e2_n2_s12', 'Nyahkod nota ini. Satu negeri di utara sahaja memiliki lagu itu.', 2),
(476, NULL, 202, 'e2_n2_s12', 'Di negeri itu ketuanya bergelar Raja.', 3),
(477, 39, 202, 'e2_n2_s12', 'Dan Perak, Kedah, Pulau Pinang?', 4),
(478, 21, 202, 'e2_n2_s12', 'Kita ke pantai timur esok. Zahar telah ke sana awal.', 5),
(479, 39, 202, 'e2_n2_s12', 'Lagu Perak, Kedah dan Pulau Pinang itu tajuknya apa?', 6),
(480, 27, 202, 'e2_n2_s13', 'Terengganu dari ''taring anu'', taring besar di Pulau Duyong. Ada juga ''terangnya ganu'', pelangi.', 1),
(481, 8, 202, 'e2_n2_s13', 'Pahang dari pokok mahang. Dalam Sulalatus Salatin ia Inderapura atau Pura, bandar.', 2),
(482, 55, 202, 'e2_n2_s13', 'Kelantan dari ''kilatan'', cahaya terang. Orang pantai kata gelam hutan.', 3),
(483, 21, 202, 'e2_n2_s13', 'Padankan setiap cerita. Peta Zahar tentu menyembunyikan sesuatu di sana.', 4),
(484, 21, 202, 'e2_n2_s13', 'Selepas ini kita ke bilik peta. Empat nama bandar akan bercampur.', 5),
(485, 55, 202, 'e2_n2_s13', 'Seingat saya, Terangnya ganu berpasangan dengan Pelangi.', 6),
(486, 55, 202, 'e2_n2_s13', 'Kilatan itu cahaya yang dilihat oleh siapakah?', 7),
(487, 40, 202, 'e2_n2_s14', 'Pegawai Istiadat, empat kad bercampur. Pekan bukan pusat pentadbiran.', 1),
(488, 21, 202, 'e2_n2_s14', 'Pekan berwarna kuning di peta, ada istana. Kuantan merah.', 2),
(489, NULL, 202, 'e2_n2_s14', 'Terengganu dan Kelantan hanya ada ibu negeri pada peta.', 3),
(490, 40, 202, 'e2_n2_s14', 'Siapakah yang mengusik kad ini?', 4),
(491, 21, 202, 'e2_n2_s14', 'Esok pagi kita ke radio terakhir. Zahar tidak akan berhenti.', 5),
(492, 40, 202, 'e2_n2_s14', 'Bagaimanakah kita memelihara istana lama?', 6),
(493, 39, 202, 'e2_n2_s15', 'Pegawai Istiadat, dua negeri kongsi tajuk ''Selamat Sultan''. Saya tidak hendak tersilap, jadi saya perlukan lagu Pahang.', 1),
(494, 21, 202, 'e2_n2_s15', 'Ketua Pahang bergelar Sultan, dan lagunya menyebut ''Kami''.', 2),
(495, NULL, 202, 'e2_n2_s15', 'Saya pilih dengan teliti.', 3),
(496, 39, 202, 'e2_n2_s15', 'Jikalau tersilap, Sultan Pahang tersinggung.', 4),
(497, 21, 202, 'e2_n2_s15', 'Esok pagi kita ke Borneo, ke dua negeri yang jauh. Zahar menanti di sana.', 5),
(498, 21, 202, 'e2_n2_s15', 'Seingat saya, jawapannya ialah Allah Selamatkan Sultan Kami.', 6),
(499, 39, 202, 'e2_n2_s15', 'Dan ''Selamat Sultan'' itu lagu negeri mana?', 7),
(500, 28, 202, 'e2_n2_s16', 'Sarawak dari Sungai Serak yang berubah menjadi Sungai Sarawak, bersempena sejenis bijih galian.', 1),
(501, 27, 202, 'e2_n2_s16', 'Atau ''cerava'', logam antimoni, panggilan Portugis.', 2),
(502, 21, 202, 'e2_n2_s16', 'Surat ini dari Sabah. Nyahkod, kerana tarikh di dalamnya penting.', 3),
(503, NULL, 202, 'e2_n2_s16', 'Ada dokumen bertajuk ''Maharajah of Sabah''.', 4),
(504, 21, 202, 'e2_n2_s16', 'Esok pagi Hari-H. Zahar akan membuat langkah terakhir.', 5),
(505, 27, 202, 'e2_n2_s16', 'Seingat saya, jawapannya ialah 1877 dan pisang saba.', 6),
(506, 28, 202, 'e2_n2_s16', 'Dan nama Sarawak itu bagaimanakah?', 7),
(507, 40, 202, 'e2_n2_s17', 'Ibu negeri kami Kuching. Lagu kami Ibu Pertiwiku.', 1),
(508, 53, 202, 'e2_n2_s17', 'Kami Kota Kinabalu. Lagu kami Sabah Tanah Airku.', 2),
(509, 21, 202, 'e2_n2_s17', 'Wilayah Persekutuan pun ada lagu. Maju dan Sejahtera. Padankan semuanya.', 3),
(510, NULL, 202, 'e2_n2_s17', 'Peta hanya menanda ibu negeri bagi Kuching dan Kota Kinabalu.', 4),
(511, 21, 202, 'e2_n2_s17', 'Esok pagi Hari-H. Dalam gelap, Zahar menuju dewan istiadat.', 5),
(512, 40, 202, 'e2_n2_s17', 'Mengapakah kami wajar menghormati lambang negeri?', 6),
(513, 60, 202, 'e2_n2_s18', 'Pegawai Istiadat, majlis bermula. Tetamu menunggu.', 1),
(514, 57, 202, 'e2_n2_s18', 'Saya telah menukar semua kad tuan hamba. Tuan hamba akan memalukan negara.', 2),
(515, 21, 202, 'e2_n2_s18', 'Dia mengaku sendiri. Tunjukkan bukti bahawa semuanya benar, iaitu jata, bendera dan radio lagu.', 3),
(516, NULL, 202, 'e2_n2_s18', 'Maka setiap negeri ada bendera, lagu dan jata sebagai lambang kemegahan dan kedaulatan.', 4),
(517, 60, 202, 'e2_n2_s18', 'Mengapakah kita wajar menghormati lambang negeri?', 5),
(518, 26, 203, NULL, 'Aku Pengembara Warisan. Pasportku kosong dan setiap penjaga cop hanya memberi cop jika aku tahu fakta yang betul, {nama}.', 1),
(519, 26, 203, NULL, 'Aku belajar bahawa setiap negeri ada nama, ketua, pusat, lagu dan lambang yang menjadi kebanggaannya. Kenangan perjalanan lebih berharga daripada cop.', 2),
(520, 26, 203, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengembara yang membawa pasport kosong. Di setiap wilayah ada penjaga cop yang berbalah dengan penduduk. Hanya fakta betul membuka cop.', 3),
(521, 17, 203, 'e2_n3_s1', 'Pengembara, pasport tuan hamba kosong. Penjaga cop Sabah di pondok itu.', 1),
(522, 31, 203, 'e2_n3_s1', 'Cop Sabah hanya untuk yang tahu mengapakah negeri ini bernama Sabah.', 2),
(523, NULL, 203, 'e2_n3_s1', 'Saya akan padankan fakta dahulu agar tidak bercakap kosong.', 3),
(524, 17, 203, 'e2_n3_s1', 'Pondok ini ada pisang dan satu dokumen tua. Teliti.', 4),
(525, 17, 203, 'e2_n3_s1', 'Selepas ini kita ke tebing sungai di tanah jiran. Ada logam dan bijih menanti.', 5),
(526, 31, 203, 'e2_n3_s1', 'Apa itu pisang saba?', 6),
(527, 31, 203, 'e2_n3_s2', 'Surat ini bakal membuka cop Sarawak. Baca.', 1),
(528, 17, 203, 'e2_n3_s2', 'Dua cerita bersaing di sini, iaitu sungai dan logam.', 2),
(529, NULL, 203, 'e2_n3_s2', 'Saya nyahkod ayat demi ayat.', 3),
(530, 31, 203, 'e2_n3_s2', 'Nama Sarawak ada hubungan dengan Sungai Serak.', 4),
(531, 17, 203, 'e2_n3_s2', 'Esok kita bertemu pusat-pusat pentadbiran Borneo.', 5),
(532, 31, 203, 'e2_n3_s2', 'Dan cerita Portugis? Apa maksudnya?', 6),
(533, 40, 203, 'e2_n3_s3', 'Ibu negeri kami Kuching. Lagu kami Ibu Pertiwiku.', 1),
(534, 53, 203, 'e2_n3_s3', 'Ibu negeri kami Kota Kinabalu. Lagu kami Sabah Tanah Airku.', 2),
(535, 17, 203, 'e2_n3_s3', 'Ketua mereka bergelar Yang di-Pertua Negeri.', 3),
(536, NULL, 203, 'e2_n3_s3', 'Peta hanya menanda ibu negeri bagi Kuching dan Kota Kinabalu.', 4),
(537, 17, 203, 'e2_n3_s3', 'Kita menyeberang ke Labuan, wilayah yang bermula dengan perkataan ''labuh''.', 5),
(538, 53, 203, 'e2_n3_s3', 'Siapakah ketua Wilayah Persekutuan?', 6),
(539, 148, 203, 'e2_n3_s4', 'Tiga wilayah, tiga nama. Pelancong sedang menunggu penerangan saya.', 1),
(540, 17, 203, 'e2_n3_s4', 'Nama Putrajaya ada Putra dan jaya. Dengar baik-baik.', 2),
(541, NULL, 203, 'e2_n3_s4', 'Saya pilih dokumen yang betul.', 3),
(542, 148, 203, 'e2_n3_s4', 'Jikalau tersalah, pelancong menyangka kami tidak mengenali negara sendiri.', 4),
(543, 17, 203, 'e2_n3_s4', 'Maka selepas ini kita periksa kad ketua dan lagu wilayah.', 5),
(544, 148, 203, 'e2_n3_s4', 'Wilayah Persekutuan terdiri daripada apa?', 6),
(545, 31, 203, 'e2_n3_s5', 'Cop ini mahukan tiga fakta, iaitu ketua, lagu dan ibu negeri.', 1),
(546, 17, 203, 'e2_n3_s5', 'Wilayah Persekutuan bukan negeri biasa. Ketuanya lebih tinggi daripada Sultan.', 2),
(547, NULL, 203, 'e2_n3_s5', 'Nota ini ada petunjuk.', 3),
(548, 31, 203, 'e2_n3_s5', 'Baca dengan teliti.', 4),
(549, 17, 203, 'e2_n3_s5', 'Kita menuju selatan ke sebuah negeri yang bermula dengan perkataan batu permata.', 5),
(550, 31, 203, 'e2_n3_s5', 'Apa ketua Wilayah Persekutuan dan ibu negerinya?', 6),
(551, 30, 203, 'e2_n3_s6', 'Johor dari ''jauhar'', batu permata bernilai!', 1),
(552, 55, 203, 'e2_n3_s6', 'Dalam Sulalatus Salatin ia Ujong Tanah!', 2),
(553, 31, 203, 'e2_n3_s6', 'Cop Johor untuk yang menyelesaikan nota ini.', 3),
(554, 17, 203, 'e2_n3_s6', 'Perhatikan batu berkilau dan naskhah di atas meja.', 4),
(555, 17, 203, 'e2_n3_s6', 'Selepas ini kita padankan pusat dan istana Johor.', 5),
(556, 30, 203, 'e2_n3_s6', 'Jauhar itu bahasa apa?', 6),
(557, 40, 203, 'e2_n3_s7', 'Ibu negeri Johor Bahru, bandar diraja Bandar Maharani.', 1),
(558, 17, 203, 'e2_n3_s7', 'Titik merah pusat pentadbiran, titik kuning istana dan warisan.', 2),
(559, 40, 203, 'e2_n3_s7', 'Lagu kami Lagu Bangsa Johor. Ketua kami bergelar Sultan.', 3),
(560, NULL, 203, 'e2_n3_s7', 'Saya padankan semuanya.', 4),
(561, 17, 203, 'e2_n3_s7', 'Esok kita ke Melaka. Ada sebatang pokok dan seekor pelanduk.', 5),
(562, 40, 203, 'e2_n3_s7', 'Mengapakah bandar diraja penting?', 6),
(563, 8, 203, 'e2_n3_s8', 'Melaka dari pokok tempat Parameswara berehat!', 1),
(564, 30, 203, 'e2_n3_s8', 'Dari ''Malakat'', perhimpunan pedagang!', 2),
(565, 31, 203, 'e2_n3_s8', 'Baca nota di akar pokok ini.', 3),
(566, 17, 203, 'e2_n3_s8', 'Nota ini menyebut seekor binatang kecil dan seekor anjing.', 4),
(567, 17, 203, 'e2_n3_s8', 'Selepas ini kita dengar kaset di bilik radio.', 5),
(568, 30, 203, 'e2_n3_s8', 'Dan Malakat itu apa maksudnya?', 6),
(569, 39, 203, 'e2_n3_s9', 'Lagu Melaka mesti dimainkan sebelum Yang di-Pertua Negeri tiba.', 1),
(570, 17, 203, 'e2_n3_s9', 'Ketua Melaka bergelar Yang di-Pertua Negeri. Ibu negerinya Bandar Melaka.', 2),
(571, NULL, 203, 'e2_n3_s9', 'Saya pilih kaset yang benar.', 3),
(572, 39, 203, 'e2_n3_s9', 'Jikalau salah, ketua kami tersinggung.', 4),
(573, 17, 203, 'e2_n3_s9', 'Ketahuilah, selepas ini ke negeri yang bernama dari ''nagari''.', 5),
(574, 17, 203, 'e2_n3_s9', 'Seingat saya, jawapannya ialah Melaka Maju Jaya.', 6),
(575, 39, 203, 'e2_n3_s9', 'Ibu negeri Melaka di mana?', 7),
(576, 54, 203, 'e2_n3_s10', 'Negeri kami terbentuk daripada sembilan luak.', 1),
(577, 31, 203, 'e2_n3_s10', 'Padankan fakta, usah teka.', 2),
(578, 17, 203, 'e2_n3_s10', 'Ada satu tahun dan satu perkataan Minangkabau.', 3),
(579, NULL, 203, 'e2_n3_s10', 'Saya cuba.', 4),
(580, 17, 203, 'e2_n3_s10', 'Lalu kita cari pusat dan istana Negeri Sembilan.', 5),
(581, 54, 203, 'e2_n3_s10', 'Sebut sembilan luak itu!', 6),
(582, 58, 203, 'e2_n3_s11', 'Ibu negeri Seremban, bandar diraja Seri Menanti.', 1),
(583, 17, 203, 'e2_n3_s11', 'Ketua Negeri Sembilan bergelar Yang di-Pertuan Besar.', 2),
(584, NULL, 203, 'e2_n3_s11', 'Lagu mereka Berkatlah Yang di-Pertuan Besar.', 3),
(585, 58, 203, 'e2_n3_s11', 'Padankan semuanya.', 4),
(586, 17, 203, 'e2_n3_s11', 'Sesungguhnya, selepas ini kita ke Selangor dan Pahang, dua negeri berjiran dengan kisah nama masing-masing.', 5),
(587, 58, 203, 'e2_n3_s11', 'Mengapakah menghormati ketua negeri penting?', 6),
(588, 27, 203, 'e2_n3_s12', 'Selangor dari pokok mentagau. Pedagang menyebut kuala selangau.', 1),
(589, 8, 203, 'e2_n3_s12', 'Atau dari serangga selangur.', 2),
(590, 31, 203, 'e2_n3_s12', 'Pahang dari pokok mahang. Dalam Sulalatus Salatin ia Inderapura atau Pura.', 3),
(591, 17, 203, 'e2_n3_s12', 'Pura bermaksud bandar atau pekan.', 4),
(592, 17, 203, 'e2_n3_s12', 'Lalu kita menuju pusat dan istana kedua-dua negeri.', 5),
(593, 31, 203, 'e2_n3_s12', 'Apa maksud pura?', 6),
(594, 40, 203, 'e2_n3_s13', 'Ibu negeri Shah Alam, bandar diraja Klang. Lagu kami Duli Yang Maha Mulia.', 1),
(595, 53, 203, 'e2_n3_s13', 'Ibu negeri Kuantan, bandar diraja Pekan. Lagu kami Allah Selamatkan Sultan Kami.', 2),
(596, 17, 203, 'e2_n3_s13', 'Kedua-dua ketua bergelar Sultan.', 3),
(597, NULL, 203, 'e2_n3_s13', 'Saya padankan satu per satu.', 4),
(598, 17, 203, 'e2_n3_s13', 'Kita ke pantai timur. Pelangi menunggu selepas hujan.', 5),
(599, 40, 203, 'e2_n3_s13', 'Apa gelaran ketua kedua-dua negeri?', 6),
(600, 27, 203, 'e2_n3_s14', 'Terengganu dari ''taring anu'', taring besar di Pulau Duyong, atau ''terangnya ganu'', pelangi.', 1),
(601, 55, 203, 'e2_n3_s14', 'Kelantan dari ''kilatan'', cahaya terang yang dilihat orang Patani, atau dari gelam hutan.', 2),
(602, 17, 203, 'e2_n3_s14', 'Padankan kesemuanya, satu per satu.', 3),
(603, NULL, 203, 'e2_n3_s14', 'Saya bergerak.', 4),
(604, 17, 203, 'e2_n3_s14', 'Selepas ini kita periksa lagu dan pusat pantai timur.', 5),
(605, 55, 203, 'e2_n3_s14', 'Seingat saya, Terangnya ganu berpasangan dengan Pelangi.', 6),
(606, 27, 203, 'e2_n3_s14', 'Gading apa itu sebenarnya?', 7),
(607, 31, 203, 'e2_n3_s15', 'Dua negeri di sini kongsi tajuk lagu yang sama. Nota ini menjelaskannya.', 1),
(608, 17, 203, 'e2_n3_s15', 'Ibu negeri satu ialah Kuala Terengganu, satu lagi Kota Bharu. Tiada bandar diraja ditanda pada peta.', 2),
(609, NULL, 203, 'e2_n3_s15', 'Saya nyahkod.', 3),
(610, 31, 203, 'e2_n3_s15', 'Ketua kedua-dua negeri bergelar Sultan.', 4),
(611, 17, 203, 'e2_n3_s15', 'Kita ke barat. Sebuah lombong menunggu.', 5),
(612, 31, 203, 'e2_n3_s15', 'Ibu negeri Terengganu dan Kelantan?', 6),
(613, 56, 203, 'e2_n3_s16', 'Perak dari kilatan ikan, atau bijih timah putih berkilat!', 1),
(614, 27, 203, 'e2_n3_s16', 'Pulau ini Pulo Ka Satu. Orang Kedah panggil Tanjong Penaga, bersempena pokok penaga.', 2),
(615, 30, 203, 'e2_n3_s16', 'Pinang juga bahan dagangan penting.', 3),
(616, 17, 203, 'e2_n3_s16', 'Padankan kesemuanya. Penjaga cop menunggu.', 4),
(617, 17, 203, 'e2_n3_s16', 'Selepas ini kita periksa dokumen pusat utara.', 5),
(618, 30, 203, 'e2_n3_s16', 'Mengapakah pinang penting pada nama pulau?', 6),
(619, 40, 203, 'e2_n3_s17', 'Pengembara, saya perlukan dokumen ibu negeri, bandar diraja, lagu dan ketua bagi Perak dan Pulau Pinang.', 1),
(620, 17, 203, 'e2_n3_s17', 'Ketua Perak bergelar Sultan. Ketua Pulau Pinang bergelar Yang di-Pertua Negeri.', 2),
(621, NULL, 203, 'e2_n3_s17', 'Saya pilih yang betul.', 3),
(622, 40, 203, 'e2_n3_s17', 'Dokumen lain bercampur.', 4),
(623, 17, 203, 'e2_n3_s17', 'Kita ke dua negeri terakhir di utara.', 5),
(624, 40, 203, 'e2_n3_s17', 'Apa lagu Pulau Pinang?', 6),
(625, 29, 203, 'e2_n3_s18', 'Kedah dari ''kheddah'', perangkap gajah.', 1),
(626, 30, 203, 'e2_n3_s18', 'Dari ''qadah'', cawan berkaki. Ada juga ''kadaram'' atau ''kalagam'' dalam tulisan Tamil.', 2),
(627, 28, 203, 'e2_n3_s18', 'Perlis dari ''prow-lowy'', kelapa hanyut, atau dari ''peroleh''.', 3),
(628, 17, 203, 'e2_n3_s18', 'Padankan semuanya.', 4),
(629, 17, 203, 'e2_n3_s18', 'Cop terakhir. Perlis ialah negeri paling hujung utara.', 5),
(630, 28, 203, 'e2_n3_s18', 'Seingat saya, Peroleh berpasangan dengan Mandat Sultan Ahmad Tajuddin Halim Shah II kepada Raja Syed Hussin Jamalullail.', 6),
(631, 28, 203, 'e2_n3_s18', 'Siapakah Raja Syed Hussin itu?', 7),
(632, 39, 203, 'e2_n3_s19', 'Lagu Kedah atau lagu Perlis, Pengembara? Saya perlukan Kedah dahulu.', 1),
(633, 17, 203, 'e2_n3_s19', 'Ketua Kedah bergelar Sultan, ketua Perlis bergelar Raja. Kangar dan Arau, Alor Setar dan Anak Bukit.', 2),
(634, NULL, 203, 'e2_n3_s19', 'Saya pilih kaset Kedah.', 3),
(635, 39, 203, 'e2_n3_s19', 'Jikalau tersilap, Raja Perlis tersinggung.', 4),
(636, 17, 203, 'e2_n3_s19', 'Pasport hampir penuh. Satu cop lagi menanti di Wilayah Persekutuan.', 5),
(637, 39, 203, 'e2_n3_s19', 'Lagu Perlis dan ibu negeri serta bandar diraja?', 6),
(638, 31, 203, 'e2_n3_s20', 'Cop ini bukan untuk satu negeri. Ia untuk bendera, jata dan lagu semua negeri.', 1),
(639, 17, 203, 'e2_n3_s20', 'Halaman yang koyak bukan hilang. Ia tersembunyi di pentas.', 2),
(640, NULL, 203, 'e2_n3_s20', 'Saya cari bukti lambang negeri dahulu.', 3),
(641, 31, 203, 'e2_n3_s20', 'Setiap negeri mempunyai bendera, lagu dan jata sebagai lambang kemegahan dan kedaulatan.', 4),
(642, 17, 203, 'e2_n3_s20', 'Kita sampai. Sahabat sebenar bukan cop, namun kenangan.', 5),
(643, 31, 203, 'e2_n3_s20', 'Mengapakah kita wajar menghormati lambang negeri?', 6),
(644, 5, 301, NULL, 'Tugasku ialah menenangkan negara selepas 13 Mei 1969, mendengar semua pihak dan merangka satu ideologi yang menyatukan rakyat. Satu kesilapan boleh mencetuskan perpecahan baharu, {nama}.', 1),
(645, 5, 301, NULL, 'Aku belajar bahawa perpaduan tidak lahir daripada paksaan, tetapi daripada pegangan bersama yang dihayati oleh semua kaum.', 2),
(646, 5, 301, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemimpin yang mentadbir negara melalui MAGERAN selepas peristiwa 13 Mei 1969. Keputusanmu menentukan masa depan perpaduan. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(647, 43, 301, 'e3_n1_s1', 'Tun, jalan telah sunyi namun rakyat masih curiga antara satu sama lain. Siapa yang kini mentadbir negara?', 1),
(648, NULL, 301, 'e3_n1_s1', 'Selepas rusuhan kaum 13 Mei 1969, sebuah majlis khas mengambil alih. Namanya Majlis Gerakan Negara, ringkasnya MAGERAN.', 2),
(649, 42, 301, 'e3_n1_s1', 'Nota ini menyebut majlis itu dibentuk selepas rusuhan, bukan sebelumnya. Namun tulisannya tergesa-gesa.', 3),
(650, NULL, 301, 'e3_n1_s1', 'Benar. Kita tenangkan negara dahulu, kemudian cari punca agar ia tidak berulang.', 4),
(651, 43, 301, 'e3_n1_s1', 'Tun, jika orang bertanya mengapakah pentadbiran biasa tidak diteruskan, apa jawapan kita?', 5),
(652, 43, 301, 'e3_n1_s2', 'Tun, pentadbiran British membawa masuk pekerja dari luar untuk sektor ekonomi. Setiap kaum diberi kerja yang berbeza.', 1),
(653, NULL, 301, 'e3_n1_s2', 'Orang Melayu bertani sara diri. Orang Cina melombong dan berniaga. Orang India bekerja di ladang.', 2),
(654, 42, 301, 'e3_n1_s2', 'Maka jurang ekonomi tidak seimbang, Tun. Itulah sebab pertama laporan ini.', 3),
(655, 45, 301, 'e3_n1_s2', 'Tun, saya Pak Tani. Kami menanam padi untuk makan sendiri. Kami tidak bertemu pelombong atau peniaga.', 4),
(656, 46, 301, 'e3_n1_s2', 'Saya Pak Muthu, penoreh getah. Kami bekerja di ladang sejak pagi, jauh daripada kampung dan pekan.', 5),
(657, 43, 301, 'e3_n1_s2', 'Tun, tiga kegiatan itu ada bukti di peta. Cari semuanya, kerana wakil rakyat hendak melihat sendiri.', 6),
(658, 42, 301, 'e3_n1_s3', 'Tun, orang Melayu tinggal di kampung dan pedalaman. Orang Cina di bandar. Orang India di kawasan ladang.', 1),
(659, NULL, 301, 'e3_n1_s3', 'Maka mereka hidup berasingan sehingga jarang bertemu. Apa akibatnya, jikalau orang tidak pernah berbual?', 2),
(660, 44, 301, 'e3_n1_s3', 'Saya Tauke Lim, peniaga rumah kedai. Saya jarang bertemu jiran Melayu atau India. Kami bertegur sapa hanya di pasar.', 3),
(661, 43, 301, 'e3_n1_s3', 'Tun, ada satu lagi sebab dalam laporan. Perbezaan fahaman politik merenggangkan hubungan kaum.', 4),
(662, 42, 301, 'e3_n1_s3', 'Keadaan itu tidak harmoni, Tun, sehingga mencetuskan rusuhan kaum 13 Mei 1969.', 5),
(663, 44, 301, 'e3_n1_s3', 'Seingat saya, jawapannya ialah kurang peluang berinteraksi antara masyarakat.', 6),
(664, 43, 301, 'e3_n1_s3', 'Tun, nota ini tidak lengkap. Apakah akibat langsung daripada tempat tinggal yang berasingan?', 7),
(665, 43, 301, 'e3_n1_s4', 'Tun, Majlis Perundingan Negara, ringkasnya MAPEN, akan bersidang. Ia dianggotai 66 orang wakil dari pelbagai pihak.', 1),
(666, NULL, 301, 'e3_n1_s4', 'Wakil daripada MAGERAN, kerajaan negeri, parti politik, Sarawak dan Sabah, kumpulan agama, badan profesional dan lain-lain.', 2),
(667, 41, 301, 'e3_n1_s4', 'Saya Sambanthan. Saya mewakili suara rakyat berbilang kaum. Rukun Negara mesti lahir daripada perundingan bersama.', 3),
(668, 43, 301, 'e3_n1_s4', 'Ketahuilah, pada 4 Mac 1970, Jawatankuasa Rukun Negara di bawah MAPEN merangka dan memperkenalkan Rukun Negara.', 4),
(669, 42, 301, 'e3_n1_s4', 'Tun, saya perlu menghantar surat jemputan kepada jawatankuasa. Surat yang manakah yang benar?', 5),
(670, 41, 301, 'e3_n1_s5', 'Tun, Rukun Negara mempunyai lima matlamat. Pertama, mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat.', 1),
(671, NULL, 301, 'e3_n1_s5', 'Kedua, memelihara satu cara hidup demokrasi. Ketiga, mencipta masyarakat yang adil agar kemakmuran dinikmati secara adil dan saksama.', 2),
(672, 43, 301, 'e3_n1_s5', 'Keempat, menjamin cara yang liberal terhadap tradisi kebudayaan yang kaya dan pelbagai corak.', 3),
(673, 42, 301, 'e3_n1_s5', 'Kelima, membina masyarakat progresif yang menggunakan sains dan teknologi moden.', 4),
(674, 41, 301, 'e3_n1_s5', 'Tun, bantu wakil memadankan setiap matlamat dengan maksudnya sebelum persidangan bermula.', 5),
(675, 43, 301, 'e3_n1_s6', 'Tun, Rukun Negara dimasyhurkan sebagai Pengisytiharan Diraja oleh Yang di-Pertuan Agong Keempat, Tuanku Sultan Ismail Nasiruddin Shah.', 1),
(676, NULL, 301, 'e3_n1_s6', 'Ia diisytiharkan bersempena ulang tahun Hari Kebangsaan yang ke-13, iaitu 31 Ogos 1970.', 2),
(677, 42, 301, 'e3_n1_s6', 'Sebelum itu, MAPEN bersidang pada 4 Mac 1970 dan semuanya bermula dengan rusuhan 13 Mei 1969.', 3),
(678, 52, 301, 'e3_n1_s6', 'Pak Cik, mengapakah Rukun Negara diisytiharkan bersempena Hari Kebangsaan?', 4),
(679, 43, 301, 'e3_n1_s6', 'Tun, kad peristiwa ini bercampur. Susun mengikut tarikh sebelum tetamu bertanya.', 5),
(680, 52, 301, 'e3_n1_s7', 'Pak Cik, rumah ibadat berlainan agama ada di sini. Mengapakah mereka boleh hidup aman?', 1),
(681, NULL, 301, 'e3_n1_s7', 'Prinsip pertama ialah Kepercayaan kepada Tuhan. Agama menjadi pegangan utama dan kita menghormati amalan beragama orang lain.', 2),
(682, 43, 301, 'e3_n1_s7', 'Prinsip kedua pula Kesetiaan kepada Raja dan Negara. Setiap warganegara taat setia kepada Yang di-Pertuan Agong sebagai Ketua Utama Negara.', 3),
(683, 42, 301, 'e3_n1_s7', 'Kedua-dua prinsip menyatupadukan rakyat berbilang kaum dan melahirkan semangat patriotik.', 4),
(684, 52, 301, 'e3_n1_s7', 'Pak Cik, saya ada dua kad. Yang mana serahkan kepada guru untuk prinsip pertama?', 5),
(685, 49, 301, 'e3_n1_s8', 'Tun, saya Arun. Saya diberitahu Perlembagaan Persekutuan ialah undang-undang tertinggi negara. Benarkah?', 1),
(686, NULL, 301, 'e3_n1_s8', 'Itulah Keluhuran Perlembagaan. Tiada institusi dapat mengatasi Perlembagaan, dan rakyat perlu menerima, mematuhi serta mempertahankannya.', 2),
(687, 43, 301, 'e3_n1_s8', 'Prinsip keempat ialah Kedaulatan Undang-undang. Setiap rakyat perlu menghormati dan mematuhi undang-undang yang ditetapkan.', 3),
(688, 42, 301, 'e3_n1_s8', 'Kepatuhan kepada undang-undang menjamin keharmonian masyarakat dan keselamatan negara.', 4),
(689, 49, 301, 'e3_n1_s8', 'Tun, ada tiga bukti di bilik ini tentang dua prinsip itu. Boleh Tun cari bersama?', 5),
(690, 52, 301, 'e3_n1_s9', 'Pak Cik, prinsip kelima ialah Kesopanan dan Kesusilaan. Apa maksudnya?', 1),
(691, NULL, 301, 'e3_n1_s9', 'Amalan nilai murni yang melambangkan keperibadian rakyat Malaysia. Ia membentuk masyarakat berdisiplin dan berakhlak mulia.', 2),
(692, 43, 301, 'e3_n1_s9', 'Contoh situasi, iaitu seorang murid mematuhi undang-undang jalan raya. Seorang lagi memimpin nenek melintas jalan.', 3),
(693, 42, 301, 'e3_n1_s9', 'Seorang graduan undang-undang menggubal undang-undang di Parlimen. Sebuah keluarga berdoa mengikut kepercayaan masing-masing.', 4),
(694, 43, 301, 'e3_n1_s9', 'Seorang anggota komando rela berkorban demi kedaulatan negara. Tun, padankan situasi ini dengan prinsip yang benar.', 5),
(695, 50, 301, 'e3_n1_s10', 'Tun, saya Hafiz. Jiran saya berlainan agama. Mengapakah kami boleh berdiri bersama di sini?', 1),
(696, NULL, 301, 'e3_n1_s10', 'Rukun Negara berperanan mewujudkan rakyat yang bersatu padu dan bertoleransi. Prinsip kepercayaan kepada Tuhan membentuk rakyat yang patuh ajaran agama masing-masing.', 2),
(697, 43, 301, 'e3_n1_s10', 'Masyarakat yang beragama dapat mengelakkan perasaan dengki, khianat, rasuah, penyalahgunaan dadah dan keruntuhan moral.', 3),
(698, 42, 301, 'e3_n1_s10', 'Rukun Negara juga membentuk masyarakat patriotik yang menghormati bendera Jalur Gemilang, Jata Negara dan lagu Negaraku.', 4),
(699, 50, 301, 'e3_n1_s10', 'Tun, tolong nyahkod nota ini tentang peranan Rukun Negara.', 5),
(700, 47, 301, 'e3_n1_s11', 'Tun, saya Wei Jie, sukarelawan kempen. Rukun Negara bimbing kami daripada terlibat dengan jenayah, betulkah?', 1),
(701, NULL, 301, 'e3_n1_s11', 'Ya. Rukun Negara memupuk sikap menghormati undang-undang. Kepatuhan kepada undang-undang mewujudkan keamanan dan kesejahteraan.', 2),
(702, 44, 301, 'e3_n1_s11', 'Saya Tauke Lim. Dahulu kami jarang bertemu jiran berlainan kaum. Kini kami belajar budaya masing-masing.', 3),
(703, 43, 301, 'e3_n1_s11', 'Rukun Negara mengukuhkan perpaduan melalui permuafakatan dan toleransi.', 4),
(704, 47, 301, 'e3_n1_s11', 'Tun, ada tiga bukti peranan itu di bandar ini. Boleh Tun carikan bersama?', 5),
(705, 52, 301, 'e3_n1_s12', 'Pak Cik, saya masih keliru dengan dua peranan terakhir, nilai murni dan jati diri.', 1),
(706, NULL, 301, 'e3_n1_s12', 'Rukun Negara menerapkan nilai murni agar hubungan harmoni dan saling menghormati. Ia juga membentuk jati diri masyarakat Malaysia yang berintegriti.', 2),
(707, 43, 301, 'e3_n1_s12', 'Integriti bermaksud mempunyai sikap kejujuran yang tulen dan tidak berubah. Contohnya, tidak meniru dalam peperiksaan.', 3),
(708, 42, 301, 'e3_n1_s12', 'Integriti mempengaruhi kecemerlangan dalam pendidikan, kerjaya dan kehidupan.', 4),
(709, 43, 301, 'e3_n1_s12', 'Seingat saya, Meraikan kepelbagaian agama dan kepercayaan berpasangan dengan Menghormati amalan agama orang lain, Masyarakat patriotik berpasangan dengan Menghormati bendera, Jata Negara dan lagu Negaraku.', 5),
(710, 43, 301, 'e3_n1_s12', 'Dan seingat saya juga, Menghormati undang-undang berpasangan dengan Keamanan dan kesejahteraan terjamin, Mengukuhkan perpaduan berpasangan dengan Permuafakatan dan toleransi.', 6),
(711, 52, 301, 'e3_n1_s12', 'Pak Cik, boleh tolong padankan enam peranan dengan maksudnya agar saya faham?', 7),
(712, 41, 302, NULL, 'Aku mendengar suara rakyat dari satu pintu ke satu pintu. Perpaduan bermula apabila kita sudi bertegur sapa, {nama}.', 1),
(713, 41, 302, NULL, 'Rakyat hanya menerima Rukun Negara jika mereka faham dan merasainya dalam hidup harian.', 2),
(714, 41, 302, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wakil rakyat yang membawa suara pelbagai kaum ke meja perundingan. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(715, 42, 302, 'e3_n2_s1', 'Tun, rakyat berkata mereka hidup berasingan, Melayu di kampung, Cina di bandar dan India di ladang.', 1),
(716, NULL, 302, 'e3_n2_s1', 'Pengasingan tempat tinggal menyebabkan kurang peluang berinteraksi. Itu sebab kedua mengapakah Rukun Negara diperlukan.', 2),
(717, 45, 302, 'e3_n2_s1', 'Saya Pak Tani. Rumah saya di kampung dan saya jarang ke bandar. Saya tidak kenal orang ladang.', 3),
(718, 46, 302, 'e3_n2_s1', 'Saya Pak Muthu. Kami tinggal di ladang, jauh dari kampung dan bandar, Tun.', 4),
(719, 44, 302, 'e3_n2_s1', 'Saya Tauke Lim. Rumah kedai kami di bandar. Kami jarang bertemu jiran Melayu. Tun, tolong cari tiga petempatan ini di peta.', 5),
(720, 42, 302, 'e3_n2_s2', 'Tun, laporan ini menyebut tiga sebab rusuhan. Dua telah kita tahu, iaitu kegiatan ekonomi dan tempat tinggal.', 1),
(721, NULL, 302, 'e3_n2_s2', 'Sebab ketiga ialah perbezaan fahaman politik yang merenggangkan hubungan kaum, lalu mencetuskan rusuhan kaum 13 Mei 1969.', 2),
(722, 43, 302, 'e3_n2_s2', 'Selepas rusuhan, MAGERAN mentadbir negara. Tun, laporan ini menyebut sebab ketiga namun ayat itu terpadam sebahagian.', 3),
(723, 49, 302, 'e3_n2_s2', 'Tun, saya Arun. Boleh Tun bantu nyahkod ayat terpadam itu?', 4),
(724, 43, 302, 'e3_n2_s3', 'Tun, MAPEN mempunyai 66 wakil dari pelbagai bidang. Mereka bersidang agar semua suara didengar.', 1),
(725, NULL, 302, 'e3_n2_s3', 'Jawatankuasa Rukun Negara di bawah MAPEN ditubuhkan untuk merangka dan memperkenalkan Rukun Negara.', 2),
(726, 42, 302, 'e3_n2_s3', 'Tarikhnya ialah 4 Mac 1970. Tun, setiausaha memerlukan dokumen yang benar untuk dibaca.', 3),
(727, 50, 302, 'e3_n2_s3', 'Tun, saya Hafiz. Saya setiausaha. Dokumen yang manakah perlu saya bacakan?', 4),
(728, NULL, 302, 'e3_n2_s4', 'Rukun Negara ada lima matlamat, iaitu perpaduan lebih erat, demokrasi, masyarakat adil, cara liberal terhadap kebudayaan dan masyarakat progresif.', 1),
(729, NULL, 302, 'e3_n2_s4', 'Perpaduan lebih erat dalam kalangan seluruh masyarakat. Masyarakat adil bermakna kemakmuran dinikmati secara adil dan saksama.', 2),
(730, 47, 302, 'e3_n2_s4', 'Saya Wei Jie. Cara liberal terhadap kebudayaan bermakna kita menghormati tradisi yang kaya dan pelbagai corak, bukan?', 3),
(731, 52, 302, 'e3_n2_s4', 'Masyarakat progresif pula menggunakan sains dan teknologi moden, Pak Cik?', 4),
(732, 47, 302, 'e3_n2_s4', 'Seingat saya, Cara hidup demokrasi berpasangan dengan Rakyat mengundi memilih wakil.', 5),
(733, NULL, 302, 'e3_n2_s4', 'Benar. Tolong padankan matlamat dan contohnya agar semua orang faham.', 6),
(734, 43, 302, 'e3_n2_s5', 'Tun, Rukun Negara diisytiharkan sebagai Pengisytiharan Diraja pada 31 Ogos 1970, bersempena ulang tahun Hari Kebangsaan ke-13.', 1),
(735, NULL, 302, 'e3_n2_s5', 'Baginda ialah Yang di-Pertuan Agong Keempat, Tuanku Sultan Ismail Nasiruddin Shah.', 2),
(736, 52, 302, 'e3_n2_s5', 'Pak Cik, mengapakah pengisytiharan itu bersempena Hari Kebangsaan?', 3),
(737, 42, 302, 'e3_n2_s5', 'Tun, wakil rakyat hendak menyerahkan kad pengisytiharan kepada baginda. Kad yang mana?', 4),
(738, 43, 302, 'e3_n2_s6', 'Prinsip pertama Kepercayaan kepada Tuhan. Kedua, Kesetiaan kepada Raja dan Negara. Ketiga, Keluhuran Perlembagaan.', 1),
(739, NULL, 302, 'e3_n2_s6', 'Keempat, Kedaulatan Undang-undang. Kelima, Kesopanan dan Kesusilaan.', 2),
(740, 52, 302, 'e3_n2_s6', 'Pak Cik, Kesetiaan kepada Raja dan Negara bermaksud taat setia kepada Yang di-Pertuan Agong, bukan?', 3),
(741, 43, 302, 'e3_n2_s6', 'Seingat saya, Kepercayaan kepada Tuhan berpasangan dengan Agama pegangan utama dan hormat amalan beragama, Kesopanan dan Kesusilaan berpasangan dengan Amalan nilai murni keperibadian rakyat.', 4),
(742, 42, 302, 'e3_n2_s6', 'Benar. Yang di-Pertuan Agong ialah Ketua Utama Negara. Tun, tolong padankan prinsip dengan maksudnya.', 5),
(743, NULL, 302, 'e3_n2_s7', 'Rukun Negara meraikan kepelbagaian agama. Prinsip kepercayaan kepada Tuhan membentuk rakyat yang patuh ajaran agama masing-masing.', 1),
(744, 43, 302, 'e3_n2_s7', 'Masyarakat beragama dapat mengelakkan dengki, khianat, rasuah, penyalahgunaan dadah dan keruntuhan moral.', 2),
(745, 42, 302, 'e3_n2_s7', 'Rukun Negara juga membentuk masyarakat patriotik yang menghormati Jalur Gemilang, Jata Negara dan Negaraku.', 3),
(746, 50, 302, 'e3_n2_s7', 'Tun, bantu saya cari tiga bukti peranan ini di kawasan ini.', 4),
(747, 47, 302, 'e3_n2_s8', 'Tun, saya Wei Jie. Rukun Negara membimbing kami menghormati undang-undang dan menguatkan perpaduan.', 1),
(748, NULL, 302, 'e3_n2_s8', 'Kepatuhan kepada undang-undang mewujudkan keamanan dan kesejahteraan. Permuafakatan dan toleransi pula mengukuhkan perpaduan.', 2),
(749, 44, 302, 'e3_n2_s8', 'Saya Tauke Lim. Kami dan jiran kini belajar budaya masing-masing. Jarak antara kami telah berkurang.', 3),
(750, 47, 302, 'e3_n2_s8', 'Tun, boleh Tun nyahkod nota ini tentang peranan Rukun Negara di bandar?', 4),
(751, 52, 302, 'e3_n2_s9', 'Pak Cik, apakah maksud integriti dalam jati diri masyarakat Malaysia?', 1),
(752, NULL, 302, 'e3_n2_s9', 'Integriti ialah sikap kejujuran yang tulen dan tidak berubah. Contohnya, tidak meniru dalam peperiksaan.', 2),
(753, 43, 302, 'e3_n2_s9', 'Rukun Negara menerapkan nilai murni agar hubungan harmoni dan saling menghormati. Ia juga membentuk jati diri yang berintegriti.', 3),
(754, 52, 302, 'e3_n2_s9', 'Seingat saya, Meraikan kepelbagaian agama berpasangan dengan Hormat amalan agama orang lain, Masyarakat patriotik berpasangan dengan Hormat Jalur Gemilang, Jata Negara dan Negaraku.', 4),
(755, 52, 302, 'e3_n2_s9', 'Dan seingat saya juga, Menghormati undang-undang berpasangan dengan Keamanan dan kesejahteraan, Mengukuhkan perpaduan berpasangan dengan Permuafakatan dan toleransi.', 5),
(756, 42, 302, 'e3_n2_s9', 'Integriti mempengaruhi kecemerlangan dalam pendidikan, kerjaya dan kehidupan. Tun, murid hendak merumuskan enam peranan.', 6),
(757, 1, 303, NULL, 'Aku telah menyaksikan kemerdekaan dan rusuhan. Aku mahu Rukun Negara menjadi ikrar yang dipegang semua rakyat, {nama}.', 1),
(758, 1, 303, NULL, 'Rukun Negara akan hidup jika rakyat memegangnya dalam kehidupan harian.', 2),
(759, 1, 303, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, Bapa Kemerdekaan yang menyaksikan Rukun Negara diisytiharkan. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(760, 43, 303, 'e3_n3_s1', 'Tunku, laporan menyatakan rusuhan 13 Mei 1969 berpunca daripada tiga sebab yang berkait dengan jurang antara kaum.', 1),
(761, NULL, 303, 'e3_n3_s1', 'Pertama, perbezaan kegiatan ekonomi. Kedua, pengasingan tempat tinggal. Ketiga, perbezaan fahaman politik.', 2),
(762, 42, 303, 'e3_n3_s1', 'Selepas rusuhan, MAGERAN mentadbir negara di bawah pengarah Tun Abdul Razak.', 3),
(763, 43, 303, 'e3_n3_s1', 'Seingat saya, Perbezaan kegiatan ekonomi berpasangan dengan Melayu bertani, Cina berniaga, India di ladang.', 4),
(764, 43, 303, 'e3_n3_s1', 'Tunku, nota ini mencampurkan sebab dan akibat. Tolong asingkan mengikut yang benar.', 5),
(765, 41, 303, 'e3_n3_s2', 'Tunku, Majlis Perundingan Negara dianggotai 66 wakil. Jawatankuasa Rukun Negara di bawahnya bersidang pada 4 Mac 1970.', 1),
(766, NULL, 303, 'e3_n3_s2', 'Sesungguhnya, pada 13 Mei 1969, rusuhan berlaku. Pada 4 Mac 1970, jawatankuasa merangka. Rukun Negara lalu diisytiharkan.', 2),
(767, 42, 303, 'e3_n3_s2', 'Tunku, kad tarikh ini bercampur. Tolong susun mengikut tarikh.', 3),
(768, 43, 303, 'e3_n3_s2', 'Tarikh kemuncak ialah 31 Ogos 1970, bersempena ulang tahun Hari Kebangsaan ke-13.', 4),
(769, 43, 303, 'e3_n3_s3', 'Tunku, Yang di-Pertuan Agong Keempat ialah Tuanku Sultan Ismail Nasiruddin Shah. Baginda memasyhurkan Rukun Negara.', 1),
(770, NULL, 303, 'e3_n3_s3', 'Pengisytiharan Diraja itu menandakan Rukun Negara diterima oleh semua rakyat dan semua kaum.', 2),
(771, 52, 303, 'e3_n3_s3', 'Tunku, mengapakah pengisytiharan itu penting kepada murid?', 3),
(772, 42, 303, 'e3_n3_s3', 'Tunku, tolong nyahkod catatan ini tentang pengisytiharan.', 4),
(773, NULL, 303, 'e3_n3_s4', 'Matlamat pertama, iaitu mencapai perpaduan yang lebih erat dalam kalangan seluruh masyarakat. Kedua, iaitu memelihara satu cara hidup demokrasi.', 1),
(774, 43, 303, 'e3_n3_s4', 'Ketiga, iaitu mencipta masyarakat adil agar kemakmuran dinikmati secara adil dan saksama.', 2),
(775, 42, 303, 'e3_n3_s4', 'Keempat, iaitu menjamin cara liberal terhadap tradisi kebudayaan yang kaya dan pelbagai corak.', 3),
(776, 52, 303, 'e3_n3_s4', 'Kelima, iaitu membina masyarakat progresif yang menggunakan sains dan teknologi moden.', 4),
(777, NULL, 303, 'e3_n3_s4', 'Tolong cari lima matlamat ini di dalam dewan agar semua orang melihat sendiri.', 5),
(778, NULL, 303, 'e3_n3_s5', 'Lima prinsip menyokong bangsa. Kepercayaan kepada Tuhan, Kesetiaan kepada Raja dan Negara, Keluhuran Perlembagaan, Kedaulatan Undang-undang, Kesopanan dan Kesusilaan.', 1),
(779, 43, 303, 'e3_n3_s5', 'Keluhuran Perlembagaan bermaksud Perlembagaan ialah undang-undang tertinggi. Kedaulatan Undang-undang bermaksud rakyat menghormati dan mematuhi undang-undang.', 2),
(780, 52, 303, 'e3_n3_s5', 'Tunku, Kesopanan dan Kesusilaan ialah nilai murni, bukan?', 3),
(781, 43, 303, 'e3_n3_s5', 'Seingat saya, Memimpin nenek melintas jalan berpasangan dengan Kesopanan dan Kesusilaan.', 4),
(782, 42, 303, 'e3_n3_s5', 'Benar. Tunku, tolong padankan situasi dengan prinsip.', 5),
(783, 45, 303, 'e3_n3_s6', 'Tunku, dahulu kami tidak bertegur sapa. Kini kami berkongsi juadah pada hari perayaan.', 1),
(784, 44, 303, 'e3_n3_s6', 'Rukun Negara mengajar kami meraikan kepelbagaian agama dan saling menghormati.', 2),
(785, NULL, 303, 'e3_n3_s6', 'Itulah peranan Rukun Negara, iaitu meraikan kepelbagaian agama dan kepercayaan, serta membentuk masyarakat patriotik.', 3),
(786, 45, 303, 'e3_n3_s6', 'Seingat saya, jawapannya ialah Dengki, khianat, rasuah, dadah dan keruntuhan moral.', 4),
(787, 43, 303, 'e3_n3_s6', 'Tunku, murid mahu tahu apa yang boleh diperoleh daripada masyarakat yang beragama. Tolong beri juadah yang benar.', 5),
(788, 47, 303, 'e3_n3_s7', 'Tunku, kami belia kempen. Kami diajar menghormati undang-undang dan bekerjasama dengan semua kaum.', 1),
(789, NULL, 303, 'e3_n3_s7', 'Itu dua peranan Rukun Negara, iaitu menghormati undang-undang dan mengukuhkan perpaduan.', 2),
(790, 44, 303, 'e3_n3_s7', 'Saya Tauke Lim. Kami berniaga bersama jiran Melayu dan India. Perniagaan makin maju.', 3),
(791, 47, 303, 'e3_n3_s7', 'Tunku, boleh Tunku carikan tiga bukti peranan ini di sekeliling kami?', 4),
(792, 52, 303, 'e3_n3_s8', 'Tunku, apakah maksud jati diri yang berintegriti?', 1),
(793, NULL, 303, 'e3_n3_s8', 'Integriti ialah kejujuran yang tulen dan tidak berubah. Contohnya, tidak meniru dalam peperiksaan.', 2),
(794, 43, 303, 'e3_n3_s8', 'Rukun Negara menerapkan nilai murni agar hubungan harmoni dan saling menghormati.', 3),
(795, 52, 303, 'e3_n3_s8', 'Seingat saya, Meraikan kepelbagaian agama berpasangan dengan Hormat amalan agama orang lain, Masyarakat patriotik berpasangan dengan Hormat lambang kedaulatan negara, Menghormati undang-undang berpasangan dengan Keamanan dan kesejahteraan.', 4),
(796, 52, 303, 'e3_n3_s8', 'Dan seingat saya juga, Mengukuhkan perpaduan berpasangan dengan Permuafakatan dan toleransi.', 5),
(797, 42, 303, 'e3_n3_s8', 'Integriti mempengaruhi kecemerlangan dalam pendidikan, kerjaya dan kehidupan. Tunku, tolong padankan enam peranan.', 6),
(798, 61, 401, NULL, 'Tugasku ialah menjaga rentak setiap kaum supaya tidak hilang ditelan zaman. Jika satu bunyi terlupa, satu cerita ikut hilang, {nama}.', 1),
(799, 61, 401, NULL, 'Aku belajar bahawa alat muzik dan tarian pelbagai kaum memperlihatkan kebijaksanaan nenek moyang dan menjadi warisan yang perlu kita hargai bersama.', 2),
(800, 61, 401, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemuzik yang mengembara membawa alat muzik pelbagai kaum. Dengar setiap rentak dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(801, 60, 401, 'e4_n1_s1', 'Pakcik Pemuzik! Hujan petang tadi melunturkan kad ucapan saya. Malam ini saya mesti menyambut tetamu dalam bahasa mereka sendiri, namun saya telah tidak ingat siapakah bercakap apa.', 1),
(802, 69, 401, 'e4_n1_s1', 'Datuk saya berbual Hokkien, pakcik. Namun kawan-kawan lain di pekan ada yang bertutur Mandarin, Hakka atau Kantonis. Semuanya Cina juga.', 2),
(803, 65, 401, 'e4_n1_s1', 'Ketahuilah, kami di rumah bercakap Tamil. Ada keluarga India yang memakai Telugu, dan ada yang Malayalam.', 3),
(804, 64, 401, 'e4_n1_s1', 'Orang Melayu tentulah bahasa Melayu. Jiran saya orang Sikh, dia bertutur Punjabi dengan ibunya.', 4),
(805, NULL, 401, 'e4_n1_s1', 'Usah lupa Melaka. Kaum Serani di sana bertutur Kristang dan bahasa Inggeris, manakala Baba dan Nyonya memakai dialek Melayu Baba.', 5),
(806, 60, 401, 'e4_n1_s1', 'Banyaknya! Pakcik, tolong padankan semuanya di kad ini sebelum pentas dibuka. Namun kenapa pengacara perlu menyebut begitu banyak bahasa malam ini?', 6),
(807, 70, 401, 'e4_n1_s2', 'Pakcik, budak bandar ini kata orang kami sama dengan orang Iban dan Bidayuh. Sakit telinga saya mendengarnya.', 1),
(808, 74, 401, 'e4_n1_s2', 'Saya fikir semua orang di hutan itu satu kaum. Maaf, Tok Batin.', 2),
(809, 70, 401, 'e4_n1_s2', 'Sesungguhnya, kami Orang Asli di Semenanjung ini terbahagi kepada tiga kumpulan besar, iaitu Negrito atau Semang, Senoi dan Melayu Proto. Kami terkenal kerana masih mengekalkan kraf tangan, ubat herba dan bahasa mengikut suku.', 3),
(810, NULL, 401, 'e4_n1_s2', 'Tok Batin menulis nota kecil untuk tuan hamba, namun hujan sempat menyiram dakwatnya. Biar aku bacakan perlahan-lahan.', 4),
(811, 74, 401, 'e4_n1_s2', 'Pakcik, nota itu belum habis. Jadi siapakah sebenarnya tiga kumpulan besar Orang Asli itu, dan adakah mereka sama dengan kaum di Sarawak?', 5),
(812, 69, 401, 'e4_n1_s3', 'Pakcik, di pasar malam Melaka ini ramai yang kata Baba dan Nyonya itu Cina biasa. Namun cara mereka bercakap lain benar.', 1),
(813, NULL, 401, 'e4_n1_s3', 'Sesungguhnya, mereka lahir daripada perkahwinan pedagang dari China dengan penduduk tempatan di Melaka. Sebab itu budaya mereka bercampur dengan budaya tempatan.', 2),
(814, 65, 401, 'e4_n1_s3', 'Nenek saya pula bercerita tentang kaum Chetti. Datuk moyang mereka pedagang India yang berkahwin dengan penduduk tempatan dan mereka bertutur Melayu kreol.', 3),
(815, 64, 401, 'e4_n1_s3', 'Kaum Serani dikenali sebagai orang Eurasia, kerana datuk moyang mereka orang Portugis. Tarian mereka yang paling popular ialah branyo dan frapeirra.', 4),
(816, 71, 401, 'e4_n1_s3', 'Kaum Siam pula ramai di Kedah dan Perlis. Mereka menyambut Songkran dan beribadat di wat. Orang Sikh memakai sarban dan bertutur Punjabi.', 5),
(817, 74, 401, 'e4_n1_s3', 'Pakcik, empat kad ini telah bercampur di meja. Selepas dipadankan, apakah yang menjadikan kaum peranakan ini unik?', 6),
(818, 68, 401, 'e4_n1_s4', 'Di Sarawak, kaum Iban kaum yang paling ramai. Kami bertutur bahasa Iban, pakcik. Pakaian pua kumbu kami dipakai semasa Hari Gawai dan majlis perkahwinan.', 1),
(819, 66, 401, 'e4_n1_s4', 'Kaum paling ramai di Sabah pula Kadazandusun, dan kami berbahasa mengikut dialek sukuan masing-masing. Pesta Kaamatan nanti kami keluarkan pakaian tradisi yang paling indah.', 2),
(820, 68, 401, 'e4_n1_s4', 'Linda, usah sombong. Kaum lain di Sarawak pun banyak, ada Bidayuh, Kenyah dan Melanau.', 3),
(821, NULL, 401, 'e4_n1_s4', 'Kedua-duanya benar. Satu kaum terbesar di Sarawak, satu lagi di Sabah. Tetapi pengunjung malam ini mudah keliru, jadi biar aku baca catatan ini dengan teliti.', 4),
(822, 66, 401, 'e4_n1_s4', 'Pakcik, jika kami tersilap catat, pengunjung akan menyangka kaum lain yang paling besar. Selepas membaca catatan itu, bagaimanakah kita hendak menghargai kedua-dua kaum ini?', 5),
(823, 63, 401, 'e4_n1_s5', 'Pakcik Pemuzik, angin kuat tadi menjatuhkan papan petunjuk di pentas. Pasukan Sarawak telah berdiri di sudut Melayu!', 1),
(824, NULL, 401, 'e4_n1_s5', 'Tenang. Pentas ini ada lima sudut. Melayu dengan gambus dan angklung serta tarian makyung dan zapin. Cina dengan gendang, bo dan tarian singa.', 2),
(825, 66, 401, 'e4_n1_s5', 'India pula ada veenai dan talam serta tarian bharata natyam. Sarawak dengan sape dan engkerurai serta tarian ngajat.', 3),
(826, 68, 401, 'e4_n1_s5', 'Sabah dengan kulintangan dan sompoton, dan tarian sumazau yang kami banggakan.', 4),
(827, NULL, 401, 'e4_n1_s5', 'Kita cari lima sudut itu di pentas dan pasang semula papan petunjuk. Segera, persembahan Sabah hampir bermula.', 5),
(828, 63, 401, 'e4_n1_s5', 'Pakcik, semua sudut telah ada di pentas ini. Pada pendapat pakcik, apa yang dibawa oleh alat muzik dan tarian ini kepada negara kita?', 6),
(829, 74, 401, 'e4_n1_s6', 'Pakcik, kenapa kita masih simpan alat muzik lama begini? Saya boleh buat bunyi gambus dalam komputer sahaja.', 1),
(830, NULL, 401, 'e4_n1_s6', 'Cuba tengok bahan alat ini. Angklung dibuat daripada buluh yang diikat pada rangka yang disebut ancak. Gambus pula daripada kayu keras seperti pokok nangka.', 2),
(831, 65, 401, 'e4_n1_s6', 'Nafiri dibuat daripada logam, lazimnya perak. Geduk ialah gendang dua muka yang ditutup dengan belulang lembu atau kerbau.', 3),
(832, 66, 401, 'e4_n1_s6', 'Sape pula daripada kayu meranti dan dipetik talinya. Sompoton saya diperbuat daripada buluh yang dilekatkan pada labu kering dengan lilin kelulut.', 4),
(833, NULL, 401, 'e4_n1_s6', 'Semuanya daripada alam. Jikalau engkau tahu cara membuatnya, baru engkau sedar betapa bijaknya pencipta dahulu. Mari padankan alat dengan bahannya.', 5),
(834, 74, 401, 'e4_n1_s6', 'Wah, lilin kelulut pun boleh jadi alat muzik. Pakcik, jadi kenapa alat muzik lama begini wajar kita jaga?', 6),
(835, 65, 401, 'e4_n1_s7', 'Pakcik, tirai pentas hampir dibuka dan senarai tarian bercampur. Aku hendak menari bharata natyam namun namaku tercatat di bawah tarian lain.', 1),
(836, NULL, 401, 'e4_n1_s7', 'Biar aku betulkan. Makyung ialah seni drama yang ada lakonan, tarian, muzik dan nyanyian. Zapin pula hiburan semasa pesta dan majlis perkahwinan.', 2),
(837, 69, 401, 'e4_n1_s7', 'Tarian singa kami untuk Tahun Baharu Cina. Ia lambang keharmonian.', 3),
(838, 65, 401, 'e4_n1_s7', 'Bharata natyam pula membuka tirai persembahan kebudayaan India. Ia bermula sebelum persembahan lain.', 4),
(839, 68, 401, 'e4_n1_s7', 'Ngajat ialah tarian kami semasa Hari Gawai dan upacara ritual. Sumazau pula tarian Kadazandusun untuk menghormati semangat padi.', 5),
(840, 63, 401, 'e4_n1_s7', 'Pakcik, padankan semua tarian ini dengan tujuannya sebelum tirai dibuka. Mengapakah penting iringan muzik mengikut tarian yang benar?', 6),
(841, 70, 401, 'e4_n1_s8', 'Anak-anak, di kampung kami tarian ini bernama sewang. Penarinya menghias diri dengan selempang bunga, daun kelapa, daun palas, daun nipah dan kulit kayu.', 1),
(842, 74, 401, 'e4_n1_s8', 'Namun di atas tikar ada kad bhangra juga, Tok Batin. Yang mana sebenarnya tarian orang Asli?', 2),
(843, NULL, 401, 'e4_n1_s8', 'Alat muzik tarian itu ialah buluh centong, gendang, kereb, pensol dan tetawak. Ia untuk upacara ritual, perubatan dan majlis keramaian.', 3),
(844, 65, 401, 'e4_n1_s8', 'Bhangra pula tarian orang Sikh. Iringannya dram dhol, harmonika dan tamborin.', 4),
(845, 70, 401, 'e4_n1_s8', 'Dua kad itu tertukar oleh angin. Nak, baca dengan teliti dan pilih yang benar. Selepas itu, apa yang kita pelajari apabila mengenali tarian setiap kaum?', 5),
(846, 62, 402, NULL, 'Tugasku ialah membuka peti cerita ini satu demi satu supaya cucu-cucu tahu bagaimana datuk nenek mereka hidup, {nama}.', 1),
(847, 62, 402, NULL, 'Aku belajar bahawa petempatan dan kegiatan ekonomi dahulu berbeza, tetapi kini kita boleh tinggal bersama dan cerita rakyat memberi iktibar kepada kita.', 2),
(848, 62, 402, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, nenek yang menyimpan cerita setiap kaum. Dengar soalan cucu-cucu dan jawab dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(849, 64, 402, 'e4_n2_s1', 'Nenek, mengapakah kampung Melayu dahulu semuanya berdekatan sungai dan pantai? Saya tidak pernah nampak kampung di tengah padang pasir.', 1),
(850, 62, 402, 'e4_n2_s1', 'Sebelum merdeka, orang tinggal mengikut kerja mereka, cucu. Orang Melayu tinggal di kampung, di pesisir pantai dan tepi sungai.', 2),
(851, 62, 402, 'e4_n2_s1', 'Ada yang menjadi petani, nelayan atau peniaga kecil. Ada juga yang berkhidmat dalam perkhidmatan awam.', 3),
(852, 74, 402, 'e4_n2_s1', 'Betulkah semua orang Melayu dahulu hanya menjadi petani, nenek?', 4),
(853, 62, 402, 'e4_n2_s1', 'Tidak semua. Baca catatan di laci pertama ini dahulu, usah terus meneka. Ia menyebut siapakah yang tinggal di mana.', 5),
(854, 64, 402, 'e4_n2_s1', 'Nenek, jika kami tersilap, kami akan mengajar orang lain dengan cerita yang salah. Jadi kenapa agaknya petempatan dahulu dekat dengan sungai dan pantai?', 6),
(855, 69, 402, 'e4_n2_s2', 'Datuk saya pelombong dan peniaga di pekan. Dia tinggal di pekan sepanjang hidupnya dan tidak pernah ke ladang.', 1),
(856, 65, 402, 'e4_n2_s2', 'Datuk saya bekerja di ladang, Ah Meng. Kami tinggal di pinggir bandar.', 2),
(857, 62, 402, 'e4_n2_s2', 'Kedua-duanya benar. Orang Cina dahulu tinggal di pekan dan bandar sebagai pelombong dan peniaga.', 3),
(858, 62, 402, 'e4_n2_s2', 'Orang India pula tinggal di ladang dan pinggir bandar. Mereka pekerja ladang, peniaga kecil dan pekerja pelabuhan.', 4),
(859, NULL, 402, 'e4_n2_s2', 'Nenek, saya padankan petempatan dan pekerjaan setiap kaum ya, agar Ah Meng dan Kavitha tidak berebut cerita.', 5),
(860, 65, 402, 'e4_n2_s2', 'Sesungguhnya, selepas dipadankan, nenek, kenapa dua cerita yang nampak berbeza ini sebenarnya kedua-duanya benar?', 6),
(861, 70, 402, 'e4_n2_s3', 'Datuk nenek kami tinggal jauh di pedalaman, cucu. Rumahnya daripada buluh, tikarnya daripada rotan.', 1),
(862, 74, 402, 'e4_n2_s3', 'Nenek, apa yang mereka makan? Mereka tidak ke pasar?', 2),
(863, 62, 402, 'e4_n2_s3', 'Mereka berburu dan mengutip hasil hutan. Mereka juga membuat kraf tangan seperti anyaman.', 3),
(864, 62, 402, 'e4_n2_s3', 'Banyak di Perak, Selangor, Pahang, Kelantan dan Terengganu. Itu di pedalaman, jauh dari bandar.', 4),
(865, 70, 402, 'e4_n2_s3', 'Jadi kami tidak mengambil tanah orang. Kami hanya mengambil apa yang hutan beri.', 5),
(866, 74, 402, 'e4_n2_s3', 'Nenek, selepas membaca catatan ini, kenapa Orang Asli dahulu bergantung kepada hutan?', 6),
(867, 67, 402, 'e4_n2_s4', 'Nenek, di Sarawak kaum kami tinggal di tepi sungai. Benar, kan?', 1),
(868, 68, 402, 'e4_n2_s4', 'Benar sebahagiannya, Jenny. Kaum Iban dan Bisaya tinggal berhampiran lembah sungai dan menjadi petani.', 2),
(869, 62, 402, 'e4_n2_s4', 'Kaum Bidayuh, Kenyah dan Kelabit tinggal di pedalaman. Mereka mengusahakan padi sawah, padi bukit dan mengutip hasil hutan.', 3),
(870, 62, 402, 'e4_n2_s4', 'Orang Melayu, Melanau dan Kedayan tinggal di pesisir pantai. Mereka pedagang, pembuat perahu dan pengusaha sagu.', 4),
(871, 67, 402, 'e4_n2_s4', 'Aku hendak cerita yang benar, nenek, bukan sekadar cerita yang sedap didengar.', 5),
(872, 62, 402, 'e4_n2_s4', 'Marilah padankan kaum dengan tempat tinggal dan kerjanya. Namun cucu, menurut tuan hamba, kenapa kaum yang berbeza tinggal di tempat yang berbeza?', 6),
(873, 66, 402, 'e4_n2_s5', 'Datuk saya mengusahakan padi di pedalaman, nenek. Kaum kami, Kadazandusun, ramai di sana.', 1),
(874, 71, 402, 'e4_n2_s5', 'Kaum kami, Bajau, bekerja sebagai petani atau nelayan, Linda.', 2),
(875, 62, 402, 'e4_n2_s5', 'Murut juga tinggal di pedalaman. Mereka petani dan pengutip hasil hutan. Rungus pula terkenal dengan seni perusahaan kreatif.', 3),
(876, 62, 402, 'e4_n2_s5', 'Di pesisir pantai ada Melayu Brunei, Iranun dan Suluk. Mereka nelayan, pembuat perahu dan pedagang.', 4),
(877, NULL, 402, 'e4_n2_s5', 'Ketahuilah, setiap kaum ada peranannya. Marilah kita padankan semuanya agar tiada yang tertukar.', 5),
(878, 66, 402, 'e4_n2_s5', 'Selepas memadankannya nenek, apakah yang kita boleh simpulkan tentang kaum di Sabah?', 6),
(879, 74, 402, 'e4_n2_s6', 'Nenek, jikalau dahulu setiap kaum tinggal berasingan mengikut pekerjaan, mengapakah kini kita semua boleh tinggal dalam satu taman perumahan?', 1),
(880, 62, 402, 'e4_n2_s6', 'Sebelum merdeka, penduduk tinggal berdasarkan kegiatan ekonomi atau pekerjaan masing-masing, cucu.', 2),
(881, 62, 402, 'e4_n2_s6', 'Selepas merdeka, negara semakin makmur dan pemimpin merancang pelbagai dasar pembangunan.', 3),
(882, 62, 402, 'e4_n2_s6', 'Usaha menangani kegiatan ekonomi berasaskan kaum itu menampakkan kejayaan. Sikap toleransi diterapkan dan kita belajar bekerja bersama.', 4),
(883, 64, 402, 'e4_n2_s6', 'Maka kini kita tinggal bersama dan hidup aman tanpa pemisahan tempat tinggal.', 5),
(884, 62, 402, 'e4_n2_s6', 'Marilah susun peristiwa ini mengikut urutan. Namun cucu, apakah yang membolehkan rakyat hidup bersama dalam satu kawasan perumahan?', 6),
(885, 72, 402, 'e4_n2_s7', 'Mereka kata aku nakal kerana mempermain-mainkan raja dan pembesar. Hukuman paling berat pun ditimpakan kepadaku.', 1),
(886, 74, 402, 'e4_n2_s7', 'Nenek, bagaimanakah Si Luncai boleh terlepas daripada hukuman raja?', 2),
(887, 62, 402, 'e4_n2_s7', 'Pesuruh raja memasukkan Si Luncai ke dalam guni dan membawanya dengan perahu ke tengah laut.', 3),
(888, 72, 402, 'e4_n2_s7', 'Aku menyanyikan lagu ''Si Luncai terjun dengan labu-labunya''. Pesuruh raja ketawa dan lalai.', 4),
(889, 62, 402, 'e4_n2_s7', 'Ketika mereka lalai, Si Luncai membiarkan labu-labu itu terapung dan melepaskan diri. Cerita rakyat ini milik bersama, cucu.', 5),
(890, 62, 402, 'e4_n2_s7', 'Marilah susun kejadian ini satu demi satu. Namun cucu, apakah iktibar daripada kisah Si Luncai?', 6),
(891, 73, 402, 'e4_n2_s8', 'Aku Puteri Santubong. Aku menenun kain untuk kampung kami.', 1),
(892, 74, 402, 'e4_n2_s8', 'Nenek, mengapakah mereka bertukar menjadi gunung?', 2),
(893, 62, 402, 'e4_n2_s8', 'Puteri Sejinjang mahir menumbuk padi. Kedua-duanya disukai oleh Putera Serapi, pemuda dari Matang.', 3),
(894, 62, 402, 'e4_n2_s8', 'Dua puteri itu bertelingkah. Pasir Kuning dan Pasir Putih, dua kampung berjiran, mula berpecah sehingga mereka didamaikan.', 4),
(895, 73, 402, 'e4_n2_s8', 'Kami dilarang bergaduh. Apabila syarat itu dilanggar, kami bertukar menjadi gunung.', 5),
(896, 62, 402, 'e4_n2_s8', 'Marilah padankan watak dan peranan mereka dalam legenda ini. Namun cucu, apakah yang berlaku kepada mereka kerana melanggar syarat itu?', 6),
(897, 63, 403, NULL, 'Tugasku ialah memastikan semua kanak-kanak bermain bersama, tanpa mengira kaum, supaya mereka belajar bekerjasama, {nama}.', 1),
(898, 63, 403, NULL, 'Aku belajar bahawa permainan tradisional memupuk kerjasama, kreativiti dan persaingan sihat. Toleransi antara kaum ialah asas perpaduan.', 2),
(899, 63, 403, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga gelanggang permainan tradisional. Dengar sorakan kanak-kanak dan jawab dengan bijak. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(900, 74, 403, 'e4_n3_s1', 'Tok, kenapa congkak dimainkan di anjung namun wau dimainkan di padang? Saya tak faham mana yang permainan anjung, laman dan lapang.', 1),
(901, 63, 403, 'e4_n3_s1', 'Tiga jenis, nak. Permainan anjung seperti congkak, batu seremban, go dan chaturangam dimainkan di anjung rumah.', 2),
(902, 63, 403, 'e4_n3_s1', 'Permainan laman seperti sepak raga dimainkan di laman. Permainan lapang seperti wau, gasing dan tibau perlukan padang yang luas.', 3),
(903, 64, 403, 'e4_n3_s1', 'Kabaddi dan chap teh pun permainan laman, Tok.', 4),
(904, NULL, 403, 'e4_n3_s1', 'Marilah kita cari lima petunjuk di gelanggang ini agar semua kanak-kanak tidak tersilap tempat main.', 5),
(905, 74, 403, 'e4_n3_s1', 'Tok, jikalau tersalah letak, kami bermain di tempat yang tidak sesuai. Jadi mengapakah permainan tradisional dibahagikan kepada tiga jenis?', 6),
(906, 74, 403, 'e4_n3_s2', 'Tok, saya tersebut batu seremban sebagai congkak tadi. Betulkah beza dua-duanya?', 1),
(907, 63, 403, 'e4_n3_s2', 'Congkak dimainkan dengan mengisi buah ke dalam lubang pada papan congkak.', 2),
(908, 65, 403, 'e4_n3_s2', 'Batu seremban dimainkan dengan lima atau tujuh biji batu kecil yang dilambung dan disambut.', 3),
(909, 69, 403, 'e4_n3_s2', 'Go atau Weiqi pula menggunakan buah hitam dan putih untuk menguasai kawasan papan yang lebih besar.', 4),
(910, 64, 403, 'e4_n3_s2', 'Kabaddi ialah permainan dua pasukan, tujuh pemain, yang cuba menyentuh pihak lawan. Chap teh ditating dengan bola lawi bulu ayam, dipanggil tating lawi juga. Sepak raga pula bola rotan ditimang dengan kaki sejak zaman Kesultanan Melayu.', 5),
(911, 74, 403, 'e4_n3_s2', 'Tolong padankan permainan dengan cara bermain agar tiada lagi perbalahan. Tok, apa yang patut kami buat sebelum bermain sesuatu permainan?', 6),
(912, 74, 403, 'e4_n3_s3', 'Tok, permainan lapang boleh dimainkan di mana-mana sahaja, bukan?', 1),
(913, 63, 403, 'e4_n3_s3', 'Wau lazimnya dimainkan selepas musim menuai, ketika padang lapang dan angin kuat.', 2),
(914, 67, 403, 'e4_n3_s3', 'Tibau dimainkan semasa Pesta Kaul oleh masyarakat Melanau di Sarawak.', 3),
(915, 66, 403, 'e4_n3_s3', 'Sepak manggis dimainkan di Kota Belud, Sabah, dalam majlis keramaian. Bola disepak untuk mendapat hadiah.', 4),
(916, 63, 403, 'e4_n3_s3', 'Gasing ada gasing uri dan gasing pangkah. Padankan semuanya, nak.', 5),
(917, 74, 403, 'e4_n3_s3', 'Tok, kenapa semua permainan ini dimainkan di padang, bukan di anjung?', 6),
(918, 69, 403, 'e4_n3_s4', 'Tok, yoyo Cina dan go itu dari China. Orang Melayu tidak main, bukan?', 1),
(919, 65, 403, 'e4_n3_s4', 'Kami main chaturangam dan paramapadham di rumah. Kedua-duanya datang dari India.', 2),
(920, 63, 403, 'e4_n3_s4', 'Permainan di negara kita ada unsur dari Timur Tengah, China, India dan Alam Melayu. Semua dimainkan bersama.', 3),
(921, 65, 403, 'e4_n3_s4', 'Chaturangam dimainkan oleh dua orang pemain, seolah-olah peperangan. Kemenangan bergantung pada menewaskan raja.', 4),
(922, NULL, 403, 'e4_n3_s4', 'Paramapadham pula seperti dam ular dan menggunakan dadu. Baca kad ini dan pilih permainan yang seperti catur.', 5),
(923, 69, 403, 'e4_n3_s4', 'Tok, jadi apa maknanya apabila budak-budak pelbagai kaum bermain permainan dari budaya lain?', 6),
(924, 74, 403, 'e4_n3_s5', 'Tok, bolehkah bola sepak dan badminton dikatakan permainan warisan?', 1),
(925, 63, 403, 'e4_n3_s5', 'Tidak semua permainan tercatat dalam senarai warisan kebangsaan, nak.', 2),
(926, 63, 403, 'e4_n3_s5', 'Papan di pintu ini menyenaraikan congkak, batu seremban, kabaddi, tating lawi dan menyumpit.', 3),
(927, 66, 403, 'e4_n3_s5', 'Ada juga pistol buluh, sepak raga, ketinting, baling tin dan ketuk keli, Tok.', 4),
(928, 63, 403, 'e4_n3_s5', 'Semuanya diangkat sebagai warisan kebangsaan agar generasi akan datang tidak melupakannya.', 5),
(929, 74, 403, 'e4_n3_s5', 'Tok, saya baca papan itu dahulu. Namun kenapa permainan tradisional perlu diangkat sebagai warisan?', 6),
(930, 66, 403, 'e4_n3_s6', 'Dalam cerita nenek moyang, di tepi Sungai Liwagu ada sebatang pohon nunuk yang besar. Penduduk berehat di bawahnya.', 1),
(931, 71, 403, 'e4_n3_s6', 'Lalu seekor ayam gergasi merah bertaji emas mengibar sayap, dan penduduk terbang mengikutnya.', 2),
(932, 66, 403, 'e4_n3_s6', 'Penduduk berpecah di Tambunan dan Ranau. Mereka membina dialek masing-masing.', 3),
(933, 71, 403, 'e4_n3_s6', 'Itulah Nunuk Ragang. Ia kisah asal usul pelbagai kaum di Sabah.', 4),
(934, NULL, 403, 'e4_n3_s6', 'Marilah kita cari tiga petunjuk legenda ini di dalam gambar.', 5),
(935, 66, 403, 'e4_n3_s6', 'Jikalau tersilap, asal usul kaum kami menjadi kabur. Jadi, apakah yang kita pelajari daripada legenda Nunuk Ragang?', 6),
(936, 74, 403, 'e4_n3_s7', 'Maka mereka bercakap bahasa lain dan ketawa. Saya rasa mereka mengejek kami.', 1),
(937, 69, 403, 'e4_n3_s7', 'Kami hanya bercakap Hokkien dengan datuk. Mengapakah tuan hamba marah?', 2),
(938, 63, 403, 'e4_n3_s7', 'Jikalau tidak bertoleransi, perbalahan kecil boleh menjadi pergaduhan besar.', 3),
(939, 63, 403, 'e4_n3_s7', 'Toleransi menjaga keharmonian dan kesejahteraan negara. Ia mengukuhkan semangat patriotisme dan mengelakkan salah faham antara kaum.', 4),
(940, NULL, 403, 'e4_n3_s7', 'Marilah baca kad ini dan fikirkan kepentingan toleransi antara kaum.', 5),
(941, 63, 403, 'e4_n3_s7', 'Namun budak-budak ini masih berdiri begitu. Pada pendapat tuan hamba, apa yang perlu kita lakukan apabila tidak faham bahasa orang lain?', 6),
(942, 74, 403, 'e4_n3_s8', 'Tok, untuk apa kita simpan semua budaya lama ini? Siapakah yang peduli?', 1),
(943, 64, 403, 'e4_n3_s8', 'Pelancong itu peduli. Mereka datang kerana keunikan seni warisan kita.', 2),
(944, 63, 403, 'e4_n3_s8', 'Keunikan seni tradisional kita berbeza daripada negara lain. Ia memupuk semangat patriotisme dalam diri rakyat.', 3),
(945, 63, 403, 'e4_n3_s8', 'Keunikan budaya tempatan ialah warisan negara yang perlu dipelihara. Berkongsi maklumat tentang kaum pula memupuk persefahaman.', 4),
(946, NULL, 403, 'e4_n3_s8', 'Hormat-menghormati mengeratkan perpaduan. Marilah padankan kepentingannya.', 5),
(947, 74, 403, 'e4_n3_s8', 'Tok, jikalau begitu, apa yang patut saya lakukan agar budaya ini terus hidup?', 6),
(948, 81, 501, NULL, 'Tugasku ialah mencatat agama dan kepercayaan dengan adil dan hormat. Satu catatan yang salah boleh menyinggung hati sebuah masyarakat, {nama}.', 1),
(949, 81, 501, NULL, 'Aku belajar bahawa setiap agama menuntut penganutnya melakukan perkara baik. Menghormati agama kaum lain menjamin kehidupan aman dan sejahtera.', 2),
(950, 81, 501, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengkaji yang membawa buku nota lapangan. Catat dengan teliti dan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(951, 81, 501, 'e5_n1_s1', 'Selamat datang ke Pameran Tujuh Pintu. Ini buku nota lapangan engkau. Namun lihat meja pertama itu, kad pengasas agama telah bertukar-tukar tempat dek budak-budak berlari tadi.', 1),
(952, 84, 501, 'e5_n1_s1', 'Kami penganut Islam hanya menyembah Allah Yang Maha Esa. Kad kami tiada nama pengasas lain di atasnya.', 2),
(953, 85, 501, 'e5_n1_s1', 'Agama Kristian dibawa oleh Jesus Christ. Ada yang tersilap letak nama lain pada kad saya.', 3),
(954, 86, 501, 'e5_n1_s1', 'Agama Buddha diasaskan oleh Siddharta Gautama. Tadi kad saya dilekatkan nama Guru Nanak pula!', 4),
(955, 88, 501, 'e5_n1_s1', 'Guru Nanak itu pengasas agama Sikh, jadi kad itu milik kami. Kenny, ajaran engkau pun terbalik juga, bukan?', 5),
(956, 89, 501, 'e5_n1_s1', 'Benar. Ajaran Konfusius diasaskan oleh Kung Fu Tze, dan ajaran Tao diasaskan oleh Lao Tzu.', 6),
(957, 81, 501, 'e5_n1_s1', 'Lengkaplah telah. Kini tolong padankan setiap agama dengan pengasasnya sebelum pengunjung tiba. Namun kenapa kita perlu berhati-hati ketika mencatat nota tentang agama orang lain?', 7),
(958, 85, 501, 'e5_n1_s2', 'Cikgu pengkaji, rak kitab suci ini kacau-bilau. Bible saya terselit di sebelah al-Quran tanpa label.', 1),
(959, 84, 501, 'e5_n1_s2', 'Kitab kami ialah al-Quran, dan ajaran kami juga berpandukan Hadis. Tolong letakkan dengan penuh hormat.', 2),
(960, 87, 501, 'e5_n1_s2', 'Veda ialah kitab suci agama Hindu. Usah disorok di bawah buku lain.', 3),
(961, 86, 501, 'e5_n1_s2', 'Agama Buddha pula berpandukan kitab Tipitaka.', 4),
(962, 88, 501, 'e5_n1_s2', 'Sri Guru Granth Sahib ialah kitab suci agama Sikh. Kami menyimpannya di tempat yang tinggi dan bersih.', 5),
(963, 89, 501, 'e5_n1_s2', 'Dan Tao Te Ching ialah buku ajaran Tao. Usah terbalik dengan Analek yang milik ajaran Konfusius.', 6),
(964, 81, 501, 'e5_n1_s2', 'Nampaknya kerja engkau telah jelas. Padankan semua kitab dengan agamanya. Namun apa maknanya jikalau kita meletakkan kitab suci orang lain sesuka hati?', 7),
(965, 98, 501, 'e5_n1_s3', 'Cikgu, kawan-kawan ketawa apabila Kavitha berkata dia percaya kelahiran semula. Saya tidak faham bahagian itu.', 1),
(966, 87, 501, 'e5_n1_s3', 'Aku bukan hendak bergurau. Dalam kitab Veda kami, ada Hukum Karma yang berkait dengan kelakuan manusia semasa hidup.', 2),
(967, 87, 501, 'e5_n1_s3', 'Perbuatan baik atau buruk di dunia ini akan menentukan kelahiran semula selepas mati. Itulah yang kami yakini.', 3),
(968, NULL, 501, 'e5_n1_s3', 'Kad ini pun tertulis begitu. Penganut agama Hindu mempercayai Hukum Karma dan kelahiran semula selepas mati.', 4),
(969, 98, 501, 'e5_n1_s3', 'Oh, jadi itu bukan sebuah dongeng. Namun jikalau begitu, bagaimanakah kami patut bersikap terhadap kepercayaan Kavitha?', 5),
(970, 89, 501, 'e5_n1_s4', 'Pengunjung tadi menyangka ajaran Konfusius dan ajaran Tao itu sama. Saya cuba menerangkan namun mereka tidak percaya.', 1),
(971, 86, 501, 'e5_n1_s4', 'Aku ada dengar, Konfusius mementingkan moral dalam sebuah buku. Apa nama buku itu, Kenny?', 2),
(972, 89, 501, 'e5_n1_s4', 'Analek. Ajaran Konfusius diasaskan oleh Kung Fu Tze dan menekankan prinsip moral yang tinggi, seperti perikemanusiaan dan kesusilaan.', 3),
(973, 89, 501, 'e5_n1_s4', 'Anak-anak juga diajar taat kepada ibu bapa. Itu bukan ajaran Tao, kerana Tao bermaksud jalan.', 4),
(974, NULL, 501, 'e5_n1_s4', 'Kad ini pun menyebut perkara yang sama, Kenny. Aku akan membacanya kepada pengunjung dengan hormat.', 5),
(975, 89, 501, 'e5_n1_s4', 'Terima kasih. Tolong cakap pada mereka, ajaran ini mementingkan perikemanusiaan, kesusilaan dan ketaatan kepada ibu bapa. Lalu bagaimanakah jikalau ada yang masih berkata kedua-dua ajaran itu sama?', 6),
(976, 98, 501, 'e5_n1_s5', 'Cikgu, mengapakah ada begitu banyak agama di Malaysia? Adakah semuanya dibawa orang luar sahaja?', 1),
(977, 81, 501, 'e5_n1_s5', 'Soalan yang baik. Nota lapangan kita menyebut agama Islam, Kristian, Buddha, Hindu dan Sikh, serta ajaran Konfusius dan Tao. Semuanya tersebar dengan cara yang berbeza.', 2),
(978, 84, 501, 'e5_n1_s5', 'Sebahagiannya tersebar melalui peranan pemerintah yang menerima sesuatu agama, lalu rakyatnya mengikut.', 3),
(979, 86, 501, 'e5_n1_s5', 'Para pedagang yang berdagang dari negeri jauh juga membawa agama mereka bersama barang dagangan.', 4),
(980, 87, 501, 'e5_n1_s5', 'Golongan agama pula menyebarkan ajaran, mengajar dan membina rumah ibadat di sini.', 5),
(981, NULL, 501, 'e5_n1_s5', 'Jadi cara penyebarannya melalui peranan pemerintah, pedagang dan golongan agama.', 6),
(982, 98, 501, 'e5_n1_s5', 'Aku faham kini. Namun jikalau begitu, apa yang patut kita fikirkan tentang semua agama yang telah bertapak di sini?', 7),
(983, 85, 501, 'e5_n1_s6', 'Setiap Ahad kami pergi ke gereja. Hari itu dikhaskan untuk aktiviti keagamaan kami.', 1),
(984, 88, 501, 'e5_n1_s6', 'Maka kami penganut Sikh percaya kepada satu Tuhan bernama Waheguru.', 2),
(985, 84, 501, 'e5_n1_s6', 'Agama Islam mempunyai dua teras, iaitu Rukun Islam dan Rukun Iman. Itulah asas amalan kami.', 3),
(986, 86, 501, 'e5_n1_s6', 'Dalam agama Buddha, kami berpegang kepada Empat Kebenaran Mulia dan Jalan Lapan Lapis Mulia.', 4),
(987, 89, 501, 'e5_n1_s6', 'Dan ajaran Tao pula menekankan bahawa Tao bermaksud jalan, iaitu hidup harmoni dengan alam.', 5),
(988, 81, 501, 'e5_n1_s6', 'Cantik. Padankan kelima-lima amalan itu dengan agama atau ajarannya. Namun mengapakah kita perlu belajar amalan agama yang berbeza daripada kita?', 6),
(989, 98, 501, 'e5_n1_s7', 'Cikgu, pelancong tadi memanggil semua rumah ibadat ''temple''. Betulkah semuanya sama?', 1),
(990, 81, 501, 'e5_n1_s7', 'Tidak, nak. Penganut Islam beribadat di masjid, dan penganut Kristian di gereja.', 2),
(991, 87, 501, 'e5_n1_s7', 'Kuil ialah rumah ibadat bagi penganut Hindu, manakala gurdwara ialah rumah ibadat bagi penganut Sikh.', 3),
(992, 86, 501, 'e5_n1_s7', 'Penganut Buddha biasanya ke wat atau tokong. Tokong juga rumah ibadat bagi ajaran Konfusius dan Tao.', 4),
(993, NULL, 501, 'e5_n1_s7', 'Enam bangunan di peta ini semuanya milik agama yang berbeza. Aku mesti mencarinya.', 5),
(994, 98, 501, 'e5_n1_s7', 'Segera, bas pelancong akan bergerak sebentar lagi! Bagaimanakah jikalau mereka masuk tanpa tahu nama rumah ibadat itu?', 6),
(995, 88, 501, 'e5_n1_s8', 'Cikgu pengkaji, kita telah mengenal semua agama dan ajaran. Namun untuk apa kita beragama?', 1),
(996, 85, 501, 'e5_n1_s8', 'Mama kata agama mengajar kita menjadi orang baik.', 2),
(997, 89, 501, 'e5_n1_s8', 'Benar, namun apa kepentingannya kepada seluruh masyarakat?', 3),
(998, 81, 501, 'e5_n1_s8', 'Kad refleksi ini menjawabnya. Amalan agama dan kepercayaan menjadikan masyarakat lebih maju dan hidup dalam suasana harmoni.', 4),
(999, 81, 501, 'e5_n1_s8', 'Ia memastikan masyarakat sentiasa berdisiplin, dan memimpin masyarakat supaya mempunyai matlamat dalam kehidupan.', 5),
(1000, NULL, 501, 'e5_n1_s8', 'Maju, harmoni, berdisiplin dan bermatlamat. Aku akan tulis begitu dalam laporan nota lapangan.', 6),
(1001, 88, 501, 'e5_n1_s8', 'Kami semua setuju. Jadi jikalau kita telah tahu kepentingannya, bagaimanakah kita patut menjawab pertanyaan itu pada para pengunjung?', 7),
(1002, 82, 502, NULL, 'Tugasku ialah mengingatkan semua orang bahawa kepercayaan setiap kaum perlu difahami dan dihormati, {nama}.', 1),
(1003, 82, 502, NULL, 'Aku belajar bahawa kepercayaan masyarakat dipengaruhi oleh alam semesta. Semua agama dan kepercayaan menuntut penganutnya melakukan perkara baik.', 2),
(1004, 82, 502, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ketua bomoh Kadazandusun yang menjaga semangat padi. Dengar setiap wakil dengan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1005, 98, 502, 'e5_n2_s1', 'Bobohizan, orang kampung kata gua, pokok dan batu besar itu ada roh. Adakah itu juga satu agama?', 1),
(1006, 82, 502, 'e5_n2_s1', 'Itu kepercayaan nenek moyang kami, nak. Mereka menghormati semangat di sekeliling kita.', 2),
(1007, 91, 502, 'e5_n2_s1', 'Di pulau kami, orang tua-tua berkata alam semesta hidup. Gua, pokok dan batu besar mempunyai semangat, malah roh nenek moyang yang mesti dihormati.', 3),
(1008, NULL, 502, 'e5_n2_s1', 'Kad persidangan ini menyebut perkara sama. Kepercayaan itu dipengaruhi oleh alam semesta.', 4),
(1009, 82, 502, 'e5_n2_s1', 'Namanya animisme. Ingat nama itu baik-baik, kerana wakil-wakil lain akan bertanya. Namun apa yang patut kita lakukan terhadap kepercayaan yang berbeza daripada kita?', 5),
(1010, 91, 502, 'e5_n2_s2', 'Kami suku Mah Meri mengadakan Puja Pantai untuk memohon perlindungan dan pengampunan daripada semangat laut.', 1),
(1011, 90, 502, 'e5_n2_s2', 'Kami suku Temiar dan Semai pula mengadakan upacara ritual untuk menghalau kuasa jahat.', 2),
(1012, 90, 502, 'e5_n2_s2', 'Orang Asli percaya penyakit disebabkan oleh kuasa jahat. Sebab itu upacara itu penting bagi kami.', 3),
(1013, 98, 502, 'e5_n2_s2', 'Pakcik Tok Batin, kenapa upacara suku Mah Meri dan Temiar berbeza?', 4),
(1014, 82, 502, 'e5_n2_s2', 'Setiap suku ada pegangan dan alasannya sendiri, nak. Engkau yang pegang kad, padankan mereka dengan upacara dan tujuannya.', 5),
(1015, NULL, 502, 'e5_n2_s2', 'Mah Meri dengan Puja Pantai, Temiar dan Semai dengan upacara halau kuasa jahat, dan kepercayaan Orang Asli tentang penyakit itu.', 6),
(1016, 90, 502, 'e5_n2_s2', 'Benar. Nah, selepas engkau mengetahuinya, bagaimanakah engkau akan melayan upacara yang berbeza daripada adatmu?', 7),
(1017, 92, 502, 'e5_n2_s3', 'Kami masyarakat Iban percaya Petara akan menyampaikan alamat dan petanda melalui mimpi dan bayangan.', 1),
(1018, 83, 502, 'e5_n2_s3', 'Dan untuk memuja Petara, kami mengadakan upacara Miring. Aku Lemambang, penyair yang melakukan upacara itu.', 2),
(1019, 83, 502, 'e5_n2_s3', 'Upacara Miring bermula dengan bacaan jampi mantera. Setelah itu barulah semua perkara lain dijalankan.', 3),
(1020, 98, 502, 'e5_n2_s3', 'Namun, Pakcik Lemambang, siapakah sebenarnya Petara itu? Adakah nama tempat?', 4),
(1021, 94, 502, 'e5_n2_s4', 'Masyarakat Bisaya di Sarawak bekerja sebagai petani. Kami percaya kuasa ghaib wujud di tanah.', 1),
(1022, 94, 502, 'e5_n2_s4', 'Sebelum membuka kawasan pertanian baharu, kami membaca jampi mantera agar tiada gangguan kuasa ghaib.', 2),
(1023, 98, 502, 'e5_n2_s4', 'Pakcik, bagaimanakah jikalau ada orang yang jatuh sakit akibat gangguan itu?', 3),
(1024, 94, 502, 'e5_n2_s4', 'Kami adakan upacara untuk menghalau kuasa ghaib daripada badan pesakit. Upacara itu bernama Tamarok.', 4),
(1025, NULL, 502, 'e5_n2_s4', 'Nota ini pun menyebut perkara yang sama. Upacara Tamarok menghalau kuasa ghaib daripada badan pesakit.', 5),
(1026, 94, 502, 'e5_n2_s4', 'Benar, nak. Namun jika engkau ke kampung kami, bagaimanakah engkau akan menunjukkan rasa hormat kepada upacara ini?', 6),
(1027, 95, 502, 'e5_n2_s5', 'Kami masyarakat Bajau ada dua upacara besar. Di Kota Belud, pantai barat Sabah, kami mengadakan Ngeduang.', 1),
(1028, 95, 502, 'e5_n2_s5', 'Ketahuilah, dalam Ngeduang, keluarga si mati menjamu tetamu sebagai sedekah.', 2),
(1029, 98, 502, 'e5_n2_s5', 'Dan di Semporna pula, Pakcik?', 3),
(1030, 95, 502, 'e5_n2_s5', 'Di Semporna, pantai timur Sabah, kami mengadakan Mag''ombo. Upacara itu menghargai dan menghormati warisan nenek moyang kami.', 4),
(1031, NULL, 502, 'e5_n2_s5', 'Jadi Ngeduang bersama Kota Belud, dan Mag''ombo bersama Semporna. Aku akan padankan semuanya di kad ini.', 5),
(1032, 95, 502, 'e5_n2_s5', 'Benar. Walaupun lokasinya berbeza, apakah yang sama pada kedua-dua upacara ini?', 6),
(1033, 93, 502, 'e5_n2_s6', 'Bobohizan, apakah sebenarnya Kinorohingan? Ada orang kata itu nama kampung.', 1),
(1034, 82, 502, 'e5_n2_s6', 'Bukan, Linda. Kinorohingan ialah Tuhan yang kami minta keselamatan dan perlindungan.', 2),
(1035, 98, 502, 'e5_n2_s6', 'Dan Magavau, Bobohizan?', 3),
(1036, 93, 502, 'e5_n2_s6', 'Magavau, atau Maga''au, ialah upacara semangat padi semasa Pesta Kaamatan. Ia diketuai oleh Bobohizan.', 4),
(1037, 82, 502, 'e5_n2_s6', 'Ya, Bobohizan itulah ketua bomoh yang mengetuai upacara.', 5),
(1038, NULL, 502, 'e5_n2_s6', 'Jadi Kinorohingan ialah Tuhan, Magavau ialah upacara semangat padi, dan Bobohizan ialah ketua bomoh. Aku akan padankan semuanya.', 6),
(1039, 93, 502, 'e5_n2_s6', 'Benar. Namun mengapakah masyarakat kami memanggil nama Tuhan sebelum menuai padi?', 7),
(1040, 95, 502, 'e5_n2_s7', 'Upacara Mag''ombo dan Ngeduang berbeza lokasi, namun kedua-duanya warisan kami.', 1),
(1041, 98, 502, 'e5_n2_s7', 'Di mana kita boleh nampak tanda-tanda upacara itu di perkampungan atas air ini?', 2),
(1042, 95, 502, 'e5_n2_s7', 'Perahu berhias itu untuk Mag''ombo di Semporna, dan gerbang upacara menghargai warisan turun-temurun kami.', 3),
(1043, 95, 502, 'e5_n2_s7', 'Tikar jamuan di tepi rumah pula untuk Ngeduang, kerana keluarga menjamu tetamu sebagai sedekah di Kota Belud. Rumah di atas air itu ialah perkampungan Bajau di pantai timur.', 4),
(1044, NULL, 502, 'e5_n2_s7', 'Perahu berhias dan gerbang upacara untuk Mag''ombo. Tikar jamuan untuk Ngeduang. Aku akan cari keempat-empatnya.', 5),
(1045, 95, 502, 'e5_n2_s7', 'Teliti ya, usah terlepas yang di tikar jamuan. Jika kita hendak belajar budaya Bajau, bagaimanakah caranya agar mereka tidak tersinggung?', 6),
(1046, 82, 502, 'e5_n2_s8', 'Aku Bobohizan, ketua bomoh Kadazandusun. Aku mengetuai Magavau semasa Pesta Kaamatan.', 1),
(1047, 83, 502, 'e5_n2_s8', 'Aku Lemambang, penyair upacara Miring masyarakat Iban.', 2),
(1048, 91, 502, 'e5_n2_s8', 'Maka kami suku Mah Meri melakukan Puja Pantai di Pulau Carey.', 3),
(1049, 94, 502, 'e5_n2_s8', 'Masyarakat Bisaya mengadakan Tamarok untuk menghalau kuasa ghaib.', 4),
(1050, 95, 502, 'e5_n2_s8', 'Dan masyarakat Bajau mengadakan Ngeduang dan Mag''ombo.', 5),
(1051, NULL, 502, 'e5_n2_s8', 'Aku akan padankan setiap penjaga adat dengan kaum atau upacaranya, satu demi satu.', 6),
(1052, 82, 502, 'e5_n2_s8', 'Sebelum persidangan ditutup, apakah yang engkau hendak bawa pulang sebagai pelajaran daripada semua kepercayaan ini?', 7),
(1053, 83, 503, NULL, 'Tugasku ialah melagukan syair yang mengajak semua orang memahami hak beragama dan menghormati rumah ibadat, {nama}.', 1),
(1054, 83, 503, NULL, 'Aku belajar bahawa Perlembagaan Persekutuan menjamin agama lain boleh diamalkan dengan aman dan damai. Kita juga perlu menjaga adab di rumah ibadat.', 2),
(1055, 83, 503, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penyair upacara yang melagukan puji-pujian. Dengar syair dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1056, 98, 503, 'e5_n3_s1', 'Cikgu, bagaimanakah agama Islam diakui sebagai agama Persekutuan? Adakah ia berlaku dalam satu hari?', 1),
(1057, 96, 503, 'e5_n3_s1', 'Tidak, nak. Menjelang 1957, parti politik dan pertubuhan menghantar memorandum kepada Suruhanjaya Perlembagaan Tanah Melayu 1957.', 2),
(1058, 83, 503, 'e5_n3_s1', 'Ketahuilah, selepas itu, agama Islam diakui sebagai agama Persekutuan. Kemudian kedudukannya termaktub dalam Perkara 3 Perlembagaan Persekutuan.', 3),
(1059, 96, 503, 'e5_n3_s1', 'Kini, apa-apa perubahan perlu mendapat titah perkenan Yang di-Pertuan Agong dan Raja-Raja Melayu.', 4),
(1060, NULL, 503, 'e5_n3_s1', 'Memorandum, diakui sebagai agama Persekutuan, termaktub dalam Perkara 3, dan perubahan perlu titah perkenan. Aku akan susun kad ikut urutan itu.', 5),
(1061, 98, 503, 'e5_n3_s1', 'Jikalau salah, murid akan hafal sejarah yang salah! Jadi mengapakah kedudukan ini perlu dihormati oleh semua orang?', 6),
(1062, 96, 503, 'e5_n3_s2', 'Beta ialah Ketua Agama Islam di negeri beta, kerana negeri ini mempunyai Raja. Itulah isi Perkara 3 (2).', 1),
(1063, 97, 503, 'e5_n3_s2', 'Negeriku tiada Raja, sebagaimana Melaka, Pulau Pinang, Sabah dan Sarawak. Menurut Perkara 3 (3), Yang di-Pertuan Agong menjadi Ketua Agama Islam di sini.', 2),
(1064, 98, 503, 'e5_n3_s2', 'Cikgu, bagaimanakah dengan Kuala Lumpur, Labuan dan Putrajaya?', 3),
(1065, 83, 503, 'e5_n3_s2', 'Perkara 3 (5) menyatakan bahawa Yang di-Pertuan Agong juga menjadi Ketua Agama Islam bagi ketiga-tiga wilayah itu.', 4),
(1066, 96, 503, 'e5_n3_s2', 'Perkara 3 (1) pula menyatakan agama Islam ialah agama Persekutuan, namun agama lain boleh diamalkan dengan aman dan damai.', 5),
(1067, NULL, 503, 'e5_n3_s2', 'Aku akan padankan setiap peruntukan Perkara 3 dengan isinya.', 6),
(1068, 98, 503, 'e5_n3_s2', 'Cikgu, jadi siapakah sebenarnya Ketua Agama Islam bagi negeri yang tidak mempunyai Raja?', 7),
(1069, 88, 503, 'e5_n3_s3', 'Ada orang kata kami penganut agama minoriti tidak bebas beragama. Betulkah?', 1),
(1070, 85, 503, 'e5_n3_s3', 'Aku pernah dengar ada Perkara 11 dalam Perlembagaan. Apa isinya?', 2),
(1071, NULL, 503, 'e5_n3_s3', 'Perkara 11 (1) menyatakan tiap-tiap orang berhak menganuti dan mengamalkan agamanya.', 3),
(1072, 83, 503, 'e5_n3_s3', 'Perkara 11 (3)(a) pula menyatakan tiap-tiap kumpulan agama berhak menguruskan hal ehwal agamanya sendiri.', 4),
(1073, 88, 503, 'e5_n3_s3', 'Jadi kami memang dijamin! Pemuda itu tersilap besar, dan kita perlu tunjukkan kad ini kepadanya.', 5),
(1074, 88, 503, 'e5_n3_s3', 'Namun jikalau Perlembagaan telah menjamin hak beragama setiap orang, apakah sikap yang patut kita ambil?', 6),
(1075, 98, 503, 'e5_n3_s4', 'Cikgu, rumah ibadat di pameran ini macam kuil semua. Boleh masuk sahaja?', 1),
(1076, 87, 503, 'e5_n3_s4', 'Tidak boleh begitu. Setiap rumah ibadat ada adab dan namanya sendiri.', 2),
(1077, 84, 503, 'e5_n3_s4', 'Masjid ialah rumah ibadat bagi penganut Islam, dan gereja bagi penganut Kristian.', 3),
(1078, 88, 503, 'e5_n3_s4', 'Gurdwara ialah rumah ibadat bagi penganut Sikh, dan kuil bagi penganut Hindu.', 4),
(1079, 86, 503, 'e5_n3_s4', 'Wat atau tokong ialah rumah ibadat bagi penganut Buddha, manakala tokong juga rumah ibadat bagi ajaran Konfusius dan ajaran Tao.', 5),
(1080, NULL, 503, 'e5_n3_s4', 'Aku akan cari keenam-enam rumah ibadat itu dan kenal pasti agamanya.', 6),
(1081, 89, 503, 'e5_n3_s4', 'Segera, sebelum pengunjung masuk tanpa memahami adab. Jadi sebelum melangkah ke dalam, apa yang patut kita lakukan?', 7),
(1082, 84, 503, 'e5_n3_s5', 'Masjid Negara di Kuala Lumpur dirasmikan pada 27 Ogos 1965. Ia boleh menampung 15 000 jemaah.', 1),
(1083, 98, 503, 'e5_n3_s5', 'Namun masjid mana yang dibina pada abad ke-18?', 2),
(1084, 84, 503, 'e5_n3_s5', 'Masjid Kampung Laut. Ia dibina pada abad ke-18 dan antara masjid tertua di Alam Melayu.', 3),
(1085, 84, 503, 'e5_n3_s5', 'Dan Masjid Al-Qadim di Sibu dibina pada 1830 oleh Tuan Haji Salam Minangkabau.', 4),
(1086, NULL, 503, 'e5_n3_s5', 'Masjid Negara, Masjid Kampung Laut dan Masjid Al-Qadim. Aku akan padankan semuanya dengan maklumatnya.', 5),
(1087, 83, 503, 'e5_n3_s5', 'Benar. Nah, apakah yang patut kita buat terhadap masjid-masjid lama ini?', 6),
(1088, 85, 503, 'e5_n3_s6', 'Gereja St. Michael di Sandakan dibina pada tahun 1893. Ia gereja granit tertua di Malaysia.', 1),
(1089, 86, 503, 'e5_n3_s6', 'Wat Boonyaram di Kodiang, Kedah, ialah wat Siam Buddha yang dibina pada 1932.', 2),
(1090, 86, 503, 'e5_n3_s6', 'Tokong Cheng Hoon Teng di Melaka dibina pada 1645. Asalnya sebuah kediaman di Awan Hijau.', 3),
(1091, 87, 503, 'e5_n3_s6', 'Kuil Sri Rajakaliamman pula ialah kuil kaca pertama dan satu-satunya di Malaysia.', 4),
(1092, 88, 503, 'e5_n3_s6', 'Wadda Gurdwara Sahib di Pulau Pinang dibina pada 1901. Seni binanya gabungan Moor dan moden, dan ia kini tapak warisan.', 5),
(1093, NULL, 503, 'e5_n3_s6', 'Aku akan padankan kelima-lima rumah ibadat dengan keistimewaannya.', 6),
(1094, 88, 503, 'e5_n3_s6', 'Benar. Selepas engkau mengetahui keistimewaannya, apakah yang boleh kita katakan tentang rumah ibadat bersejarah ini?', 7),
(1095, 98, 503, 'e5_n3_s7', 'Cikgu, mengapakah kita perlu menjaga adab di rumah ibadat orang lain?', 1),
(1096, 86, 503, 'e5_n3_s7', 'Aku takut tersilap kerana adab di setiap tempat berbeza.', 2),
(1097, 89, 503, 'e5_n3_s7', 'Jika tersilap, penganutnya boleh terguris hati.', 3),
(1098, 83, 503, 'e5_n3_s7', 'Kad ini menjawab semuanya. Memahami adab dapat menghormati kebebasan beragama kaum lain yang termaktub dalam Perlembagaan Persekutuan.', 4),
(1099, 83, 503, 'e5_n3_s7', 'Sesungguhnya, ia juga mengeratkan hubungan silaturahim dan perpaduan, membantu kita mengenali agama lain, dan menunjukkan sifat keperibadian yang terpuji.', 5),
(1100, NULL, 503, 'e5_n3_s7', 'Menghormati kebebasan beragama dan mengeratkan perpaduan. Itulah sebabnya adab penting.', 6),
(1101, 98, 503, 'e5_n3_s7', 'Saya faham kini, namun bagaimanakah jikalau ada yang berkata adab itu tidak perlu dijaga?', 7),
(1102, 98, 503, 'e5_n3_s8', 'Cikgu, saya telah faham. Namun bagaimanakah hendak merumuskannya dalam syair terakhir?', 1),
(1103, 84, 503, 'e5_n3_s8', 'Kita menghormati agama lain agar tidak berbalah.', 2),
(1104, 88, 503, 'e5_n3_s8', 'Dan agar persefahaman serta silaturahim terjaga.', 3),
(1105, 83, 503, 'e5_n3_s8', 'Menghormati agama lain mengukuhkan rasa persefahaman dalam masyarakat. Menjaga sensitiviti mendidik diri menghormati pelbagai kaum.', 4),
(1106, 83, 503, 'e5_n3_s8', 'Mengeratkan silaturahim menjadikan hubungan baik antara kaum. Hidup dalam harmoni menjadikan setiap masyarakat aman dan sejahtera, dan mengelakkan perbalahan bermakna tiada pergaduhan antara kaum.', 5),
(1107, NULL, 503, 'e5_n3_s8', 'Aku akan padankan setiap rumusan dengan alasannya.', 6),
(1108, 83, 503, 'e5_n3_s8', 'Nah, itulah bait terakhir syairku. Namun mengapakah hormat kepada kepelbagaian agama begitu penting untuk negara kita?', 7),
(1109, 101, 601, NULL, 'Tugasku ialah membuat hiasan untuk semua perayaan. Jika aku tersilap hiasan atau tarikh, pelanggan akan berasa perayaan mereka tidak dihormati, {nama}.', 1),
(1110, 101, 601, NULL, 'Aku belajar bahawa perayaan disambut penuh muhibah dan kita wajar menghormati perayaan kaum lain demi masyarakat yang harmoni.', 2),
(1111, 101, 601, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penggiat kraf yang membuat hiasan perayaan. Dengar tempahan pelanggan dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1112, 101, 601, 'e6_n1_s1', 'Musim perayaan sudah dekat, dan bengkel ini dibanjiri tempahan hiasan. Tetapi hujan menembusi atap semalam, dan kertas tarikh pada setiap tempahan basah lunyai.', 1),
(1113, 104, 601, 'e6_n1_s1', 'Aku menempah hiasan Aidilfitri. Aidilfitri disambut pada 1 Syawal mengikut kalendar Islam, selepas sebulan berpuasa.', 2),
(1114, 104, 601, 'e6_n1_s1', 'Dan Hari Raya Aidiladha pula pada 10 Zulhijah mengikut kalendar Islam. Jangan tertukar dengan Aidilfitri, ya.', 3),
(1115, 106, 601, 'e6_n1_s1', 'Tahun Baharu Cina kami pada hari pertama dalam kalendar Cina. Tanglung merah itu mesti siap sebelum itu.', 4),
(1116, 108, 601, 'e6_n1_s1', 'Krismas pada 25 Disember setiap tahun. Jangan tertukar dengan Gawai, kerana Gawai hanya pada 1 Jun.', 5),
(1117, 109, 601, 'e6_n1_s1', 'Pesta Kaamatan pula disambut pada bulan Mei setiap tahun.', 6),
(1118, NULL, 601, 'e6_n1_s1', 'Aku akan padankan semuanya dengan tarikh sebelum hiasan dihantar.', 7),
(1119, 101, 601, 'e6_n1_s1', 'Baguslah. Tetapi kenapa kita perlu berhati-hati dengan tarikh dan makna setiap perayaan, bukan sekadar menyiapkan hiasan?', 8),
(1120, 104, 601, 'e6_n1_s2', 'Penggiat Kraf, aku masih keliru antara Aidilfitri dan Aidiladha. Apa bezanya sebenarnya?', 1),
(1121, 113, 601, 'e6_n1_s2', 'Kawan saya kata dua-duanya hari raya untuk bergembira sahaja.', 2),
(1122, 101, 601, 'e6_n1_s2', 'Tidak begitu. Aidiladha disambut oleh masyarakat Islam pada 10 Zulhijah, dan diteruskan pada hari Tasyrik, iaitu 11, 12 dan 13 Zulhijah.', 3),
(1123, 101, 601, 'e6_n1_s2', 'Pada hari-hari itu umat Islam mengadakan ibadah korban dan memberikan sedekah daging korban. Aidilfitri tidak begitu.', 4),
(1124, NULL, 601, 'e6_n1_s2', 'Kad di kaunter ini pun menyebut perkara yang sama. Perayaan yang melibatkan ibadah korban ialah Hari Raya Aidiladha.', 5),
(1125, 104, 601, 'e6_n1_s2', 'Betul. Tetapi kalau kita membuat hiasan yang sama untuk kedua-duanya, adakah itu sesuai?', 6),
(1126, 106, 601, 'e6_n1_s3', 'Tahun Baharu Cina bermula pada malam sebelum hari pertama, apabila seluruh ahli keluarga berkumpul untuk makan malam bersama-sama.', 1),
(1127, 107, 601, 'e6_n1_s3', 'Kata nenekku, selepas itu perayaan berlanjutan selama 15 hari dengan sambutan di rumah dan tempat awam.', 2),
(1128, 106, 601, 'e6_n1_s3', 'Hari pertama ialah apabila Tahun Baharu Cina disambut pada hari pertama dalam kalendar Cina. Pada hari ke-15, perayaan berakhir pada hari Chap Goh Meh.', 3),
(1129, NULL, 601, 'e6_n1_s3', 'Malam sebelum itu, hari pertama, selama 15 hari, dan hari ke-15. Aku akan susun kad ini mengikut urutan.', 4),
(1130, 106, 601, 'e6_n1_s3', 'Jika silap, keluarga akan terlepas hari penting. Jadi apa sebenarnya yang diraikan dalam perayaan ini?', 5),
(1131, 105, 601, 'e6_n1_s4', 'Deepavali disambut pada bulan Aippasi mengikut kalendar masyarakat Hindu. Kami menghias rumah dengan kolam dan menyalakan pelita.', 1),
(1132, 105, 601, 'e6_n1_s4', 'Maknanya, kecerahan mengatasi kegelapan, atau kebijaksanaan mengatasi kejahilan.', 2),
(1133, 105, 601, 'e6_n1_s4', 'Thaipusam pula pada bulan ke-10 kalendar Hindu. Pembayar niat membawa persembahan kepada Dewa Murugan sebagai tanda terima kasih atau meminta hajat.', 3),
(1134, 110, 601, 'e6_n1_s4', 'Vaisakhi disambut oleh kaum Sikh pada bulan keempat, Vaisakh. Kami bersembahyang di Gurdwara dan mensyukuri hasil tanaman.', 4),
(1135, NULL, 601, 'e6_n1_s4', 'Deepavali dengan kolam dan pelita, Thaipusam dengan pembayar niat, dan Vaisakhi dengan sembahyang di Gurdwara. Aku akan padankan semuanya.', 5),
(1136, 101, 601, 'e6_n1_s4', 'Cantik. Tetapi kenapa hiasan setiap perayaan mesti sesuai dengan maknanya?', 6),
(1137, 111, 601, 'e6_n1_s5', 'Hari Gawai kami disambut pada 1 Jun oleh kaum Dayak, Iban dan Bidayuh. Kami bersyukur atas hasil tani, dan ngajat ditarikan di rumah panjang.', 1),
(1138, 109, 601, 'e6_n1_s5', 'Pesta Kaamatan pula disambut oleh kaum Kadazandusun dan Murut pada bulan Mei. Bobohizan mengetuai upacara Magavau.', 2),
(1139, 109, 601, 'e6_n1_s5', 'Tarian sumazau dan pertandingan Unduk Ngadau pula memeriahkan Pesta Kaamatan.', 3),
(1140, 111, 601, 'e6_n1_s5', 'Jangan campur-adukkan, kerana Gawai bukan Kaamatan.', 4),
(1141, NULL, 601, 'e6_n1_s5', 'Gawai dengan ngajat di rumah panjang, Kaamatan dengan Magavau, sumazau dan Unduk Ngadau. Aku akan padankan kad ini.', 5),
(1142, 109, 601, 'e6_n1_s5', 'Betul. Kedua-duanya perayaan kaum petani, tetapi apakah yang sama dan apakah yang berbeza antara keduanya?', 6),
(1143, 108, 601, 'e6_n1_s6', 'Krismas disambut pada 25 Disember. Kami memperingati kelahiran Jesus Christ, dan memberi hadiah serta menyanyi karol dari rumah ke rumah.', 1),
(1144, 107, 601, 'e6_n1_s6', 'Karol ialah nyanyian gembira atau puji-pujian semasa Krismas. Hari Wesak pula pada bulan Mei, dan kami memandikan patung Buddha Siddharta.', 2),
(1145, 107, 601, 'e6_n1_s6', 'Wesak dikaitkan dengan tiga peristiwa penting dalam hidup Siddharta Gautama, iaitu hari kelahiran, hari mencapai kesempurnaan fikiran dan hari nirwananya.', 3),
(1146, 113, 601, 'e6_n1_s6', 'Tetapi mengapa kita memandikan patung Buddha? Apa maknanya?', 4),
(1147, 107, 601, 'e6_n1_s6', 'Memandikan patung itu bermakna penyucian diri. Selepas itu kami mengagihkan makanan kepada sami.', 5),
(1148, NULL, 601, 'e6_n1_s6', 'Aku akan padankan Krismas, Wesak, mandi patung dan karol dengan maknanya.', 6),
(1149, 113, 601, 'e6_n1_s6', 'Baik. Jadi bagaimana boleh kita jelaskan maksud memandikan patung Buddha kepada kawan yang bertanya?', 7),
(1150, 101, 601, 'e6_n1_s7', 'Kali ini tempahan datang dari kampung Orang Asli. Mereka mahu hiasan tahun baharu, tetapi setiap suku menyebutnya dengan nama berbeza.', 1),
(1151, 101, 601, 'e6_n1_s7', 'Suku Jakun menyebutnya Tahon Baro, dan suku Semai menyebutnya Jis Pai. Suku Temuan pula mengenalinya sebagai Tahun Bahauk.', 2),
(1152, 101, 601, 'e6_n1_s7', 'Suku Mah Meri menyebutnya Tawun Empai. Sambutan ini bermula pada 31 Disember setiap tahun.', 3),
(1153, 113, 601, 'e6_n1_s7', 'Cikgu pernah kata suku Semai ada perayaan lain juga. Apa namanya?', 4),
(1154, 101, 601, 'e6_n1_s7', 'Suku Semai meraikan Hari Genggulang dengan berdoa agar wujud kesejahteraan di kampung. Orang Asli di Selangor dan Negeri Sembilan pula meraikan Hari Moyang.', 5),
(1155, NULL, 601, 'e6_n1_s7', 'Jakun, Semai, Temuan dan Mah Meri dengan nama tahun baharu masing-masing, serta Genggulang dan Hari Moyang. Aku akan padankan semuanya.', 6),
(1156, 101, 601, 'e6_n1_s7', 'Teliti ya. Tetapi kenapa setiap suku perlu dihormati dengan nama sambutan mereka sendiri?', 7),
(1157, 114, 601, 'e6_n1_s8', 'Setiap Jun, kapal kami dihias indah. Tahukah kamu perayaan apa ini?', 1),
(1158, 113, 601, 'e6_n1_s8', 'Pakcik nelayan, saya dengar perayaan ini ada penaung. Siapa dia?', 2),
(1159, 114, 601, 'e6_n1_s8', 'Perayaan ini disambut oleh masyarakat berketurunan Portugis di Melaka pada bulan Jun setiap tahun. Kami meraikan penaung nelayan.', 3),
(1160, 114, 601, 'e6_n1_s8', 'Tarian branyo yang diwarisi sejak dahulu ditarikan pada hari itu.', 4),
(1161, NULL, 601, 'e6_n1_s8', 'Papan perayaan ini pun menyebutnya. Kapal dihias indah dan branyo ditarikan. Perayaan itu ialah San Pedro.', 5),
(1162, 114, 601, 'e6_n1_s8', 'Betul. Tetapi bagaimana kita patut melayan perayaan masyarakat lain seperti ini, apabila datang ke pelabuhan ini?', 6),
(1163, 102, 602, NULL, 'Tugasku ialah membawa anak-anak pulang beraya dan membandingkan cara dahulu dengan cara kini, supaya mereka tahu tradisi tidak hilang, {nama}.', 1),
(1164, 102, 602, NULL, 'Aku belajar bahawa cara sambutan perayaan berubah, tetapi amalan seperti balik kampung, duit raya dan kunjung-mengunjung kekal sehingga kini.', 2),
(1165, 102, 602, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, ibu moden yang pulang beraya ke kampung. Dengar cerita nenek dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1166, 113, 602, 'e6_n2_s1', 'Mak, mengapa kita ada banyak perayaan di Malaysia? Tujuannya sama ke?', 1),
(1167, 102, 602, 'e6_n2_s1', 'Tidak sama, nak. Ada perayaan keagamaan, seperti Aidilfitri, Aidiladha, Krismas dan Thaipusam.', 2),
(1168, 112, 602, 'e6_n2_s1', 'Ada perayaan meraikan tahun baharu, seperti Tahun Baharu Cina, Tahon Baro, Jis Pai dan Tawun Empai.', 3),
(1169, 112, 602, 'e6_n2_s1', 'Ada perayaan mensyukuri hasil tanaman atau hasil laut, seperti Hari Gawai, Pesta Kaamatan, Vaisakhi dan San Pedro.', 4),
(1170, 102, 602, 'e6_n2_s1', 'Deepavali pula mengharapkan unsur baik mengatasi kejahatan. Hari Wesak mengingati tokoh agama.', 5),
(1171, NULL, 602, 'e6_n2_s1', 'Aku akan padankan lima tujuan itu dengan perayaan masing-masing.', 6),
(1172, 113, 602, 'e6_n2_s1', 'Kalau tersilap, saya akan beritahu kawan perkara yang salah. Jadi kenapa kita patut menghormati cara sambutan yang berbeza?', 7),
(1173, 113, 602, 'e6_n2_s2', 'Nenek, kenapa dahulu hantar kad? Kini cukup tekan butang sahaja.', 1),
(1174, 112, 602, 'e6_n2_s2', 'Dahulu kad ucapan dihantar melalui pos atau diserahkan sendiri. Kami menunggu berhari-hari.', 2),
(1175, 102, 602, 'e6_n2_s2', 'Sekarang ucapan dihantar melalui media elektronik dan media sosial, dalam sekelip mata.', 3),
(1176, 112, 602, 'e6_n2_s2', 'Dahulu juga kami mengambil foto keluarga di kedai gambar. Pak jurugambar yang atur kedudukan kami.', 4),
(1177, 102, 602, 'e6_n2_s2', 'Sekarang kami swafoto bersama keluarga, lalu dimuat naik di media sosial.', 5),
(1178, NULL, 602, 'e6_n2_s2', 'Aku akan padankan cara ucapan dan foto dahulu dengan kini.', 6),
(1179, 112, 602, 'e6_n2_s2', 'Jangan terbalik, nanti cucu salah faham. Jadi apakah yang masih sama walaupun caranya sudah berubah?', 7),
(1180, 112, 602, 'e6_n2_s3', 'Dahulu kami bergambar di kedai gambar dengan kamera yang besar.', 1),
(1181, 113, 602, 'e6_n2_s3', 'Mana buktinya, Nenek? Gambar lama ini kabur.', 2),
(1182, 112, 602, 'e6_n2_s3', 'Lihat betul-betul. Ada kamera lama untuk mengambil foto keluarga, latar lukisan studio di belakang, dan kerusi untuk bergambar bersama.', 3),
(1183, 112, 602, 'e6_n2_s3', 'Lampu studio pun masih kelihatan di sudut itu. Itulah bukti cara kami bergambar dahulu.', 4),
(1184, NULL, 602, 'e6_n2_s3', 'Kamera lama, latar lukisan studio, kerusi dan lampu studio. Aku akan cari keempat-empatnya dalam gambar.', 5),
(1185, 112, 602, 'e6_n2_s3', 'Teliti, cucu. Selepas kau menjumpai semuanya, apakah yang boleh kita lakukan terhadap gambar lama ini?', 6),
(1186, 105, 602, 'e6_n2_s4', 'Kolam kami kini dibuat dengan beras atau hampas kelapa yang berwarna-warni.', 1),
(1187, 112, 602, 'e6_n2_s4', 'Dahulu kolam dibuat daripada tepung.', 2),
(1188, 113, 602, 'e6_n2_s4', 'Mana satu kolam yang betul pada masa kini?', 3),
(1189, 105, 602, 'e6_n2_s4', 'Cari dalam gambar ini. Kanak-kanak melukis kolam beramai-ramai, dan keluarga duduk bersama membuat kolam pada Deepavali.', 4),
(1190, 105, 602, 'e6_n2_s4', 'Dan lihat, ada pelita di tengah kolam semasa Deepavali.', 5),
(1191, NULL, 602, 'e6_n2_s4', 'Beras berwarna-warni, kanak-kanak melukis, keluarga duduk bersama, dan pelita di tengah. Aku akan cari keempat-empatnya.', 6),
(1192, 105, 602, 'e6_n2_s4', 'Baik. Tetapi bahannya sudah berubah. Apakah yang tidak berubah?', 7),
(1193, 106, 602, 'e6_n2_s5', 'Dulu datuk makan besar di rumah. Kini keluarga kami ke restoran. Salahkah?', 1),
(1194, 112, 602, 'e6_n2_s5', 'Tidak salah. Tradisi makan besar di rumah, dengan berkumpul bersama keluarga pada malam Tahun Baharu Cina, masih diraikan.', 2),
(1195, 112, 602, 'e6_n2_s5', 'Walau bagaimanapun, ada keluarga yang memilih untuk menikmatinya di tempat lain, seperti restoran atau hotel.', 3),
(1196, NULL, 602, 'e6_n2_s5', 'Nota ini pun menyebut perkara itu. Tradisi masih diraikan, tetapi ada keluarga memilih restoran atau hotel.', 4),
(1197, 106, 602, 'e6_n2_s5', 'Betul. Tetapi supaya datukku tidak berkecil hati, apakah yang patut kita kekalkan walaupun tempatnya sudah berubah?', 5),
(1198, 113, 602, 'e6_n2_s6', 'Nek, kenapa tidak beli sahaja kuih raya? Kan lebih senang.', 1),
(1199, 112, 602, 'e6_n2_s6', 'Dahulu kuih dibuat dengan bahan dan kaedah tradisional. Kerja itu dilakukan secara gotong-royong oleh jiran dan keluarga.', 2),
(1200, 102, 602, 'e6_n2_s6', 'Seluruh rumah berbau mentega, dan anak-anak membantu membentuk kuih.', 3),
(1201, NULL, 602, 'e6_n2_s6', 'Kad ini pun menyebut perkara yang sama. Penyediaan kuih dahulu menggunakan bahan dan kaedah tradisional secara gotong-royong.', 4),
(1202, 112, 602, 'e6_n2_s6', 'Itulah dia. Jadi apakah yang kita dapat daripada kerja gotong-royong itu?', 5),
(1203, 113, 602, 'e6_n2_s7', 'Nek, kuih ini beli sahaja di kedai. Adakah tradisi sudah hilang?', 1),
(1204, 112, 602, 'e6_n2_s7', 'Tidak hilang. Kini peralatan moden memudahkan penyediaan kuih, dan kuih raya juga mudah dibeli.', 2),
(1205, 102, 602, 'e6_n2_s7', 'Lihat di kedai itu. Ada rak balang kuih raya, juruwang yang melayan pelanggan, beg hadiah dan hamper kuih yang siap dibungkus.', 3),
(1206, 102, 602, 'e6_n2_s7', 'Di pintu pula ada papan Selamat Hari Raya.', 4),
(1207, NULL, 602, 'e6_n2_s7', 'Rak balang kuih, juruwang, hamper kuih dan papan ucapan. Aku akan cari keempat-empatnya.', 5),
(1208, 113, 602, 'e6_n2_s7', 'Cepat, kedai nak tutup. Tetapi walaupun kuih dibeli, apakah yang masih kekal dalam perayaan?', 6),
(1209, 109, 602, 'e6_n2_s8', 'Dahulu pemenang Unduk Ngadau dipilih berdasarkan semangat Huminodun, iaitu kesanggupan berkorban untuk menyelamatkan generasinya.', 1),
(1210, 113, 602, 'e6_n2_s8', 'Dan kini bagaimana, Kak Linda?', 2),
(1211, 109, 602, 'e6_n2_s8', 'Kini pemenang dipilih berdasarkan sesi soal jawab tentang sejarah dan kehidupan masyarakat lampau.', 3),
(1212, NULL, 602, 'e6_n2_s8', 'Dalam gambar ini ada pemenang Unduk Ngadau dahulu, tiga peserta yang menunggu keputusan, pentas pondok di tepi sawah, dan sawah padi yang disyukuri. Aku akan mencari keempat-empatnya.', 4),
(1213, 109, 602, 'e6_n2_s8', 'Teliti, kerana ini warisan kami. Tetapi walaupun cara memilih sudah berubah, apakah nilai yang masih kekal?', 5),
(1214, 113, 602, 'e6_n2_s9', 'Nek, apa yang tidak berubah dari dahulu hingga sekarang?', 1),
(1215, 112, 602, 'e6_n2_s9', 'Banyak, nak. Setiap kali menjelang perayaan, ramai yang pulang ke tempat asal. Itulah tradisi balik ke kampung.', 2),
(1216, 102, 602, 'e6_n2_s9', 'Pemberian duit raya dan angpau pun diteruskan sehingga kini.', 3),
(1217, 112, 602, 'e6_n2_s9', 'Dan melawat jiran serta saudara kekal sebagai budaya. Orang kampung memanggilnya kunjung-mengunjung.', 4),
(1218, NULL, 602, 'e6_n2_s9', 'Kad ini pun menyebutnya. Balik ke kampung, pemberian duit raya dan angpau, dan kunjung-mengunjung kekal dalam masyarakat.', 5),
(1219, 112, 602, 'e6_n2_s9', 'Pilih dengan teliti. Selepas ini, apakah yang amalan itu lakukan kepada perpaduan kita?', 6),
(1220, 103, 603, NULL, 'Tugasku ialah melayan pelanggan semua kaum dengan hormat. Jika aku tersilap, perayaan mereka akan tersinggung, {nama}.', 1),
(1221, 103, 603, NULL, 'Aku belajar bahawa menghormati kepelbagaian sambutan perayaan mengekalkan keamanan dan keharmonian negara.', 2),
(1222, 103, 603, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, peniaga rumah kedai yang menjual keperluan semua perayaan. Layan setiap pelanggan dengan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1223, 104, 603, 'e6_n3_s1', 'Pakcik Peniaga, apakah perayaan yang diraikan melalui Rumah Terbuka Malaysia?', 1),
(1224, 103, 603, 'e6_n3_s1', 'Rumah terbuka ialah rumah yang dapat dikunjungi semua orang pada hari perayaan. Kerajaan Malaysia telah memutuskan enam perayaan utama sebagai Rumah Terbuka Malaysia.', 2),
(1225, 106, 603, 'e6_n3_s1', 'Aku dengar ada enam, tetapi tak ingat semuanya.', 3),
(1226, 103, 603, 'e6_n3_s1', 'Aidilfitri, Tahun Baharu Cina dan Deepavali. Kemudian Hari Gawai, Pesta Kaamatan dan Krismas.', 4),
(1227, NULL, 603, 'e6_n3_s1', 'Kad ini pun menyebut senarai itu. Aku akan tentukan yang betul.', 5),
(1228, 104, 603, 'e6_n3_s1', 'Jangan tersilap, nanti pelanggan lain kecewa. Jadi bagaimana rumah terbuka membantu kita semua?', 6),
(1229, 104, 603, 'e6_n3_s2', 'Mengapa kita perlu meraikan perayaan bersama keluarga?', 1),
(1230, 113, 603, 'e6_n3_s2', 'Hanya telefon sahaja pun cukup, bukan?', 2),
(1231, 103, 603, 'e6_n3_s2', 'Meraikan perayaan bersama keluarga dapat mengeratkan hubungan dan mengukuhkan perpaduan antara anggota keluarga.', 3),
(1232, 103, 603, 'e6_n3_s2', 'Ia juga mengelakkan tradisi hilang ditelan zaman dan mengekalkan kesejahteraan negara.', 4),
(1233, NULL, 603, 'e6_n3_s2', 'Kad ini pun menyebut perkara itu. Aku akan tentukan kepentingan meraikan perayaan bersama keluarga.', 5),
(1234, 104, 603, 'e6_n3_s2', 'Jawab betul-betul, kerana aku mahu ajar anakku. Jadi, kalau keluarga kita jauh, apa yang patut kita usahakan?', 6),
(1235, 106, 603, 'e6_n3_s3', 'Aku mahu melawat rumah jiran Melayu pada hari raya. Bagaimana adabnya?', 1),
(1236, 103, 603, 'e6_n3_s3', 'Setiap perayaan ada adab tersendiri. Jadi kita bertanya dahulu sebelum bertandang.', 2),
(1237, 103, 603, 'e6_n3_s3', 'Menghormati kepelbagaian sambutan dan adab perayaan dapat mengekalkan keamanan dan keharmonian negara.', 3),
(1238, 103, 603, 'e6_n3_s3', 'Ia juga memupuk semangat bertolak-ansur serta melahirkan masyarakat yang memahami dan menghormati budaya kaum lain.', 4),
(1239, NULL, 603, 'e6_n3_s3', 'Kad ini pun menyebutnya. Aku akan tentukan kepentingan menghormati kepelbagaian sambutan dan adab perayaan.', 5),
(1240, 106, 603, 'e6_n3_s3', 'Baik. Aku mahu elakkan salah faham, jadi apa yang patut aku lakukan sebelum bertandang ke rumah jiran?', 6),
(1241, 111, 603, 'e6_n3_s4', 'Dahulu Hari Gawai diraikan oleh petani kaum Dayak dengan upacara ritual. Kini ramai tetamu datang.', 1),
(1242, 106, 603, 'e6_n3_s4', 'Aku datang kerana jiranku jemput, tetapi aku keliru dengan caranya.', 2),
(1243, 111, 603, 'e6_n3_s4', 'Kini Hari Gawai diraikan oleh pelbagai kaum tanpa mengira pekerjaan.', 3),
(1244, 113, 603, 'e6_n3_s4', 'Dan Unduk Ngadau? Dahulu pemenangnya dipilih berdasarkan semangat Huminodun.', 4),
(1245, 111, 603, 'e6_n3_s4', 'Kini pemenang dipilih melalui sesi soal jawab tentang sejarah dan kehidupan lampau.', 5),
(1246, NULL, 603, 'e6_n3_s4', 'Aku akan padankan sambutan Gawai dan Unduk Ngadau dahulu dengan kini.', 6),
(1247, 111, 603, 'e6_n3_s4', 'Betulkan, supaya tetamu faham. Dan kenapa perayaan semakin meriah apabila semua kaum menyertainya?', 7),
(1248, 113, 603, 'e6_n3_s5', 'Mana satu cara dahulu dan mana satu cara kini?', 1),
(1249, 105, 603, 'e6_n3_s5', 'Aku tahu kolam dahulu dibuat daripada tepung. Kini ia daripada beras atau hampas kelapa berwarna-warni.', 2),
(1250, 106, 603, 'e6_n3_s5', 'Makan besar dahulu di rumah bersama keluarga. Kini ada keluarga memilih restoran atau hotel.', 3),
(1251, 103, 603, 'e6_n3_s5', 'Kuih dahulu dibuat dengan bahan dan kaedah tradisional secara gotong-royong. Kini peralatan moden memudahkan penyediaan kuih.', 4),
(1252, NULL, 603, 'e6_n3_s5', 'Aku akan padankan setiap tradisi dengan perubahannya.', 5),
(1253, 103, 603, 'e6_n3_s5', 'Betul. Cara berubah mengikut zaman. Tetapi apa yang patut kita kekalkan?', 6),
(1254, 113, 603, 'e6_n3_s6', 'Cikgu kata kita perlu membuat analisis SWOT tentang warisan perayaan. Apa itu?', 1),
(1255, 103, 603, 'e6_n3_s6', 'Empat bahagian. Kekuatan ialah apa yang membantu mengekalkan warisan perayaan.', 2),
(1256, 103, 603, 'e6_n3_s6', 'Kelemahan ialah apa yang menyukarkan mempertahankan warisan perayaan. Peluang ialah peluang untuk mengekalkannya.', 3),
(1257, 103, 603, 'e6_n3_s6', 'Halangan dan cabaran ialah cabaran dalam mengekalkan warisan perayaan.', 4),
(1258, NULL, 603, 'e6_n3_s6', 'Aku akan padankan setiap istilah SWOT dengan soalan yang dibincangkan.', 5),
(1259, 113, 603, 'e6_n3_s6', 'Jangan campur aduk, nanti markah dipotong. Tetapi mengapa kita perlu menganalisis warisan perayaan dengan SWOT?', 6),
(1260, 104, 603, 'e6_n3_s7', 'Boleh ringkaskan perbezaan dahulu dan kini sebelum kedai ditutup?', 1),
(1261, 113, 603, 'e6_n3_s7', 'Dan apa yang masih kekal?', 2),
(1262, 103, 603, 'e6_n3_s7', 'Balik ke kampung ialah tradisi menjelang perayaan yang kekal. Duit raya dan angpau pula pemberian yang kekal sehingga kini.', 3),
(1263, 103, 603, 'e6_n3_s7', 'Kunjung-mengunjung ialah amalan budaya yang kekal dalam masyarakat. Rumah terbuka pula rumah yang dapat dikunjungi semua orang pada hari perayaan.', 4),
(1264, NULL, 603, 'e6_n3_s7', 'Aku akan padankan setiap amalan dengan penerangannya.', 5),
(1265, 104, 603, 'e6_n3_s7', 'Jangan lupa rumah terbuka. Nah, kalau semua amalan ini dihormati, apa yang akan berlaku kepada negara kita?', 6),
(1266, 121, 701, NULL, 'Tugasku merakam siaran khas tentang Perdana Menteri. Jika tarikh atau nama salah, penonton akan menerima sejarah yang salah, {nama}.', 1),
(1267, 121, 701, NULL, 'Aku belajar bahawa pemimpin yang berjasa wajar dihormati dan pengorbanan mereka dijadikan iktibar.', 2),
(1268, 121, 701, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wartawan muda di Pejabat Perdana Menteri. Tanya dengan teliti dan catat dengan betul. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1269, 121, 701, 'e7_n1_s1', 'Lima minit lagi siaran khas bermula, dan skrip aku dipenuhi cop kopi. Penerbit minta aku sebut Perdana Menteri dipilih terus oleh rakyat. Betulkah begitu?', 1),
(1270, 132, 701, 'e7_n1_s1', 'Jangan tergesa-gesa, wartawan muda. Perdana Menteri merupakan ketua kerajaan yang mengetuai pentadbiran negara.', 2),
(1271, 132, 701, 'e7_n1_s1', 'Beliau dilantik secara rasmi oleh beta, Yang di-Pertuan Agong, Ketua Utama Negara. Tetapi beliau mesti mendapat sokongan majoriti Ahli Dewan Rakyat.', 3),
(1272, 121, 701, 'e7_n1_s1', 'Dan jawatan itu dahulu tiada, Tuanku?', 4),
(1273, 132, 701, 'e7_n1_s1', 'Jawatan Perdana Menteri diwujudkan selepas Tanah Melayu merdeka pada 31 Ogos 1957, dan kekal hingga hari ini.', 5),
(1274, NULL, 701, 'e7_n1_s1', 'Nota ini pun menyebutnya. Perdana Menteri ialah ketua kerajaan yang dilantik oleh Yang di-Pertuan Agong.', 6),
(1275, 121, 701, 'e7_n1_s1', 'Cepat, siaran bermula sebentar lagi! Jadi bagaimana aku patut menerangkan cara Perdana Menteri dilantik kepada penonton?', 7),
(1276, 121, 701, 'e7_n1_s2', 'Pita rakaman empat Perdana Menteri pertama bercampur-campur. Siapa dahulu, siapa kemudian?', 1),
(1277, 124, 701, 'e7_n1_s2', 'Beta dahulu. Tunku Abdul Rahman menjadi Perdana Menteri pertama pada 31 Ogos 1957.', 2),
(1278, 125, 701, 'e7_n1_s2', 'Aku Tun Abdul Razak. Aku menjadi Perdana Menteri kedua pada 22 September 1970.', 3),
(1279, 126, 701, 'e7_n1_s2', 'Dan aku Tun Hussein Onn, Perdana Menteri ketiga pada 15 Januari 1976.', 4),
(1280, 127, 701, 'e7_n1_s2', 'Aku pula Tun Dr. Mahathir, yang keempat pada 16 Julai 1981.', 5),
(1281, 122, 701, 'e7_n1_s2', 'Kalau pita ini terbalik, penonton akan belajar sejarah yang songsang.', 6),
(1282, NULL, 701, 'e7_n1_s2', 'Aku akan susun pita itu mengikut tarikh mereka mula berkhidmat.', 7),
(1283, 122, 701, 'e7_n1_s2', 'Ingat, tarikhnya mesti betul. Tetapi kenapa kita perlu menyusun pemimpin mengikut tarikh?', 8),
(1284, 121, 701, 'e7_n1_s3', 'Rakaman laungan kemerdekaan ini kabur. Mana buktinya kemerdekaan dicapai melalui rundingan?', 1),
(1285, 124, 701, 'e7_n1_s3', 'Beta berdiri di podium Stadium Merdeka pada 31 Ogos 1957. Beta memperjuangkan kemerdekaan secara rundingan.', 2),
(1286, 124, 701, 'e7_n1_s3', 'Lihat papan Perisytiharan Kemerdekaan Malaya di podium itu, dan poster Merdeka! Malaya! yang dipegang rakyat.', 3),
(1287, 124, 701, 'e7_n1_s3', 'Rakyat bersorak dan mengangkat tangan menyambut kemerdekaan, wartawan muda.', 4),
(1288, NULL, 701, 'e7_n1_s3', 'Tunku di podium, papan perisytiharan, poster Merdeka! Malaya!, dan rakyat yang bersorak. Aku akan cari keempat-empatnya.', 5),
(1289, 124, 701, 'e7_n1_s3', 'Tunjukkan dengan tepat. Dan bagaimana kemerdekaan itu dicapai, wartawan muda?', 6),
(1290, 121, 701, 'e7_n1_s4', 'Tunku, boleh ceritakan latar hidup Tunku untuk siaran ini?', 1),
(1291, 124, 701, 'e7_n1_s4', 'Beta dilahirkan di Alor Setar, Kedah. Beta melanjutkan pelajaran di Universiti Cambridge dalam bidang undang-undang.', 2),
(1292, 124, 701, 'e7_n1_s4', 'Beta pernah berkhidmat sebagai Pegawai Daerah di Padang Terap, Langkawi dan Sungai Petani.', 3),
(1293, 124, 701, 'e7_n1_s4', 'Pada tahun 1955, beta menjadi Ketua Menteri Persekutuan Tanah Melayu. Rakyat memberi beta gelaran Bapa Kemerdekaan.', 4),
(1294, 122, 701, 'e7_n1_s4', 'Saya bimbang tarikh dan gelaran tersilap semasa siaran.', 5),
(1295, NULL, 701, 'e7_n1_s4', 'Aku akan padankan biodata Tunku dengan maklumat yang betul.', 6),
(1296, 124, 701, 'e7_n1_s4', 'Baik. Tetapi mengapa biodata seseorang pemimpin mesti disampaikan dengan tepat?', 7),
(1297, 121, 701, 'e7_n1_s5', 'Skripku menulis Tun Razak menutup semua pejabat kerajaan selepas 13 Mei 1969. Betulkah begitu, Tun?', 1),
(1298, 125, 701, 'e7_n1_s5', 'Itu salah. Selepas peristiwa 13 Mei 1969, aku menubuhkan Majlis Gerakan Negara atau MAGERAN, untuk mengembalikan keamanan negara.', 2),
(1299, 125, 701, 'e7_n1_s5', 'Aku juga memperkenalkan Dasar Ekonomi Baru atau DEB, untuk membasmi kemiskinan rakyat dan menyusun semula masyarakat berbilang kaum.', 3),
(1300, NULL, 701, 'e7_n1_s5', 'Nota pencapaian ini pun menyebut perkara yang sama. Tun Razak menubuhkan MAGERAN dan memperkenalkan DEB.', 4),
(1301, 125, 701, 'e7_n1_s5', 'Baca betul-betul, kerana ini sejarah. Jadi mengapa dua langkah itu penting kepada masyarakat berbilang kaum?', 5),
(1302, 121, 701, 'e7_n1_s6', 'Tun Razak, di manakah rumah kelahiran Tun?', 1),
(1303, 125, 701, 'e7_n1_s6', 'Tempat lahir aku di Pulau Keladi, Pekan, Pahang.', 2),
(1304, 122, 701, 'e7_n1_s6', 'Dan pelajaran Tun di mana?', 3),
(1305, 125, 701, 'e7_n1_s6', 'Aku belajar di Kolej Melayu Kuala Kangsar, kemudian menyambung pelajaran undang-undang di Lincoln''s Inn, London.', 4),
(1306, 125, 701, 'e7_n1_s6', 'Aku pernah berkhidmat sebagai Setiausaha Kerajaan Negeri Pahang dan Menteri Besar Pahang. Rakyat memberi aku gelaran Bapa Pembangunan.', 5),
(1307, NULL, 701, 'e7_n1_s6', 'Aku akan padankan biodata Tun Razak dengan tepat.', 6),
(1308, 122, 701, 'e7_n1_s6', 'Teliti ya. Tetapi mengapa kita perlu mengetahui perjalanan hidup seseorang pemimpin?', 7),
(1309, 121, 701, 'e7_n1_s7', 'Tun Hussein, mengapa Tun digelar Bapa Perpaduan?', 1),
(1310, 126, 701, 'e7_n1_s7', 'Aku memperkenalkan Program Rukun Tetangga untuk menggalakkan perpaduan dalam kalangan rakyat berbilang kaum.', 2),
(1311, 126, 701, 'e7_n1_s7', 'Aku juga memperkenalkan Amanah Saham Nasional Berhad, supaya kaum bumiputera mudah memiliki saham dalam syarikat berhad.', 3),
(1312, 122, 701, 'e7_n1_s7', 'Saya keliru antara ASN dengan program perpaduan.', 4),
(1313, 126, 701, 'e7_n1_s7', 'Aku dilahirkan di Johor Bahru, Johor, dan menjadi Perdana Menteri dari 15 Januari 1976 hingga 16 Julai 1981.', 5),
(1314, NULL, 701, 'e7_n1_s7', 'Aku akan padankan ASN, Rukun Tetangga, gelaran, tempoh jawatan dan tempat lahir.', 6),
(1315, 126, 701, 'e7_n1_s7', 'Baik. Tetapi apakah yang patut kita lakukan terhadap program yang menyatukan rakyat berbilang kaum?', 7),
(1316, 122, 701, 'e7_n1_s8', 'Siaran khas hampir tamat. Siapa Bapa Kemerdekaan? Siapa Bapa Pembangunan?', 1),
(1317, 124, 701, 'e7_n1_s8', 'Beta, Tunku Abdul Rahman, digelar Bapa Kemerdekaan.', 2),
(1318, 125, 701, 'e7_n1_s8', 'Aku digelar Bapa Pembangunan, dan Tun Hussein digelar Bapa Perpaduan.', 3),
(1319, 127, 701, 'e7_n1_s8', 'Aku digelar Bapa Pemodenan, Tun Dr. Mahathir Mohamad.', 4),
(1320, 128, 701, 'e7_n1_s8', 'Aku Tun Abdullah Ahmad Badawi, Bapa Pembangunan Modal Insan.', 5),
(1321, NULL, 701, 'e7_n1_s8', 'Aku akan padankan gelaran dengan pemimpinnya.', 6),
(1322, 122, 701, 'e7_n1_s8', 'Ada dua yang hampir serupa, jadi teliti. Dan mengapa setiap pemimpin diberi gelaran yang berbeza?', 7),
(1323, 122, 702, NULL, 'Tugasku mengajar murid mengenali tugas Perdana Menteri. Jika aku tersilap, murid akan mempelajari fakta yang salah, {nama}.', 1),
(1324, 122, 702, NULL, 'Aku belajar bahawa kepemimpinan yang berwibawa memajukan ekonomi, menjamin keselamatan dan menyatukan rakyat.', 2),
(1325, 122, 702, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, guru Sejarah di bilik darjah. Dengar soalan murid dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1326, 123, 702, 'e7_n2_s1', 'Cikgu, gambar dalam buku teks ini hidup! Tun Dr. Mahathir keluar dari muka surat, tetapi saya tak tahu gambar ini menunjukkan tugas Perdana Menteri yang mana.', 1),
(1327, 127, 702, 'e7_n2_s1', 'Aku sedang mengadakan mesyuarat dengan Ketua-ketua Setiausaha Kementerian. Perdana Menteri ialah ketua pentadbir utama yang merancang dan menyelaraskan semua dasar negara.', 2),
(1328, 125, 702, 'e7_n2_s1', 'Aku meninjau tanaman getah di Felda Lurah Bilut. Perdana Menteri memastikan semua dasar pembangunan dapat ditingkatkan demi kesejahteraan rakyat.', 3),
(1329, 126, 702, 'e7_n2_s1', 'Aku bertemu Presiden Anwar Sadat pada 1977. Perdana Menteri menjalin hubungan diplomatik dan persahabatan dengan negara luar.', 4),
(1330, 122, 702, 'e7_n2_s1', 'Dan gambar watikah ini? Perdana Menteri mencadangkan pelantikan duta, diplomat dan konsulat, lalu Yang di-Pertuan Agong menandatangani watikahnya.', 5),
(1331, NULL, 702, 'e7_n2_s1', 'Aku akan padankan setiap gambar dengan tugas Perdana Menteri.', 6),
(1332, 123, 702, 'e7_n2_s1', 'Baik, Cikgu. Tetapi apakah tujuan semua tugas Perdana Menteri ini?', 7),
(1333, 123, 702, 'e7_n2_s2', 'Cikgu, siapa yang melantik Jemaah Menteri?', 1),
(1334, 132, 702, 'e7_n2_s2', 'Perdana Menteri mencadangkan senarai Jemaah Menteri, dan beta, Yang di-Pertuan Agong, melantik mereka.', 2),
(1335, 122, 702, 'e7_n2_s2', 'Perdana Menteri juga menasihati Yang di-Pertuan Agong berkaitan pemerintahan negara, dan mengiringi baginda ke Mesyuarat Majlis Raja-Raja.', 3),
(1336, 123, 702, 'e7_n2_s2', 'Dan siapa yang mempengerusikan mesyuarat Jemaah Menteri?', 4),
(1337, 124, 702, 'e7_n2_s2', 'Perdana Menteri sendiri. Mesyuarat Jemaah Menteri yang pertama selepas merdeka dipengerusikan oleh beta, Tunku.', 5),
(1338, NULL, 702, 'e7_n2_s2', 'Aku akan padankan setiap tugas dengan penjelasannya.', 6),
(1339, 123, 702, 'e7_n2_s2', 'Baik, Cikgu. Jadi sebenarnya siapa yang mencadangkan, dan siapa yang melantik Jemaah Menteri?', 7),
(1340, 123, 702, 'e7_n2_s3', 'Cikgu, Tun Dr. Mahathir seorang doktor perubatan, bukan?', 1),
(1341, 127, 702, 'e7_n2_s3', 'Betul. Aku dilahirkan di Seberang Perak, Alor Setar, Kedah, dan belajar perubatan di Singapura.', 2),
(1342, 127, 702, 'e7_n2_s3', 'Pada tahun 1957, aku membuka Klinik MAHA di Alor Setar. Klinik itu masih beroperasi hingga hari ini.', 3),
(1343, 127, 702, 'e7_n2_s3', 'Aku menjadi Perdana Menteri keempat dari 16 Julai 1981 hingga 30 Oktober 2003, dan gelaran aku ialah Bapa Pemodenan.', 4),
(1344, NULL, 702, 'e7_n2_s3', 'Aku akan padankan biodata Tun Dr. Mahathir dengan maklumat yang betul.', 5),
(1345, 123, 702, 'e7_n2_s3', 'Baik. Tetapi apakah kebaikan jika pemimpin berpendidikan dan berpengalaman seperti Tun?', 6),
(1346, 123, 702, 'e7_n2_s4', 'Cikgu, apa bukti Wawasan 2020 itu nyata?', 1),
(1347, 127, 702, 'e7_n2_s4', 'Pandang gambar ini. Menara Berkembar Petronas di KLCC dibina pada zaman aku, bersama KLIA dan Putrajaya.', 2),
(1348, 127, 702, 'e7_n2_s4', 'Itu kilang moden HICOM, untuk industri berteknologi tinggi. Itu pula papan carta menaik Wawasan 2020 menuju kemajuan.', 3),
(1349, 127, 702, 'e7_n2_s4', 'Jambatan layang dan jalan raya pula menunjukkan pembangunan seperti KLIA dan Putrajaya.', 4),
(1350, NULL, 702, 'e7_n2_s4', 'Menara Berkembar Petronas, kilang HICOM, papan carta Wawasan 2020, dan jambatan layang. Aku akan cari keempat-empatnya.', 5),
(1351, 123, 702, 'e7_n2_s4', 'Baik, Cikgu. Dan apakah sebenarnya tujuan Wawasan 2020 itu?', 6),
(1352, 123, 702, 'e7_n2_s5', 'Bukankah Tun Dr. Mahathir hanya sekali menjadi Perdana Menteri?', 1),
(1353, 127, 702, 'e7_n2_s5', 'Tidak. Aku menjadi Perdana Menteri kali kedua, iaitu yang ketujuh, dari 10 Mei 2018 hingga 24 Februari 2020.', 2),
(1354, 127, 702, 'e7_n2_s5', 'Aku pernah berkhidmat sebagai Pengerusi PETRONAS dan Penasihat PROTON, dan melawat Jepun, Thailand dan United Kingdom.', 3),
(1355, 123, 702, 'e7_n2_s5', 'Dan apa wawasan baharu Tun pada masa itu?', 4),
(1356, 127, 702, 'e7_n2_s5', 'Aku memperkenalkan Wawasan Kemakmuran Bersama 2030.', 5),
(1357, NULL, 702, 'e7_n2_s5', 'Nota ini pun menyebutnya. Wawasan baharu itu ialah Wawasan Kemakmuran Bersama 2030.', 6),
(1358, 123, 702, 'e7_n2_s5', 'Faham. Jadi apakah matlamat wawasan baharu itu kepada rakyat?', 7),
(1359, 123, 702, 'e7_n2_s6', 'Cikgu, Tun Abdullah ini belajar apa dahulu?', 1),
(1360, 128, 702, 'e7_n2_s6', 'Aku belajar Pengajian Islam di Universiti Malaya. Aku dilahirkan di Kampung Perlis, Bayan Lepas, Pulau Pinang.', 2),
(1361, 128, 702, 'e7_n2_s6', 'Aku pernah berkhidmat sebagai Setiausaha Majlis Gerakan Negara atau MAGERAN.', 3),
(1362, 128, 702, 'e7_n2_s6', 'Aku menjadi Perdana Menteri kelima dari 31 Oktober 2003 hingga 3 April 2009. Aku digelar Bapa Pembangunan Modal Insan.', 4),
(1363, NULL, 702, 'e7_n2_s6', 'Aku akan padankan biodata Tun Abdullah dengan maklumat yang betul.', 5),
(1364, 128, 702, 'e7_n2_s6', 'Baik. Tetapi tahukah kamu apa maksud modal insan itu?', 6),
(1365, 123, 702, 'e7_n2_s7', 'Koridor Wilayah Ekonomi dan Pelan Integriti Nasional sama ke, Cikgu?', 1),
(1366, 128, 702, 'e7_n2_s7', 'Tidak sama. Satu untuk ekonomi, satu untuk akhlak.', 2),
(1367, 128, 702, 'e7_n2_s7', 'Koridor Wilayah Ekonomi aku perkenalkan untuk memastikan pembangunan ekonomi seimbang dan kemasukan pelaburan yang besar.', 3),
(1368, 128, 702, 'e7_n2_s7', 'Pelan Integriti Nasional atau PIN pula aku perkenalkan untuk membina masyarakat yang bermoral dan beretika.', 4),
(1369, NULL, 702, 'e7_n2_s7', 'Nota ini pun menyebutnya. Pelan Integriti Nasional membina masyarakat yang bermoral dan beretika.', 5),
(1370, 128, 702, 'e7_n2_s7', 'Baca nota ini dan tentukan fungsi setiap satu. Jadi, mengapa pembangunan tidak cukup dengan ekonomi sahaja?', 6),
(1371, 123, 702, 'e7_n2_s8', 'Cikgu, apa moto 1Malaysia?', 1),
(1372, 129, 702, 'e7_n2_s8', 'Rakyat Didahulukan, Pencapaian Diutamakan. Aku memperkenalkan Gagasan 1Malaysia pada 3 April 2009.', 2),
(1373, 129, 702, 'e7_n2_s8', 'Gagasan ini bertujuan memperkukuh hubungan dan kerjasama antara kaum demi kesejahteraan negara.', 3),
(1374, 129, 702, 'e7_n2_s8', 'Aku dilahirkan di Kuala Lipis, Pahang, dan belajar ekonomi industri di Universiti Nottingham. Aku menjadi Perdana Menteri keenam dari 3 April 2009 hingga 9 Mei 2018.', 4),
(1375, 129, 702, 'e7_n2_s8', 'Aku juga melancarkan Program Transformasi Kerajaan atau GTP, untuk menjadikan negara berpendapatan tinggi selaras dengan Wawasan 2020.', 5),
(1376, NULL, 702, 'e7_n2_s8', 'Aku akan padankan biodata dan pencapaian Dato'' Sri Najib.', 6),
(1377, 129, 702, 'e7_n2_s8', 'Baik. Jadi, apakah yang ditekankan oleh Gagasan 1Malaysia kepada rakyat?', 7),
(1378, 123, 702, 'e7_n2_s9', 'Cikgu, apa sumbangan Tan Sri Muhyiddin kepada rakyat?', 1),
(1379, 130, 702, 'e7_n2_s9', 'Aku dilahirkan di Muar, Johor, dan menjadi Perdana Menteri dari 1 Mac 2020 hingga 16 Ogos 2021.', 2),
(1380, 130, 702, 'e7_n2_s9', 'Aku menubuhkan Majlis Tindakan Ekonomi atau MTE, untuk menggalakkan pertumbuhan sosioekonomi dan meningkatkan pelaburan. Semasa PKP, aku juga mengumumkan bantuan untuk rakyat.', 3),
(1381, 131, 702, 'e7_n2_s9', 'Aku Dato'' Seri Ismail Sabri. Aku dilahirkan di Temerloh, Pahang, dan menjadi Perdana Menteri mulai 20 Ogos 2021.', 4),
(1382, 131, 702, 'e7_n2_s9', 'Aku memperkenalkan konsep Keluarga Malaysia, yang meraikan keterangkuman pelbagai agama, bangsa, kaum dan usia.', 5),
(1383, NULL, 702, 'e7_n2_s9', 'Aku akan padankan sumbangan kedua-dua pemimpin itu.', 6),
(1384, 123, 702, 'e7_n2_s9', 'Baik, Cikgu. Jadi apakah yang boleh kita pelajari daripada pemimpin yang prihatin kepada rakyat?', 7),
(1385, 123, 703, NULL, 'Tugasku melengkapkan album kad koleksi dengan betul. Jika silap, projek sekolah akan menyalahkan jasa pemimpin, {nama}.', 1),
(1386, 123, 703, NULL, 'Aku belajar bahawa menghormati pemimpin dan menyokong kepimpinan negara memastikan kedaulatan dan perpaduan rakyat kekal terpelihara.', 2),
(1387, 123, 703, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, murid penyelidik dengan album kad koleksi. Semak setiap halaman dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1388, 122, 703, 'e7_n3_s1', 'Pada zaman Kesultanan Melayu Melaka, siapakah ketua pembesar kerajaan?', 1),
(1389, 123, 703, 'e7_n3_s1', 'Kalau tidak silap saya, Perdana Menteri.', 2),
(1390, 122, 703, 'e7_n3_s1', 'Tidak. Nota ini menyebut bahawa Bendahara ialah Ketua Pembesar kerajaan pada zaman Kesultanan Melayu Melaka.', 3),
(1391, 122, 703, 'e7_n3_s1', 'Pada masa ini, pentadbiran kerajaan diketuai oleh Perdana Menteri. Jawatan itu diwujudkan selepas Tanah Melayu merdeka pada 31 Ogos 1957 dan kekal hingga hari ini.', 4),
(1392, NULL, 703, 'e7_n3_s1', 'Dahulu Bendahara mengetuai pembesar, kini Perdana Menteri mengetuai pentadbiran. Aku akan tulis begitu dalam album.', 5),
(1393, 122, 703, 'e7_n3_s1', 'Teliti, jangan campur dua zaman. Jadi apakah persamaan antara kedua-dua jawatan itu?', 6),
(1394, 123, 703, 'e7_n3_s2', 'Saya sudah ada empat Perdana Menteri pertama dalam album. Lima lagi bagaimana, Cikgu?', 1),
(1395, 122, 703, 'e7_n3_s2', 'Susun mengikut tarikh mereka mula berkhidmat. Tun Abdullah Ahmad Badawi menjadi yang kelima pada 31 Oktober 2003.', 2),
(1396, 122, 703, 'e7_n3_s2', 'Dato'' Sri Najib yang keenam pada 3 April 2009. Tun Dr. Mahathir yang ketujuh, kali kedua, pada 10 Mei 2018.', 3),
(1397, 122, 703, 'e7_n3_s2', 'Muhyiddin yang kelapan pada 1 Mac 2020, dan Dato'' Seri Ismail Sabri yang kesembilan pada 20 Ogos 2021.', 4),
(1398, NULL, 703, 'e7_n3_s2', 'Aku akan padankan semuanya. Kalau tersilap, album ini tidak boleh dihantar.', 5),
(1399, 122, 703, 'e7_n3_s2', 'Betul. Jadi sejak 1957 hingga 2021, berapa orangkah Perdana Menteri negara kita?', 6),
(1400, 123, 703, 'e7_n3_s3', 'Cikgu, mengapa pembentukan Malaysia dikira pencapaian Tunku?', 1),
(1401, 124, 703, 'e7_n3_s3', 'Beta berjaya merealisasikan pembentukan Malaysia pada 16 September 1963.', 2),
(1402, 122, 703, 'e7_n3_s3', 'Dan Tunku memperjuangkan kemerdekaan negara melalui apa?', 3),
(1403, 124, 703, 'e7_n3_s3', 'Melalui rundingan. Beta memperjuangkan kemerdekaan secara rundingan, bukan peperangan.', 4),
(1404, NULL, 703, 'e7_n3_s3', 'Nota ini pun menyebut dua pencapaian itu. Memperjuangkan kemerdekaan secara rundingan dan merealisasikan pembentukan Malaysia.', 5),
(1405, 124, 703, 'e7_n3_s3', 'Betul. Jadi apakah yang dibawa oleh pemimpin yang berunding kepada negara?', 6),
(1406, 122, 703, 'e7_n3_s4', 'Pemimpin mana yang memperkenalkan Dasar Ekonomi Baru?', 1),
(1407, 123, 703, 'e7_n3_s4', 'Saya ingat, tetapi tidak pasti.', 2),
(1408, 125, 703, 'e7_n3_s4', 'Aku, Tun Abdul Razak, memperkenalkan Dasar Ekonomi Baru. Tunku pula memperjuangkan kemerdekaan secara rundingan.', 3),
(1409, 126, 703, 'e7_n3_s4', 'Aku, Tun Hussein, memperkenalkan Amanah Saham Nasional Berhad.', 4),
(1410, 127, 703, 'e7_n3_s4', 'Aku merealisasikan Wawasan 2020 melalui Putrajaya, KLIA dan KLCC. Tun Abdullah memperkenalkan Pelan Integriti Nasional.', 5),
(1411, 129, 703, 'e7_n3_s4', 'Aku pula melancarkan Program Transformasi Kerajaan atau GTP.', 6),
(1412, NULL, 703, 'e7_n3_s4', 'Aku akan padankan semua enam pemimpin dengan pencapaian utama mereka.', 7),
(1413, 122, 703, 'e7_n3_s4', 'Jangan campur, ini peperiksaan kecil. Jadi apakah faedah pencapaian itu kepada rakyat?', 8),
(1414, 122, 703, 'e7_n3_s5', 'Mengapa kita perlu pemimpin yang memiliki ciri-ciri kepimpinan berwibawa?', 1),
(1415, 123, 703, 'e7_n3_s5', 'Supaya negara hebat, tetapi itu sahaja?', 2),
(1416, 122, 703, 'e7_n3_s5', 'Kad ini menjelaskannya. Pemimpin yang berwibawa memajukan sistem ekonomi negara, menjamin keselamatan negara dan membentuk kerajaan yang tersusun.', 3),
(1417, 122, 703, 'e7_n3_s5', 'Mereka juga menimbulkan rasa hormat antara pemimpin, mewujudkan negara yang membangun dan memudahkan pelaksanaan dasar-dasar pembangunan negara.', 4),
(1418, NULL, 703, 'e7_n3_s5', 'Memajukan ekonomi, menjamin keselamatan dan membentuk kerajaan tersusun. Aku akan baca kad itu sekali lagi sebelum menjawab.', 5),
(1419, 122, 703, 'e7_n3_s5', 'Fikir tentang negara dan rakyat. Jadi apakah yang kita dapat apabila pemimpinnya berwibawa?', 6),
(1420, 122, 703, 'e7_n3_s6', 'Bagaimana kita menghargai Perdana Menteri? Bukan dengan kata-kata kosong sahaja.', 1),
(1421, 123, 703, 'e7_n3_s6', 'Kad ini menyebut empat cara, Cikgu.', 2),
(1422, 122, 703, 'e7_n3_s6', 'Kita boleh mengeratkan perpaduan antara kaum dan mengekalkan taat setia terhadap pemimpin.', 3),
(1423, 122, 703, 'e7_n3_s6', 'Kita juga boleh menjaga nama baik negara dan menjaga keamanan negara.', 4),
(1424, NULL, 703, 'e7_n3_s6', 'Aku akan baca kad dan pilih yang betul. Mengeratkan perpaduan antara kaum dan menjaga nama baik negara.', 5),
(1425, 122, 703, 'e7_n3_s6', 'Satu kad pun jangan tersilap. Jadi bagaimana kita menghormati pemimpin dalam kehidupan seharian?', 6),
(1426, 122, 703, 'e7_n3_s7', 'Mengapa kita perlu menyokong kepimpinan negara? Fikir tiga peringkat, iaitu diri, masyarakat dan negara.', 1),
(1427, 123, 703, 'e7_n3_s7', 'Bagi diri, kita perlu menghormati pemimpin negara.', 2),
(1428, 122, 703, 'e7_n3_s7', 'Bagi masyarakat, sokongan kepada pemimpin berwibawa melahirkan masyarakat yang bertanggungjawab.', 3),
(1429, 122, 703, 'e7_n3_s7', 'Dan bagi negara, sikap bertanggungjawab memastikan kedaulatan negara terpelihara.', 4),
(1430, NULL, 703, 'e7_n3_s7', 'Aku akan padankan setiap peringkat dengan faedahnya.', 5),
(1431, 122, 703, 'e7_n3_s7', 'Jangan campur aduk. Jadi apakah yang terjamin apabila kita menyokong kepimpinan negara?', 6),
(1432, 122, 703, 'e7_n3_s8', 'Unit ini mengajar dua nilai teras sivik. Apakah nilai itu?', 1),
(1433, 123, 703, 'e7_n3_s8', 'Satu saya tahu, bertanggungjawab. Satu lagi?', 2),
(1434, 122, 703, 'e7_n3_s8', 'Nota ini menyebut bahawa kita menghargai jasa pemimpin yang memajukan negara.', 3),
(1435, 122, 703, 'e7_n3_s8', 'Kita perlu menghormati pemimpin dan bersikap bertanggungjawab terhadap negara, supaya kedaulatan negara dan perpaduan rakyat kekal terpelihara.', 4),
(1436, NULL, 703, 'e7_n3_s8', 'Aku akan baca nota dan pilih jawapan yang betul. Bertanggungjawab dan hormat-menghormati.', 5),
(1437, 122, 703, 'e7_n3_s8', 'Teliti, nilai itu berkaitan dengan hubungan kita dengan pemimpin. Jadi bagaimana kita akan mengamalkannya selepas album ini siap?', 6),
(1438, 141, 801, NULL, 'Tugasku menjaga mesin ladang supaya ekonomi berjalan. Jika aku keliru antara cara dahulu dan kini, kerja petani akan terganggu, {nama}.', 1),
(1439, 141, 801, NULL, 'Aku belajar bahawa setiap warganegara perlu menyokong usaha meningkatkan ekonomi negara supaya terus berkembang maju.', 2),
(1440, 141, 801, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, juruteknik yang menjaga jentera di ladang. Dengar keluhan petani dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1441, 141, 801, 'e8_n1_s1', 'Selamat datang ke kembara aku, dari cangkul ke jentera. Di tepi petak sawah itu ada seorang petani tua yang masih tidak mahu menukar caranya.', 1),
(1442, 144, 801, 'e8_n1_s1', 'Aku masih dengan cangkul dan sabit. Tidak perlu mesin. Cangkul kedua di tepi pagar itu pun cukup, kerana modalnya kecil dan alatnya sederhana.', 2),
(1443, 144, 801, 'e8_n1_s1', 'Rumah kayu itu rumah petani seperti aku. Hasil sawah kami ambil untuk keperluan sendiri dan keluarga.', 3),
(1444, 141, 801, 'e8_n1_s1', 'Petak sawah kecil itu pula diusahakan secara kecil-kecilan, sebab itu cara ini dinamakan ekonomi tradisional.', 4),
(1445, NULL, 801, 'e8_n1_s1', 'Aku akan cari empat buktinya dalam gambar. Cangkul di tepi petak, cangkul di tepi pagar, rumah kayu petani dan petak sawah kecil.', 5),
(1446, 144, 801, 'e8_n1_s1', 'Cari betul-betul, jangan menuduh. Jadi cara bertani aku ini sesuai untuk apa sebenarnya?', 6),
(1447, 145, 801, 'e8_n1_s2', 'Ladang kami diusahakan secara perladangan dengan mesin dan jentera. Kami memerlukan modal yang besar dan tenaga buruh yang banyak.', 1),
(1448, 144, 801, 'e8_n1_s2', 'Aku cuma ada cangkul. Apa bezanya cara kami, Juruteknik?', 2),
(1449, 141, 801, 'e8_n1_s2', 'Ekonomi tradisional diusahakan kecil-kecilan, dan tujuannya untuk keperluan sendiri dan keluarga.', 3),
(1450, 145, 801, 'e8_n1_s2', 'Ekonomi komersial pula diusahakan secara perladangan, dengan mesin dan jentera penuai. Hasilnya untuk kegunaan tempatan dan eksport.', 4),
(1451, NULL, 801, 'e8_n1_s2', 'Aku akan padankan ciri setiap jenis ekonomi itu.', 5),
(1452, 145, 801, 'e8_n1_s2', 'Padankan dengan betul supaya pak tani faham. Dan walaupun cara kami berbeza, apakah yang sama antara kedua-duanya?', 6),
(1453, NULL, 801, 'e8_n1_s3', 'Dua gambar ini tentang perlombongan. Yang mana tradisional, yang mana komersial?', 1),
(1454, 146, 801, 'e8_n1_s3', 'Kata datuk aku, dahulu orang mendulang untuk mencari bijih.', 2),
(1455, 141, 801, 'e8_n1_s3', 'Betul, mendulang ialah kaedah tradisional. Perlombongan komersial pula menggunakan jentera seperti kapal korek, contohnya di lombong emas Sungai Lebir, Kelantan.', 3),
(1456, 141, 801, 'e8_n1_s3', 'Apabila ekonomi komersial diperkenalkan, bandar-bandar mula dibuka di kawasan perlombongan.', 4),
(1457, NULL, 801, 'e8_n1_s3', 'Nota di belakang gambar ini pun menyebutnya. Tradisional dengan mendulang, komersial dengan kapal korek.', 5),
(1458, 146, 801, 'e8_n1_s3', 'Jangan terbalik. Jadi apakah yang dibawa oleh ekonomi komersial kepada kawasan perlombongan itu?', 6),
(1459, 146, 801, 'e8_n1_s4', 'Pokok getah di sini sudah ditanam sejak lama. Datuk aku menoreh getah sejak zaman dahulu lagi.', 1),
(1460, 145, 801, 'e8_n1_s4', 'Kelapa sawit pun bermula dalam tempoh yang sama, malah ladang kami tumbuh bersamanya.', 2),
(1461, 141, 801, 'e8_n1_s4', 'Nota ini menyebut bahawa industri getah dan kelapa sawit bermula sejak awal abad ke-20. Ia sektor pertanian utama yang merangsang kemajuan ekonomi Malaysia.', 3),
(1462, NULL, 801, 'e8_n1_s4', 'Aku akan semak nota dan tentukan bila kedua-dua industri bermula. Sejak awal abad ke-20.', 4),
(1463, 146, 801, 'e8_n1_s4', 'Jangan agak-agak, kerana tarikh mesti tepat. Jadi apakah yang dilakukan oleh industri lama ini kepada ekonomi negara?', 5),
(1464, 146, 801, 'e8_n1_s5', 'Kad-kad ini jatuh ke tanah. Siapa boleh susun semula manfaat getah dan sawit?', 1),
(1465, 146, 801, 'e8_n1_s5', 'Hasil getah dan sawit dieksport, seperti sarung tangan dan minyak. Itulah cara ia meningkatkan pendapatan negara.', 2),
(1466, 145, 801, 'e8_n1_s5', 'Perladangan memerlukan tenaga kerja yang banyak, jadi ia menyediakan peluang pekerjaan.', 3),
(1467, 141, 801, 'e8_n1_s5', 'Ia juga mewujudkan industri hiliran, contohnya pembuatan perabot daripada kayu getah. Ia memajukan industri asas tani dengan meningkatkan pengeluaran bahan makanan tempatan.', 4),
(1468, 145, 801, 'e8_n1_s5', 'Dan sawit diproses menjadi biodiesel, minyak dan sabun. Itulah cara ia membangunkan industri biodiesel.', 5),
(1469, NULL, 801, 'e8_n1_s5', 'Aku akan padankan lima manfaat itu dengan penerangannya.', 6),
(1470, 146, 801, 'e8_n1_s5', 'Baik. Jadi apakah manfaat paling dekat dengan penduduk kampung kita?', 7),
(1471, 146, 801, 'e8_n1_s6', 'Industri hiliran dan biodiesel selalu dikelirukan. Aku hanya tahu menoreh getah.', 1),
(1472, 141, 801, 'e8_n1_s6', 'Nota ini menjelaskannya. Industri hiliran bermaksud kegiatan yang berkembang daripada kegiatan ekonomi utama, contohnya pembuatan perabot daripada kayu getah.', 2),
(1473, 141, 801, 'e8_n1_s6', 'Biodiesel pula bermaksud bahan buangan organik yang digunakan sebagai bahan api. Industri kelapa sawit turut menghasilkan biodiesel sawit.', 3),
(1474, NULL, 801, 'e8_n1_s6', 'Aku akan baca nota dan pilih maksud yang betul. Industri hiliran ialah kegiatan yang berkembang daripada kegiatan ekonomi utama.', 4),
(1475, 146, 801, 'e8_n1_s6', 'Teliti, nanti pelawat salah faham. Jadi apakah yang ditambah oleh industri hiliran kepada negara?', 5),
(1476, 146, 801, 'e8_n1_s7', 'Label di kotak ini luntur. Apa yang dieksport daripada getah dan sawit?', 1),
(1477, 146, 801, 'e8_n1_s7', 'Aku tahu sarung tangan dibuat daripada getah. Benang lateks pun hasil getah yang dieksport untuk membuat barangan kenyal.', 2),
(1478, 145, 801, 'e8_n1_s7', 'Kelapa sawit pula ada pelbagai bentuk. Minyak mentah sawit ialah hasil sebelum diproses, dan minyak sawit diproses ialah hasil selepas diproses untuk dieksport.', 3),
(1479, 141, 801, 'e8_n1_s7', 'Sabun pula produk yang diproses daripada kelapa sawit.', 4),
(1480, NULL, 801, 'e8_n1_s7', 'Aku akan padankan hasil dengan sumbernya.', 5),
(1481, 146, 801, 'e8_n1_s7', 'Baik. Tetapi apakah kesan hasil eksport ini kepada negara kita?', 6),
(1482, 144, 801, 'e8_n1_s8', 'Juruteknik, ringkaskan perubahan dari dahulu hingga kini. Apa yang hilang, apa yang kekal?', 1),
(1483, 141, 801, 'e8_n1_s8', 'Pada zaman awal, pertanian dan perlombongan tradisional diusahakan kecil-kecilan. Pada awal abad ke-20, industri getah dan kelapa sawit berkembang secara perladangan.', 2),
(1484, 141, 801, 'e8_n1_s8', 'Industri petroleum bermula pada 1910 di Miri, Sarawak. PETRONAS ditubuhkan pada 1974 dan dimiliki sepenuhnya oleh kerajaan.', 3),
(1485, 141, 801, 'e8_n1_s8', 'PROTON pula ditubuhkan pada 1983 di Shah Alam, Selangor.', 4),
(1486, NULL, 801, 'e8_n1_s8', 'Aku akan susun peristiwa mengikut peringkat perkembangan ekonomi itu.', 5),
(1487, 144, 801, 'e8_n1_s8', 'Ingat, kemajuan datang secara berperingkat. Jadi dari mana bermulanya kemajuan ekonomi kita?', 6),
(1488, 142, 802, NULL, 'Tugasku memeriksa mutu dan fakta. Jika satu cop salah, seluruh laporan ekonomi menjadi cacat, {nama}.', 1),
(1489, 142, 802, NULL, 'Aku belajar bahawa pelbagai kegiatan ekonomi menjana pendapatan dan memajukan negara.', 2),
(1490, 142, 802, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, inspektor yang memeriksa kilang dan industri. Semak setiap borang dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1491, 147, 802, 'e8_n2_s1', 'Inspektor, borang ini menulis industri petroleum bermula pada 1974. Betulkah begitu?', 1),
(1492, NULL, 802, 'e8_n2_s1', 'Aku ragu. Mari semak nota dahulu.', 2),
(1493, 142, 802, 'e8_n2_s1', 'Nota menyebut industri petroleum di negara kita bermula pada tahun 1910 di Miri, Sarawak. The Grand Old Lady, Miri ialah telaga minyak yang pertama di negara kita.', 3),
(1494, 147, 802, 'e8_n2_s1', 'Tahun 1974 itu ialah penubuhan PETRONAS, iaitu Petroliam Nasional Berhad. Ia dimiliki sepenuhnya oleh kerajaan Malaysia.', 4),
(1495, NULL, 802, 'e8_n2_s1', 'Aku akan baca nota sebelum mencop. Bermula 1910 di Miri, dan PETRONAS ditubuhkan pada 1974.', 5),
(1496, 142, 802, 'e8_n2_s1', 'Jika cop LULUS salah, kita semua malu. Jadi apakah kejayaan penubuhan PETRONAS itu?', 6),
(1497, 147, 802, 'e8_n2_s2', 'Industri ini membuka kerja kepada ramai orang, iaitu pekerja di pelantar minyak dan pusat pemprosesan.', 1),
(1498, NULL, 802, 'e8_n2_s2', 'Dan ia juga melahirkan usahawan, seperti mereka yang membuka stesen minyak.', 2),
(1499, 147, 802, 'e8_n2_s2', 'Betul. PETRONAS pula penaja utama sukan permotoran, iaitu Grand Prix Malaysia, dan itu meningkatkan pendapatan negara.', 3),
(1500, 142, 802, 'e8_n2_s2', 'Ada juga biasiswa untuk melanjutkan pelajaran ke Universiti Teknologi PETRONAS. Dan permintaan tinggi dunia terhadap petroleum memberi pulangan pendapatan yang tinggi.', 4),
(1501, NULL, 802, 'e8_n2_s2', 'Aku akan padankan sumbangan itu dengan penerangannya.', 5),
(1502, 142, 802, 'e8_n2_s2', 'Jangan cop dahulu sebelum semak. Jadi apakah pendapat kau tentang industri petroleum ini?', 6),
(1503, 147, 802, 'e8_n2_s3', 'Seorang wartawan bertanya, buat apa PETRONAS menaja perlumbaan?', 1),
(1504, NULL, 802, 'e8_n2_s3', 'Fikir tentang pendapatan negara.', 2),
(1505, 142, 802, 'e8_n2_s3', 'Nota ini menyebut bahawa PETRONAS ialah penaja utama sukan permotoran seperti Grand Prix Malaysia.', 3),
(1506, 142, 802, 'e8_n2_s3', 'Penganjuran sukan ini meningkatkan pendapatan negara.', 4),
(1507, NULL, 802, 'e8_n2_s3', 'Aku akan baca nota penajaan itu dan jawab. Penganjuran sukan permotoran meningkatkan pendapatan negara.', 5),
(1508, 142, 802, 'e8_n2_s3', 'Jawapan pendek dan tepat. Jadi mengapakah penajaan sukan itu berbaloi kepada negara dan rakyat?', 6),
(1509, 142, 802, 'e8_n2_s4', 'Aku Inspektor Kilang Automotif. Tarikh-tarikh dalam fail kilang ini bercampur-campur.', 1),
(1510, 147, 802, 'e8_n2_s4', 'PROTON ditubuhkan pada 1983 di Shah Alam, Selangor. Pada Julai 1985, Proton Saga dilancarkan sebagai model kereta pertama negara.', 2),
(1511, 142, 802, 'e8_n2_s4', 'PERODUA ditubuhkan pada 1993, dan model pertama PERODUA, Kancil, dikeluarkan pada 1994.', 3),
(1512, 142, 802, 'e8_n2_s4', 'Pada 2005, kilang kedua PROTON dibina di Tanjung Malim, Perak. Pada 2018, PROTON menjalin usaha sama dengan Geely Holding Group.', 4),
(1513, NULL, 802, 'e8_n2_s4', 'Aku akan susun peristiwa itu mengikut tahun.', 5),
(1514, 142, 802, 'e8_n2_s4', 'Laporan perlu dihantar sebelum waktu pejabat tamat. Dan apakah perasaan kita terhadap pencapaian automotif negara ini?', 6),
(1515, 147, 802, 'e8_n2_s5', 'Pengunjung kilang tidak tahu beza PROTON dan PERODUA. Tolong padankan butiran dengan betul.', 1),
(1516, 142, 802, 'e8_n2_s5', 'PROTON ditubuhkan dengan kilang pertama di Shah Alam pada tahun 1983. Proton Saga ialah model kereta pertama negara pada Julai 1985.', 2),
(1517, 142, 802, 'e8_n2_s5', 'Kilang kedua PROTON dibina di Tanjung Malim, Perak pada tahun 2005.', 3),
(1518, 142, 802, 'e8_n2_s5', 'PERODUA ditubuhkan pada tahun 1993. Kancil ialah model pertama PERODUA pada tahun 1994, dan produk PERODUA bernama Nippa dieksport ke United Kingdom.', 4),
(1519, NULL, 802, 'e8_n2_s5', 'Aku akan padankan syarikat dengan butirannya.', 5),
(1520, 147, 802, 'e8_n2_s5', 'Jangan rosakkan reputasi kilang. Dan apakah yang didorong oleh industri automotif ini?', 6),
(1521, 148, 802, 'e8_n2_s6', 'Pelancong datang ke Malaysia kerana keindahan alam. Cari buktinya dalam gambar, Inspektor.', 1),
(1522, NULL, 802, 'e8_n2_s6', 'Jangan lupa Tahun Melawat Malaysia.', 2),
(1523, 148, 802, 'e8_n2_s6', 'Betul. Kempen Tahun Melawat Malaysia dianjurkan sejak tahun 1990 untuk menarik pelancong. Lihat air terjun hutan itu, dan pelancong di jambatan gantung.', 3),
(1524, 148, 802, 'e8_n2_s6', 'Lihat juga gua batu kapur itu, dan pelancong yang bergambar di pantai.', 4),
(1525, NULL, 802, 'e8_n2_s6', 'Air terjun hutan, jambatan gantung, gua batu kapur dan pantai. Aku akan cari keempat-empatnya.', 5),
(1526, 148, 802, 'e8_n2_s6', 'Teliti, pelancong itu cerewet. Jadi apakah yang perlu kita lakukan terhadap alam semula jadi ini?', 6),
(1527, 148, 802, 'e8_n2_s7', 'Pelancong suka sejarah, alam dan budaya. Padankan dengan betul, Inspektor.', 1),
(1528, NULL, 802, 'e8_n2_s7', 'Dan makanan serta inap desa juga.', 2),
(1529, 148, 802, 'e8_n2_s7', 'Tapak dan bangunan bersejarah ialah Kota A Famosa, Candi Bukit Batu Pahat dan Istana Kenangan. Keindahan alam semula jadi pula Gunung Kinabalu, Pulau Langkawi dan Gua Niah.', 3),
(1530, 148, 802, 'e8_n2_s7', 'Keharmonian dan keunikan budaya bermaksud hidup pelbagai kaum menjamin keselamatan dan menarik pelancong. Agropelancongan ialah konsep inap desa bersama keluarga penduduk tempatan.', 4),
(1531, 148, 802, 'e8_n2_s7', 'Sukan, muzik dan pameran antarabangsa ialah Formula One, Le Tour de Langkawi, Festival Muzik Hutan Hujan dan LIMA.', 5),
(1532, NULL, 802, 'e8_n2_s7', 'Aku akan padankan keistimewaan itu dengan penerangannya.', 6),
(1533, 148, 802, 'e8_n2_s7', 'Mesyuarat bermula sebentar lagi. Jadi apakah yang turut menjadi tarikan pelancong, selain sejarah dan alam?', 7),
(1534, 148, 802, 'e8_n2_s8', 'Formula One di mana? LIMA di mana? Senarai ini kusut.', 1),
(1535, 142, 802, 'e8_n2_s8', 'Perlumbaan Formula One dianjurkan di Sepang. Le Tour de Langkawi ialah perlumbaan basikal antarabangsa.', 2),
(1536, 148, 802, 'e8_n2_s8', 'Festival Muzik Hutan Hujan Sedunia dianjurkan di Sarawak. LIMA pula pameran maritim dan aeroangkasa yang dianjurkan di Pulau Langkawi setiap dua tahun.', 3),
(1537, NULL, 802, 'e8_n2_s8', 'Aku akan padankan acara itu dengan tempat atau cirinya.', 4),
(1538, 148, 802, 'e8_n2_s8', 'Padankan dengan betul, kerana pelancong menunggu. Jadi apakah yang dibawa oleh acara antarabangsa ini?', 5),
(1539, 143, 803, NULL, 'Tugasku menyusun rak dengan barangan buatan Malaysia dan menceritakan kisahnya. Jika aku tersilap, pelanggan akan hilang kepercayaan, {nama}.', 1),
(1540, 143, 803, NULL, 'Aku belajar bahawa membeli barangan buatan Malaysia memajukan ekonomi dan menimbulkan rasa bangga terhadap negara.', 2),
(1541, 143, 803, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemilik kedai jenama Malaysia. Layan pelanggan dengan jujur. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1542, 149, 803, 'e8_n3_s1', 'Poster kempen di dinding kedai ini dilancarkan bila, Pakcik?', 1),
(1543, NULL, 803, 'e8_n3_s1', 'Aku tahu, tetapi aku mahu pelanggan menjawab sendiri.', 2),
(1544, 143, 803, 'e8_n3_s1', 'Nota di bawah poster ini menyebut kempen ''Beli Barangan Buatan Malaysia'' dilancarkan pada tahun 1985.', 3),
(1545, 143, 803, 'e8_n3_s1', 'Antara barangan buatan Malaysia termasuklah perabot, barangan elektrik dan elektronik serta produk makanan.', 4),
(1546, NULL, 803, 'e8_n3_s1', 'Aku akan baca nota di bawah poster itu. Tahun 1985, dengan perabot, elektrik dan elektronik, serta makanan.', 5),
(1547, 149, 803, 'e8_n3_s1', 'Jawab betul, nanti aku marah. Jadi apakah faedah membeli barangan tempatan kepada ekonomi negara?', 6),
(1548, 149, 803, 'e8_n3_s2', 'Aku letak minyak pelincir di rak buah-buahan tadi. Salahkah?', 1),
(1549, NULL, 803, 'e8_n3_s2', 'Itu salah. Mari kita susun semula.', 2),
(1550, 143, 803, 'e8_n3_s2', 'Minyak masak dan sabun ialah produk pertanian daripada sawit. Buah durian dan buah nanas pula produk pertanian berupa buah-buahan.', 3),
(1551, 143, 803, 'e8_n3_s2', 'Minyak petrol ialah bahan api kenderaan daripada petroleum. Minyak pelincir kenderaan melincirkan enjin, dan gas untuk memasak digunakan di dapur.', 4),
(1552, 143, 803, 'e8_n3_s2', 'Kereta dan motosikal pula produk automotif keluaran negara.', 5),
(1553, NULL, 803, 'e8_n3_s2', 'Aku akan padankan produk dengan kategorinya.', 6),
(1554, 149, 803, 'e8_n3_s2', 'Cepat, aku mahu keluar. Jadi mengapa kita patut berbangga dengan produk ini?', 7),
(1555, 149, 803, 'e8_n3_s3', 'Apa bukti pencapaian ekonomi pesat negara, Pakcik?', 1),
(1556, 143, 803, 'e8_n3_s3', 'Lihat sekeliling, ada tiga bidang. Pembangunan, perhubungan dan perdagangan.', 2),
(1557, 149, 803, 'e8_n3_s3', 'Menara pencakar langit itu pembangunan. Jambatan, kereta api dan jalan raya itu perhubungan moden yang terancang.', 3),
(1558, 149, 803, 'e8_n3_s3', 'Gudang e-dagang itu perdagangan yang semakin berkembang, dan papan iklan carta menaik itu pun menunjukkan e-dagang semakin berkembang.', 4),
(1559, NULL, 803, 'e8_n3_s3', 'Menara pencakar langit, jambatan dan jalan raya, gudang e-dagang, dan papan iklan carta menaik. Aku akan cari keempat-empatnya.', 5),
(1560, 149, 803, 'e8_n3_s3', 'Fikir pembangunan, perhubungan dan perdagangan. Jadi bagaimana perasaan kau melihat semua pencapaian ini?', 6),
(1561, 149, 803, 'e8_n3_s4', 'Pembangunan, perhubungan dan perdagangan, apa maksud setiap satu, Pakcik?', 1),
(1562, 143, 803, 'e8_n3_s4', 'Pembangunan ialah bangunan pencakar langit sebagai lambang kemakmuran negara. Perhubungan pula jaringan moden terancang yang mendorong kesinambungan pembangunan.', 2),
(1563, 143, 803, 'e8_n3_s4', 'Perdagangan ialah kegiatan e-dagang yang membuka peluang kepada rakyat. E-dagang bermaksud proses menjalankan urusan perniagaan melalui rangkaian Internet.', 3),
(1564, NULL, 803, 'e8_n3_s4', 'Aku akan padankan pencapaian itu dengan penerangannya.', 4),
(1565, 149, 803, 'e8_n3_s4', 'Jangan campur, kerana aku akan menyalin ke buku. Jadi apa yang e-dagang berikan kepada rakyat?', 5),
(1566, 149, 803, 'e8_n3_s5', 'Mengapa perlu bangga dengan barangan buatan Malaysia, Pakcik?', 1),
(1567, 143, 803, 'e8_n3_s5', 'Ada sebab ekonomi dan sebab identiti. Kad ini menyebut rasa bangga memajukan sistem ekonomi negara dan memperluaskan pasaran produk tempatan.', 2),
(1568, 143, 803, 'e8_n3_s5', 'Ia juga memperkenalkan identiti negara dan membantu usahawan meningkatkan produktiviti.', 3),
(1569, NULL, 803, 'e8_n3_s5', 'Aku akan baca kad dan memilih jawapan yang betul. Memajukan ekonomi, memperluaskan pasaran tempatan dan memperkenalkan identiti negara.', 4),
(1570, 149, 803, 'e8_n3_s5', 'Pilih betul-betul, nanti aku beli barang luar. Jadi apakah pilihan kau semasa membeli-belah nanti?', 5),
(1571, 149, 803, 'e8_n3_s6', 'Soal selidik ini mengelirukan. Pernyataan mana yang benar?', 1),
(1572, 149, 803, 'e8_n3_s6', 'Kemajuan ekonomi bukankah menambah kemiskinan?', 2),
(1573, 143, 803, 'e8_n3_s6', 'Tidak. Kad ini menyebut kemajuan ekonomi meningkatkan taraf hidup rakyat dengan menyediakan lebih banyak peluang pekerjaan.', 3),
(1574, 143, 803, 'e8_n3_s6', 'Ia juga membolehkan pelaburan dalam infrastruktur seperti jalan raya dan jambatan, menyumbang kepada kestabilan sosial dan politik, serta meningkatkan daya saing negara.', 4),
(1575, NULL, 803, 'e8_n3_s6', 'Aku akan baca kad dan tentukan pernyataan yang betul. Meningkatkan taraf hidup, infrastruktur dan daya saing negara.', 5),
(1576, 149, 803, 'e8_n3_s6', 'Jangan terpengaruh dengan pernyataan pelik. Jadi apakah kesimpulan kau tentang kemajuan ekonomi?', 6),
(1577, 149, 803, 'e8_n3_s7', 'Sebagai warganegara, apa peranan setiap peringkat dalam menyokong ekonomi?', 1),
(1578, 143, 803, 'e8_n3_s7', 'Fikir tiga peringkat. Diri ialah setiap warganegara yang menyokong usaha meningkatkan ekonomi negara.', 2),
(1579, 143, 803, 'e8_n3_s7', 'Masyarakat pula, sokongan dalam pembangunan ekonomi meningkatkan pendapatan negara.', 3),
(1580, 143, 803, 'e8_n3_s7', 'Dan negara, peningkatan pendapatan dan kemajuan ekonomi dikongsi bersama.', 4),
(1581, 149, 803, 'e8_n3_s7', 'Aku keliru antara diri, masyarakat dan negara.', 5),
(1582, NULL, 803, 'e8_n3_s7', 'Aku akan padankan setiap peringkat dengan peranannya.', 6),
(1583, 149, 803, 'e8_n3_s7', 'Jawab untuk projek ini. Jadi mengapa kita perlu menyokong ekonomi negara bersama-sama?', 7),
(1584, 149, 803, 'e8_n3_s8', 'Pakcik, boleh rumuskan Unit 8 sebelum kedai ditutup?', 1),
(1585, 143, 803, 'e8_n3_s8', 'Ada empat industri utama dan dua jenis ekonomi. Getah dan kelapa sawit ialah sektor pertanian utama sejak awal abad ke-20.', 2),
(1586, 143, 803, 'e8_n3_s8', 'Petroleum dan gas bermula pada 1910 di Miri, dan PETRONAS ditubuhkan pada 1974. Automotif bermula apabila PROTON ditubuhkan pada 1983 dan PERODUA pada 1993.', 3),
(1587, 143, 803, 'e8_n3_s8', 'Pelancongan pula dimajukan melalui Kempen Tahun Melawat Malaysia sejak tahun 1990.', 4),
(1588, NULL, 803, 'e8_n3_s8', 'Aku akan padankan industri itu dengan cirinya.', 5),
(1589, 149, 803, 'e8_n3_s8', 'Teliti, kerana ini peperiksaan kecil. Jadi mengapa kegiatan ekonomi yang pelbagai penting kepada negara?', 6),
(1590, 161, 901, NULL, 'Tugasku mengulas pencapaian sukan negara dengan tepat. Jika nama atau tahun salah, peminat akan menegur siaran kita, {nama}.', 1),
(1591, 161, 901, NULL, 'Aku belajar bahawa atlet pelbagai kaum yang gigih mengharumkan nama negara dan wajar dihargai.', 2),
(1592, 161, 901, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pengulas sukan di stadium. Rakam kejayaan atlet dengan tepat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1593, 161, 901, 'e9_n1_s1', 'Dua minit lagi siaran bermula dan skrip aku basah kena teh tarik. Tahun penubuhan Persatuan Badminton Malaysia pun aku sudah tidak pasti.', 1),
(1594, 164, 901, 'e9_n1_s1', 'Aku Lee Chong Wei. Persatuan Badminton Malaysia, atau BAM, ditubuhkan pada tahun 1960. Persatuan inilah yang menganjurkan Kejohanan Badminton Kebangsaan.', 2),
(1595, 164, 901, 'e9_n1_s1', 'Daripada kejohanan itu lahir atlet kebanggaan seperti Punch Gunalan, Misbun Sidek dan aku sendiri. Pencapaian antarabangsa kami pula juara Piala Thomas lima kali dan pingat Olimpik.', 3),
(1596, NULL, 901, 'e9_n1_s1', 'Aku akan padankan tahun, kejohanan, atlet dan pencapaian itu.', 4),
(1597, 161, 901, 'e9_n1_s1', 'Betulkan skrip aku cepat. Selepas semua itu, apakah peranan sebuah persatuan sukan?', 5),
(1598, 163, 901, 'e9_n1_s2', 'Pengulas, kad catatan ini tertinggal di bangku penonton. Tulisannya hampir luntur.', 1),
(1599, 161, 901, 'e9_n1_s2', 'Bacalah dengan kuat. Peminat di rumah mahu tahu apa pencapaian badminton kita di peringkat antarabangsa.', 2),
(1600, 163, 901, 'e9_n1_s2', 'Atlet negara juara Piala Thomas sebanyak lima kali dan memenangi pingat perak serta gangsa Olimpik. Mereka juga menjuarai All England Terbuka bagi acara beregu dan individu lelaki.', 3),
(1601, NULL, 901, 'e9_n1_s2', 'Aku akan pilih pencapaian yang sama dengan nota itu.', 4),
(1602, 161, 901, 'e9_n1_s2', 'Pilih dengan tepat kerana pendengar menanti. Dan bagaimana perasaan kita terhadap kejayaan ini?', 5),
(1603, 161, 901, 'e9_n1_s3', 'Sekarang bola sepak. Siapa boleh bantu aku susun fakta Persatuan Bola Sepak Malaysia?', 1),
(1604, 163, 901, 'e9_n1_s3', 'FAM ditubuhkan pada tahun 1963. Pertandingan yang dianjurkan FAM ialah Liga Bola Sepak Malaysia, tempat pemain berbakat seperti Soh Chin Ann, James Wong dan Safawi Rasid dilahirkan.', 2),
(1605, 163, 901, 'e9_n1_s3', 'Pasukan negara pernah layak ke Sukan Olimpik di Munich pada 1972 dan di Moscow pada 1980. Pada tahun 2010 pasukan kita juara Piala Suzuki AFF.', 3),
(1606, NULL, 901, 'e9_n1_s3', 'Aku akan padankan tahun, liga, pemain, Olimpik dan Piala Suzuki.', 4),
(1607, 161, 901, 'e9_n1_s3', 'Jangan silap kerana ini siaran langsung. Apakah yang melahirkan pemain berbakat negara?', 5),
(1608, 163, 901, 'e9_n1_s4', 'Anugerah antarabangsa apa yang pernah dimenangi pemain bola sepak kita dari Pulau Pinang?', 1),
(1609, 161, 901, 'e9_n1_s4', 'Nota ringkas ini menyebut Mohd Faiz Subri ketika menjadi pemain pasukan Pulau Pinang memenangi anugerah antarabangsa PUSKAS FIFA 2016.', 2),
(1610, 163, 901, 'e9_n1_s4', 'Jangan keliru dengan anugerah lain. Anugerah Pemain Lelaki Terbaik BWF milik Lee Chong Wei, anugerah Atlet Terunggul Sukan Dunia milik Nicol Ann David dan anugerah Olahragawan Negara 1986 milik Abdul Malek.', 3),
(1611, NULL, 901, 'e9_n1_s4', 'Aku akan pilih anugerah yang betul. PUSKAS FIFA 2016.', 4),
(1612, 161, 901, 'e9_n1_s4', 'Baik, kalau betul aku mohon maaf kerana tersilap tadi. Jadi apakah yang dibuktikan oleh pemain tempatan itu?', 5),
(1613, 161, 901, 'e9_n1_s5', 'Dalam rakaman lama ini ada empat bukti kegemilangan olahraga kita. Aku mahu pelajar mencarinya.', 1),
(1614, 179, 901, 'e9_n1_s5', 'Aku Dr. M. Jegathesan. Pelari pecut di tengah memenangi pingat emas 100 meter Sukan Asia pada tahun 1966 dan pada tahun 1982.', 2),
(1615, 179, 901, 'e9_n1_s5', 'Blok permulaan di bawah ialah acara 100 meter Sukan Asia. Pegawai berjam randik di kiri menunjukkan olahraga diurus oleh KOM, dan pelari kedua mewakili atlet Malaysia dalam Kejohanan Sukan SEA.', 3),
(1616, NULL, 901, 'e9_n1_s5', 'Pelari pecut, blok permulaan, pegawai berjam randik dan pelari kedua. Aku akan cari keempat-empatnya.', 4),
(1617, 161, 901, 'e9_n1_s5', 'Cari betul-betul kerana rakaman ini bukti sejarah. Jadi siapakah di sebalik kejayaan olahraga itu?', 5),
(1618, 180, 901, 'e9_n1_s6', 'Aku M. Rajamani. Kesatuan Olahraga Amatur Malaysia atau KOAM ditubuhkan pada tahun 1952 dan kini dikenali sebagai Kesatuan Olahraga Malaysia atau KOM.', 1),
(1619, 161, 901, 'e9_n1_s6', 'KOM menganjurkan Kejohanan Olahraga Kebangsaan. Daripadanya lahir Dr. M. Jegathesan, Rabuan Pit dan Watson Nyambek.', 2),
(1620, 180, 901, 'e9_n1_s6', 'Dalam Sukan SEA 2017 atlet olahraga membantu negara muncul juara dengan menyumbang lapan pingat emas.', 3),
(1621, NULL, 901, 'e9_n1_s6', 'Aku akan pilih maklumat yang betul tentang KOAM dan KOM.', 4),
(1622, 161, 901, 'e9_n1_s6', 'Jangan keliru dengan persatuan lain. Dan apakah yang disokong oleh persatuan sukan?', 5),
(1623, 161, 901, 'e9_n1_s7', 'Hoki pula. Nombor-nombor di skrip ini bergelut sesama sendiri.', 1),
(1624, 166, 901, 'e9_n1_s7', 'Aku S. Kuhan. Konfederasi Hoki Malaysia atau MHC ditubuhkan pada tahun 1953. Pertandingan yang dianjurkan ialah Liga Hoki Kebangsaan.', 2),
(1625, 166, 901, 'e9_n1_s7', 'Pemain hoki berbakat ialah Poon Fook Loke, Sarjit Singh dan Mirnawan Nawawi. Negara layak ke Hoki Piala Dunia sebanyak lapan kali dan mendapat tempat keempat pada tahun 1975.', 3),
(1626, 166, 901, 'e9_n1_s7', 'Pada tahun 1998 pasukan kita menjadi naib juara Sukan Komanwel.', 4),
(1627, NULL, 901, 'e9_n1_s7', 'Aku akan padankan tahun, liga, pemain dan pencapaian itu.', 5),
(1628, 161, 901, 'e9_n1_s7', 'Jangan salah kerana kapten akan marah. Apakah erti kejayaan hoki itu kepada negara?', 6),
(1629, 161, 901, 'e9_n1_s8', 'Penutup siaran. Aku mahu menyebut empat legenda yang membuka jalan sebelum kita semua.', 1),
(1630, 179, 901, 'e9_n1_s8', 'Aku Dr. M. Jegathesan, digelar Manusia Terpantas Asia kerana memenangi tiga emas Sukan Asia di Bangkok pada tahun 1966.', 2),
(1631, 180, 901, 'e9_n1_s8', 'Aku M. Rajamani, atlet olahraga wanita yang mewakili negara di Olimpik 1964. Tan Aik Huang pula juara perseorangan lelaki All England pada tahun 1966.', 3),
(1632, 182, 901, 'e9_n1_s8', 'Aku Mokhtar Dahari, digelar Supermokh. Aku mencatat 167 penampilan antarabangsa dan menjaringkan 89 gol.', 4),
(1633, NULL, 901, 'e9_n1_s8', 'Aku akan padankan legenda dengan pencapaian mereka.', 5),
(1634, 161, 901, 'e9_n1_s8', 'Padankan dengan betul sebelum siaran berakhir. Mengapa kita perlu menghargai jasa mereka?', 6),
(1635, 162, 902, NULL, 'Tugasku menunjuk teladan atlet kepada murid. Jika aku silap tentang pencapaian mereka, murid akan hilang kepercayaan, {nama}.', 1),
(1636, 162, 902, NULL, 'Aku belajar bahawa atlet pelbagai kaum dan atlet paralimpik mengharumkan nama negara dan wajar dihargai.', 2),
(1637, 162, 902, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, jurulatih sekolah di padang. Beri semangat kepada murid dengan sabar. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1638, 162, 902, 'e9_n2_s1', 'Murid-murid, sebelum berlari mari kita lihat gambar podium ini. Ada empat tanda kebanggaan yang aku mahu kamu cari.', 1),
(1639, 163, 902, 'e9_n2_s1', 'Pingat emas ialah lambang kebanggaan atlet negara, cikgu. Bendera Malaysia itu pula lambang kebanggaan negara.', 2),
(1640, 163, 902, 'e9_n2_s1', 'Trofi yang diangkat menunjukkan kejayaan atlet kebanggaan negara, dan penonton yang bersorak menunjukkan rakyat bangga dengan atlet negara.', 3),
(1641, NULL, 902, 'e9_n2_s1', 'Pingat emas, bendera Malaysia, trofi diangkat dan penonton bersorak. Aku akan cari keempat-empatnya.', 4),
(1642, 162, 902, 'e9_n2_s1', 'Cepat kerana kawan-kawan menunggu. Bagaimanakah perasaan kita apabila bendera negara berkibar di temasya dunia?', 5),
(1643, 162, 902, 'e9_n2_s2', 'Hari ini kita belajar daripada Lee Chong Wei. Ada kad rekod di tangan murid ini.', 1),
(1644, 164, 902, 'e9_n2_s2', 'Aku pernah menjadi pemain badminton nombor satu dunia pada tahun 2006, 2008, 2012 dan 2013.', 2),
(1645, 164, 902, 'e9_n2_s2', 'Aku juga juara Perseorangan Lelaki Terbuka All England sebanyak empat kali dan dinobatkan Anugerah Pemain Lelaki Terbaik BWF sebanyak lima kali.', 3),
(1646, NULL, 902, 'e9_n2_s2', 'Aku akan pilih rekod yang betul. Nombor satu dunia empat kali dan juara All England empat kali.', 4),
(1647, 162, 902, 'e9_n2_s2', 'Baik, pilih dengan teliti. Dan apakah rahsia kejayaan seorang juara dunia?', 5),
(1648, 165, 902, 'e9_n2_s3', 'Aku Nicol Ann David. Aku skuasy wanita nombor satu dunia selama 108 bulan.', 1),
(1649, 167, 902, 'e9_n2_s3', 'Aku Pandelela Rinong. Aku menyumbang gangsa pertama negara di Olimpik London 2012 dalam terjun, dan aku pembawa bendera wanita pertama pada upacara pembukaan Sukan Olimpik.', 2),
(1650, 168, 902, 'e9_n2_s3', 'Aku Mohd Azizulhasni Awang, digelar The Pocket Rocketman. Aku memenangi gangsa Rio 2016 dan perak Tokyo 2020.', 3),
(1651, NULL, 902, 'e9_n2_s3', 'Aku akan padankan atlet dengan pencapaian mereka.', 4),
(1652, 162, 902, 'e9_n2_s3', 'Padankan dengan betul. Apakah yang menyatukan ketiga-tiga atlet daripada kaum berbeza ini?', 5),
(1653, 166, 902, 'e9_n2_s4', 'Aku S. Kuhan, penjaring terbanyak Liga Hoki Malaysia pada tahun 1997, 1999 dan 2003.', 1),
(1654, 162, 902, 'e9_n2_s4', 'Ceritakan tentang pasukan kebangsaan pula, kerana murid-murid mahu tahu tugas seorang ketua.', 2),
(1655, 166, 902, 'e9_n2_s4', 'Aku ketua pasukan hoki Malaysia dari tahun 2000 hingga 2006 dan mewakili negara sebanyak 341 kali dalam pelbagai kejohanan utama.', 3),
(1656, NULL, 902, 'e9_n2_s4', 'Aku akan pilih kad yang sepadan dengan rekod S. Kuhan.', 4),
(1657, 162, 902, 'e9_n2_s4', 'Teliti kerana nanti murid salah faham. Jadi apakah yang boleh kita contohi daripada seorang ketua pasukan?', 5),
(1658, 170, 902, 'e9_n2_s5', 'Aku Nurul Huda Abdullah. Di Sukan SEA Bangkok 1985 aku memenangi tujuh pingat emas, dan di Sukan SEA Jakarta 1987 aku memenangi tujuh pingat emas lagi.', 1),
(1659, 170, 902, 'e9_n2_s5', 'Di Sukan SEA Kuala Lumpur 1989 pula aku memenangi lapan pingat emas.', 2),
(1660, 171, 902, 'e9_n2_s5', 'Aku Abdul Malek Mohamed Noor. Aku digelar Mr. Asia enam kali dalam kategori heavyweight bina badan, dan dianugerahkan Olahragawan Negara pada tahun 1986.', 3),
(1661, NULL, 902, 'e9_n2_s5', 'Aku akan padankan rekod setiap atlet dengan butirannya.', 4),
(1662, 162, 902, 'e9_n2_s5', 'Cekap, tetapi jangan campur tahun. Apakah yang memungkinkan rekod sebanyak itu?', 5),
(1663, 162, 902, 'e9_n2_s6', 'Sukan baharu pun boleh membanggakan negara. Murid-murid, ada sesiapa kenal e-sukan?', 1),
(1664, 169, 902, 'e9_n2_s6', 'Kami Team Secret MY. Kami mewakili negara dalam Kejohanan Final Global PUBG Mobile atau PMGC 2021.', 2),
(1665, 169, 902, 'e9_n2_s6', 'Kami menduduki tempat ketujuh terbaik dunia.', 3),
(1666, NULL, 902, 'e9_n2_s6', 'Aku akan pilih kad yang betul. Tempat ketujuh terbaik dunia dalam PMGC 2021.', 4),
(1667, 162, 902, 'e9_n2_s6', 'Jawab dengan fakta, bukan agakan. Jadi bolehkah sukan baharu turut mengharumkan nama negara?', 5),
(1668, 172, 902, 'e9_n2_s7', 'Aku Bonnie Bunyau Gustin dalam angkat berat. Aku memenangi emas Paralimpik Tokyo 2020.', 1),
(1669, 173, 902, 'e9_n2_s7', 'Aku Muhammad Ziyad Zolkefli dalam lontar peluru F20. Rekod dunia aku ialah 16.84 meter.', 2),
(1670, 174, 902, 'e9_n2_s7', 'Aku Mohamad Ridzuan Mohamad Puzi dalam 100 meter T36 untuk cerebral palsy. Aku memenangi emas Rio 2016.', 3),
(1671, 175, 902, 'e9_n2_s7', 'Aku Abdul Latif Romly dalam lompat jauh T20. Rekod dunia aku ialah 7.60 meter.', 4),
(1672, 162, 902, 'e9_n2_s7', 'Slogan atlet paralimpik negara ialah Kami Luar Biasa.', 5),
(1673, NULL, 902, 'e9_n2_s7', 'Aku akan padankan atlet dengan acara dan rekod mereka.', 6),
(1674, 162, 902, 'e9_n2_s7', 'Padankan dengan betul. Apakah yang boleh kita pelajari daripada kesungguhan mereka?', 7),
(1675, 162, 902, 'e9_n2_s8', 'Pengetua bertanya, mengapa negara kita dipercayai menjadi tuan rumah sukan antarabangsa?', 1),
(1676, 163, 902, 'e9_n2_s8', 'Kad ini menyebut negara kita memiliki infrastruktur sukan yang lengkap, cikgu.', 2),
(1677, 162, 902, 'e9_n2_s8', 'Peranan itu menjadikan negara dikenali pada peringkat dunia, menarik kedatangan pelancong luar negara dan menyumbang kepada pembangunan ekonomi negara.', 3),
(1678, NULL, 902, 'e9_n2_s8', 'Aku akan pilih faedah yang sama dengan kad itu.', 4),
(1679, 162, 902, 'e9_n2_s8', 'Pilih dengan teliti. Jadi apakah yang negara peroleh apabila menjadi tuan rumah?', 5),
(1680, 163, 903, NULL, 'Tugasku mengisi buku skrap dengan keratan yang tepat. Jika aku tersilap, buku ini tidak boleh dijadikan rujukan, {nama}.', 1),
(1681, 163, 903, NULL, 'Aku belajar bahawa sukan memupuk perpaduan dan keharmonian kaum serta membawa pembangunan kepada negara.', 2),
(1682, 163, 903, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, murid peminat sukan dengan buku skrap. Semak setiap keratan dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1683, 163, 903, 'e9_n3_s1', 'Buku skrap aku ada enam program sukan perpaduan tetapi keterangannya bercampur.', 1),
(1684, 162, 903, 'e9_n3_s1', 'RIMUP, Rancangan Integrasi Murid Untuk Perpaduan, diperkenalkan pada tahun 2005. Ia kerjasama aktiviti sukan antara sekolah untuk memupuk perpaduan murid.', 2),
(1685, 162, 903, 'e9_n3_s1', 'Dasar 1Murid 1Sukan bermula pada tahun 2011 supaya setiap murid terlibat dalam sekurang-kurangnya satu bidang sukan. Kejohanan MSSM dianjurkan setiap tahun untuk atlet remaja.', 3),
(1686, 162, 903, 'e9_n3_s1', 'Temasya Sukan Malaysia atau SUKMA dianjurkan secara bergilir-gilir oleh setiap negeri. SUKIPT untuk atlet peringkat institusi pengajian tinggi, dan Sukan Paralimpik untuk Orang Kurang Upaya atau OKU.', 4),
(1687, NULL, 903, 'e9_n3_s1', 'Aku akan padankan enam program itu dengan keterangannya.', 5),
(1688, 163, 903, 'e9_n3_s1', 'Teliti kerana ini untuk peperiksaan. Mengapakah sukan dapat memupuk perpaduan?', 6),
(1689, 163, 903, 'e9_n3_s2', 'Nota aku menyebut satu temasya yang paling besar dalam negara.', 1),
(1690, 162, 903, 'e9_n3_s2', 'Itulah Temasya Sukan Malaysia atau SUKMA, yang dianjurkan secara bergilir-gilir oleh setiap negeri. SUKMA yang pertama diadakan pada tahun 1986.', 2),
(1691, 162, 903, 'e9_n3_s2', 'Pelibatan atlet pelbagai kaum yang mewakili setiap negeri berjaya membentuk masyarakat yang harmoni.', 3),
(1692, NULL, 903, 'e9_n3_s2', 'Aku akan baca nota dan pilih temasya yang betul. SUKMA.', 4),
(1693, 163, 903, 'e9_n3_s2', 'Jangan teka, baca nota. Jadi apakah yang dibentuk oleh atlet pelbagai kaum yang mewakili negeri?', 5),
(1694, 163, 903, 'e9_n3_s3', 'Keratan akhbar tentang Sukan SEA ini jatuh bertaburan. Boleh susun mengikut tahun?', 1),
(1695, 162, 903, 'e9_n3_s3', 'Pada tahun 1959 Sukan SEAP, Southeast Asian Peninsular Games, mula dipertandingkan. Pada tahun 1965 Malaysia menjadi tuan rumah kejohanan Sukan SEAP.', 2),
(1696, 162, 903, 'e9_n3_s3', 'Pada tahun 1977 Sukan SEAP dikenali sebagai Sukan SEA. Pada tahun 2017 Malaysia menjadi tuan rumah Sukan SEA di Kuala Lumpur.', 3),
(1697, NULL, 903, 'e9_n3_s3', 'Aku akan susun peristiwa itu mengikut tahun.', 4),
(1698, 163, 903, 'e9_n3_s3', 'Susun betul-betul dan jangan terbalik. Apakah yang dirapatkan oleh penganjuran Sukan SEA?', 5),
(1699, 163, 903, 'e9_n3_s4', 'Gambar Piala Thomas dan Hoki Piala Dunia ini hampir sama. Beza tahun dan stadium?', 1),
(1700, 162, 903, 'e9_n3_s4', 'Piala Thomas pada 1970, 1984, 1988 dan 1992 dianjurkan di Stadium Negara, Kuala Lumpur. Piala Thomas 2000 dan 2010 pula di Stadium Putra, Bukit Jalil.', 2),
(1701, 162, 903, 'e9_n3_s4', 'Itu bermakna negara kita menganjurkan Piala Thomas sebanyak enam kali.', 3),
(1702, 162, 903, 'e9_n3_s4', 'Hoki Piala Dunia 1975 dianjurkan di Stadium Merdeka dengan 12 buah negara. Hoki Piala Dunia 2002 di Stadium Hoki Nasional Bukit Jalil dengan 16 buah negara.', 4),
(1703, NULL, 903, 'e9_n3_s4', 'Aku akan padankan kejohanan dengan stadium dan jumlah negara.', 5),
(1704, 163, 903, 'e9_n3_s4', 'Teliti dan jangan campur. Apakah yang dibawa oleh penganjuran kejohanan kepada negara?', 6),
(1705, 163, 903, 'e9_n3_s5', 'Tiket-tiket acara antarabangsa ini bercampur dalam kotak. Siapa boleh asingkan?', 1),
(1706, 162, 903, 'e9_n3_s5', 'MotoGP dan SBK ialah sukan permotoran antarabangsa yang bermula pada tahun 1991. Le Tour de Langkawi ialah lumba basikal antarabangsa tahunan yang bermula pada tahun 1996.', 2),
(1707, 162, 903, 'e9_n3_s5', 'Sukan Komanwel 1998 menjadikan kita negara Asia pertama menjadi tuan rumah. Formula One dianjurkan di Sepang International Circuit sejak tahun 2000.', 3),
(1708, 162, 903, 'e9_n3_s5', 'Formula E diadakan di Putrajaya pada tahun 2014. Piala Monsun pula sukan perahu layar di Pulau Duyong, Terengganu sejak tahun 2005.', 4),
(1709, NULL, 903, 'e9_n3_s5', 'Aku akan padankan acara dengan tahun dan tempatnya.', 5),
(1710, 163, 903, 'e9_n3_s5', 'Jangan campur tarikh. Apakah faedah acara besar ini kepada negara?', 6),
(1711, 163, 903, 'e9_n3_s6', 'Nota Sukan Komanwel 1998 ini aku tampal di halaman paling depan.', 1),
(1712, 162, 903, 'e9_n3_s6', 'Malaysia ialah negara Asia pertama menjadi tuan rumah Sukan Komanwel, iaitu pada tahun 1998. Stadium Nasional Bukit Jalil menjadi stadium utama kejohanan.', 2),
(1713, 162, 903, 'e9_n3_s6', 'Imej Orang Utan dipilih sebagai maskot dan bunga raya menjadi logo kejohanan.', 3),
(1714, NULL, 903, 'e9_n3_s6', 'Aku akan baca nota dan pilih maskot dan logo yang betul.', 4),
(1715, 163, 903, 'e9_n3_s6', 'Jangan buat aku malu di kelas. Jadi apakah yang dipupuk oleh Sukan Komanwel?', 5),
(1716, 163, 903, 'e9_n3_s7', 'Guru kata sukan menyatukan kita semua. Tetapi apa peranan diri, masyarakat dan negara?', 1),
(1717, 162, 903, 'e9_n3_s7', 'Pada peringkat diri kita mengamalkan sikap saling menghormati antara kaum melalui sukan.', 2),
(1718, 162, 903, 'e9_n3_s7', 'Pada peringkat masyarakat, perpaduan dan keharmonian kaum menjamin kesejahteraan masyarakat. Pada peringkat negara, keamanan dan kemakmuran dinikmati bersama apabila perpaduan dikekalkan.', 3),
(1719, NULL, 903, 'e9_n3_s7', 'Aku akan padankan diri, masyarakat dan negara dengan peranan masing-masing.', 4),
(1720, 163, 903, 'e9_n3_s7', 'Jangan campur aduk. Mengapa perpaduan perlu dikekalkan supaya sukan terus cemerlang?', 5),
(1721, 176, 903, 'e9_n3_s8', 'Aku Sultan Azlan Muhibbuddin Shah, dikenali sebagai Bapa Hoki Malaysia. Aku Presiden Persekutuan Hoki Malaysia dari tahun 1985 hingga 2004.', 1),
(1722, 176, 903, 'e9_n3_s8', 'Piala Sultan Azlan Shah ialah kejohanan hoki lapan pasukan terbaik dunia sejak tahun 1992.', 2),
(1723, 177, 903, 'e9_n3_s8', 'Aku Dato'' Peter Velappan, Setiausaha Agung Asian Football Confederation dari tahun 1978 hingga 2007.', 3),
(1724, 178, 903, 'e9_n3_s8', 'Aku Dato'' Sieh Kok Chi, atlet polo air dan Setiausaha Agung Majlis Olimpik Malaysia dari tahun 1992 hingga 2015.', 4),
(1725, NULL, 903, 'e9_n3_s8', 'Aku akan padankan tokoh dengan sumbangan mereka.', 5),
(1726, 163, 903, 'e9_n3_s8', 'Padankan dengan betul. Apakah yang membuktikan kepimpinan sukan mengharumkan nama Malaysia?', 6),
(1727, 221, 1001, NULL, 'Tugasku mewakili suara muda di sidang ASEAN. Jika fakta silap, wakil negara lain akan menyangka Malaysia tidak bersedia, {nama}.', 1),
(1728, 221, 1001, NULL, 'Aku belajar bahawa hubungan baik dengan negara jiran memelihara keharmonian dan menjadikan negara dihormati.', 2),
(1729, 221, 1001, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, wakil muda yang menghadiri sidang ASEAN. Dengar hujah wakil lain dengan teliti. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1730, 221, 1001, 'e10_n1_s1', 'Sidang serantau bermula sebentar lagi dan aku keliru dengan tiga singkatan ini. Tolong aku sebelum wakil lain tiba.', 1),
(1731, 231, 1001, 'e10_n1_s1', 'Aku Wakil Indonesia. SEAFET ditubuhkan pada tahun 1959 dan anggotanya Persekutuan Tanah Melayu, Thailand dan Filipina.', 2),
(1732, 231, 1001, 'e10_n1_s1', 'ASA pula ditubuhkan pada tahun 1961 dengan Persekutuan Tanah Melayu, Thailand dan Filipina juga. ASEAN lahir pada tahun 1967 dan pada awalnya dianggotai lima buah negara.', 3),
(1733, NULL, 1001, 'e10_n1_s1', 'Aku akan padankan pertubuhan, tahun dan anggotanya.', 4),
(1734, 221, 1001, 'e10_n1_s1', 'Jangan salah kerana nota sidang akan tercemar. Mengapakah negara berjiran perlu bekerjasama?', 5),
(1735, 224, 1001, 'e10_n1_s2', 'Aku Pakar Ekonomi ASEAN. Keluarga ASEAN membesar sedikit demi sedikit, bukan sekali gus.', 1),
(1736, 224, 1001, 'e10_n1_s2', 'Pada tahun 1959 Malaysia menyertai SEAFET. Pada tahun 1961 Persekutuan Tanah Melayu menyertai ASA. Pada tahun 1967 ASEAN ditubuhkan dengan lima negara awal.', 2),
(1737, 231, 1001, 'e10_n1_s2', 'Brunei menyertai pada tahun 1984. Vietnam menyertai pada tahun 1995, dan Laos serta Myanmar menyertai serentak pada tahun 1997.', 3),
(1738, 231, 1001, 'e10_n1_s2', 'Kemboja menyertai pada tahun 1999, lalu genaplah sepuluh negara anggota.', 4),
(1739, NULL, 1001, 'e10_n1_s2', 'Aku akan susun peristiwa itu mengikut tahun.', 5),
(1740, 221, 1001, 'e10_n1_s2', 'Susun betul-betul kerana nanti peta jadi salah. Mengapakah anggota ASEAN terus bertambah?', 6),
(1741, 221, 1001, 'e10_n1_s3', 'Bilik sidang ini penuh dengan petunjuk tentang ASEAN. Aku mahu empat daripadanya.', 1),
(1742, 231, 1001, 'e10_n1_s3', 'Bendera Malaysia di sana menunjukkan Malaysia tuan rumah Mesyuarat Menteri Luar ASEAN. Peta Asia Tenggara di dinding menunjukkan ASEAN dianggotai 10 negara Asia Tenggara.', 2),
(1743, 224, 1001, 'e10_n1_s3', 'Bendera Singapura menunjukkan Singapura salah satu negara awal ASEAN. Dokumen perjanjian di meja menyatakan matlamat keamanan dan kestabilan politik.', 3),
(1744, NULL, 1001, 'e10_n1_s3', 'Bendera Malaysia, peta Asia Tenggara, bendera Singapura dan dokumen perjanjian. Aku akan cari keempat-empatnya.', 4),
(1745, 221, 1001, 'e10_n1_s3', 'Teliti supaya tiada yang terlepas. Jadi apakah yang dijamin oleh kerjasama serantau?', 5),
(1746, 231, 1001, 'e10_n1_s4', 'Kad latar belakang ASEAN ini terkoyak. Boleh kamu bacakan semula?', 1),
(1747, 224, 1001, 'e10_n1_s4', 'ASEAN ditubuhkan pada 8 Ogos 1967 dan kini dianggotai oleh 10 buah negara Asia Tenggara.', 2),
(1748, 224, 1001, 'e10_n1_s4', 'Ibu pejabat ASEAN terletak di Jakarta, Indonesia. Tarikh 31 Ogos 1957 ialah hari kemerdekaan Tanah Melayu, dan 16 September 1963 ialah hari Malaysia dibentuk.', 3),
(1749, NULL, 1001, 'e10_n1_s4', 'Aku akan pilih kad yang betul. 8 Ogos 1967, 10 negara dan ibu pejabat di Jakarta.', 4),
(1750, 221, 1001, 'e10_n1_s4', 'Cepat kerana sidang bermula. Dan apakah peranan Malaysia semasa ASEAN ditubuhkan?', 5),
(1751, 224, 1001, 'e10_n1_s5', 'ASEAN ada empat matlamat dan aku selalu menyebutnya dalam ucapan. Bantu aku sebut semuanya.', 1),
(1752, 231, 1001, 'e10_n1_s5', 'Keamanan bermaksud menjamin keamanan dan kestabilan politik. Pertumbuhan bermaksud menggalakkan pertumbuhan ekonomi, kemajuan sosial dan pembangunan kebudayaan.', 2),
(1753, 231, 1001, 'e10_n1_s5', 'Kerjasama bermaksud menjalin kerjasama dalam bidang latihan dan penyelidikan. Kesejahteraan bermaksud meningkatkan taraf hidup penduduk.', 3),
(1754, NULL, 1001, 'e10_n1_s5', 'Aku akan padankan empat matlamat itu dengan maksudnya.', 4),
(1755, 221, 1001, 'e10_n1_s5', 'Teliti supaya laporan tepat. Apakah faedah hubungan baik dengan jiran?', 5),
(1756, 221, 1001, 'e10_n1_s6', 'Lihat logo ASEAN di dinding ini. Setiap warna dan bentuk ada maknanya.', 1),
(1757, 231, 1001, 'e10_n1_s6', 'Warna biru melambangkan keamanan dan kestabilan. Warna merah melambangkan semangat dan dinamisme.', 2),
(1758, 231, 1001, 'e10_n1_s6', 'Warna kuning melambangkan kemakmuran dan warna putih melambangkan kesucian. Sepuluh tangkai padi melambangkan impian pengasasan ASEAN yang diikat persahabatan dan perpaduan, dan bulatan melambangkan kesatuan ASEAN.', 3),
(1759, NULL, 1001, 'e10_n1_s6', 'Aku akan padankan warna dan bentuk dengan maknanya.', 4),
(1760, 221, 1001, 'e10_n1_s6', 'Teliti kerana ini maruah ASEAN. Apakah yang diingatkan oleh logo itu kepada kita?', 5),
(1761, 224, 1001, 'e10_n1_s7', 'Apa sahaja yang Malaysia dapat daripada ASEAN? Aku mahu kamu senaraikan faedahnya.', 1),
(1762, 231, 1001, 'e10_n1_s7', 'Dari segi keamanan dan kestabilan politik, Deklarasi Kuala Lumpur 1971 mengisytiharkan ZOPFAN. Dari segi pertumbuhan ekonomi, ada projek perindustrian baja urea di Bintulu, Sarawak.', 2),
(1763, 231, 1001, 'e10_n1_s7', 'Dari segi pertumbuhan sosial, Malaysia menjadi tuan rumah penganjuran Sukan SEA. Dari segi latihan dan penyelidikan, RECSAM dibina di Pulau Pinang.', 3),
(1764, NULL, 1001, 'e10_n1_s7', 'Aku akan padankan faedah itu dengan buktinya.', 4),
(1765, 221, 1001, 'e10_n1_s7', 'Jangan lupa ZOPFAN kerana ia penting. Jadi dengan siapakah faedah ini dikongsi?', 5),
(1766, 224, 1001, 'e10_n1_s8', 'Dokumen ini menyenaraikan sumbangan Malaysia kepada ASEAN, tetapi senarainya bercampur dengan pertubuhan lain.', 1),
(1767, 231, 1001, 'e10_n1_s8', 'Malaysia menjadi tuan rumah Mesyuarat Menteri-Menteri Luar ASEAN dan membantu menangani isu pencerobohan Vietnam terhadap Kemboja.', 2),
(1768, 231, 1001, 'e10_n1_s8', 'Malaysia juga membantu meredakan konflik politik di selatan Filipina, mengutarakan penubuhan ZOPFAN dan menyertai Pertubuhan Menteri-Menteri Pelajaran ASEAN atau SEAMEO.', 3),
(1769, NULL, 1001, 'e10_n1_s8', 'Aku akan pilih sumbangan yang betul. Mengutarakan ZOPFAN dan membantu meredakan konflik di selatan Filipina.', 4),
(1770, 221, 1001, 'e10_n1_s8', 'Jangan campur dengan sumbangan PBB. Dan apakah perasaan negara anggota terhadap Malaysia?', 5),
(1771, 222, 1002, NULL, 'Tugasku menjaga keamanan dan mengenali setiap pertubuhan. Jika aku keliru, bantuan akan sampai ke tempat yang salah, {nama}.', 1),
(1772, 222, 1002, NULL, 'Aku belajar bahawa Malaysia menyumbang kepada keamanan dunia melalui rundingan perdamaian dan hubungan baik dengan negara luar.', 2),
(1773, 222, 1002, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, penjaga keamanan PBB dengan topi biru. Peka kepada setiap perubahan di sekeliling. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1774, 222, 1002, 'e10_n2_s1', 'Aku Penjaga Keamanan PBB. Hari ini kita meronda dewan sidang ini untuk mencari empat petunjuk.', 1),
(1775, 225, 1002, 'e10_n2_s1', 'Dewan sidang ini menunjukkan keahlian PBB terbuka kepada semua negara. Bendera Malaysia menunjukkan Malaysia negara anggota PBB yang aktif menyumbang.', 2),
(1776, 225, 1002, 'e10_n2_s1', 'Peta dunia di skrin menunjukkan pasukan pengaman PBB termasuk Malaysia. Peta di skrin utama menunjukkan kawasan tugas pasukan pengaman PBB.', 3),
(1777, NULL, 1002, 'e10_n2_s1', 'Dewan sidang, bendera Malaysia, peta dunia dan peta di skrin utama. Aku akan cari keempat-empatnya.', 4),
(1778, 222, 1002, 'e10_n2_s1', 'Teliti kerana ini dewan antarabangsa. Jadi apakah tugas pasukan pengaman itu?', 5),
(1779, 225, 1002, 'e10_n2_s2', 'Wakil baharu selalu keliru tentang PBB. Bacakan kad latar belakangnya.', 1),
(1780, 222, 1002, 'e10_n2_s2', 'PBB ditubuhkan pada 24 Oktober 1945 selepas Perang Dunia Kedua. Keahliannya terbuka kepada semua negara di seluruh dunia.', 2),
(1781, 222, 1002, 'e10_n2_s2', 'Ibu pejabat PBB terletak di New York, Amerika Syarikat. Bahasa rasminya ialah bahasa Arab, Mandarin, Inggeris, Perancis, Rusia dan Sepanyol, iaitu enam bahasa rasmi.', 3),
(1782, NULL, 1002, 'e10_n2_s2', 'Aku akan pilih kad yang betul. 24 Oktober 1945, ibu pejabat di New York dan enam bahasa rasmi.', 4),
(1783, 225, 1002, 'e10_n2_s2', 'Tepat atau wakil baharu akan keliru. Dan apakah yang dijamin oleh PBB?', 5),
(1784, 226, 1002, 'e10_n2_s3', 'Aku Utusan Komanwel. Malaysia menyertai Komanwel pada tahun 1957, dan Komanwel dianggotai bekas tanah jajahan British.', 1),
(1785, 225, 1002, 'e10_n2_s3', 'Malaysia menyertai PBB pada tahun 1957 juga. Keahlian PBB terbuka kepada semua negara.', 2),
(1786, 228, 1002, 'e10_n2_s3', 'Aku Duta NAM. Malaysia menyertai Pergerakan Negara-negara Berkecuali sejak tahun 1970, dan NAM dianggotai 120 negara membangun dari Asia, Afrika dan Amerika Selatan.', 3),
(1787, 227, 1002, 'e10_n2_s3', 'OIC pula disertai Malaysia sejak penubuhannya pada 1969, dan awalnya dianggotai 57 negara.', 4),
(1788, NULL, 1002, 'e10_n2_s3', 'Aku akan padankan pertubuhan antarabangsa itu dengan butirannya.', 5),
(1789, 226, 1002, 'e10_n2_s3', 'Teliti dan jangan campur. Apakah dasar yang diamalkan oleh Malaysia dengan semua pertubuhan ini?', 6),
(1790, 226, 1002, 'e10_n2_s4', 'Dokumen Komanwel ini luntur. Boleh bacakan semula?', 1),
(1791, 226, 1002, 'e10_n2_s4', 'Komanwel dibentuk pada 11 Disember 1931 dan dianggotai oleh 54 buah negara bekas tanah jajahan British kecuali Mozambique dan Republik Rwanda.', 2),
(1792, 226, 1002, 'e10_n2_s4', 'Ibu pejabat Sekretariat Komanwel terletak di London, England. Matlamatnya membina semangat setia kawan dan mewujudkan kerjasama dalam pendidikan, ekonomi, kesihatan serta belia dan sukan.', 3),
(1793, NULL, 1002, 'e10_n2_s4', 'Aku akan pilih dokumen yang betul. Dibentuk 1931, 54 negara dan Sekretariat di London.', 4),
(1794, 226, 1002, 'e10_n2_s4', 'Jangan terburu-buru. Dan apakah yang dibina oleh Komanwel antara negara anggota?', 5),
(1795, 226, 1002, 'e10_n2_s5', 'Malaysia mendapat banyak faedah daripada Komanwel dalam empat bidang.', 1),
(1796, 226, 1002, 'e10_n2_s5', 'Dalam pendidikan, ada tawaran biasiswa Komanwel untuk melanjutkan pendidikan tinggi. Dalam perdagangan, barangan Malaysia mudah menembusi pasaran antarabangsa.', 2),
(1797, 226, 1002, 'e10_n2_s5', 'Dalam kesihatan, maklumat dan data dikongsi untuk menangani wabak seperti COVID-19. Dalam belia dan sukan, Sukan Komanwel dianjurkan di Malaysia pada tahun 1998.', 3),
(1798, NULL, 1002, 'e10_n2_s5', 'Aku akan padankan bidang itu dengan faedahnya.', 4),
(1799, 226, 1002, 'e10_n2_s5', 'Bagus, padankan satu demi satu. Jadi apakah yang ditawarkan oleh Komanwel kepada banyak bidang?', 5),
(1800, 226, 1002, 'e10_n2_s6', 'Nota ini menyebut dua sumbangan besar Malaysia dalam Komanwel.', 1),
(1801, 226, 1002, 'e10_n2_s6', 'Malaysia mengecam dasar Aparteid di Afrika Selatan yang membezakan penduduk mengikut warna kulit dan membantu menamatkannya pada tahun 1993.', 2),
(1802, 226, 1002, 'e10_n2_s6', 'Malaysia juga menjadi tuan rumah Commonwealth Heads of Government Meeting atau CHOGM pada tahun 1989 dan mengisytiharkan Deklarasi Langkawi 1989 tentang pencemaran alam sekitar.', 3),
(1803, NULL, 1002, 'e10_n2_s6', 'Aku akan pilih sumbangan yang betul. Menamatkan Aparteid pada 1993 dan Deklarasi Langkawi 1989.', 4),
(1804, 226, 1002, 'e10_n2_s6', 'Jangan campur dengan sumbangan organisasi lain. Dan apakah yang dikecam serta dipelihara oleh Malaysia?', 5),
(1805, 227, 1002, 'e10_n2_s7', 'Aku Wakil OIC. Kad latar belakang ini tertulis tentang pengasas kami.', 1),
(1806, 230, 1002, 'e10_n2_s7', 'Aku Tunku Abdul Rahman. OIC ditubuhkan pada 25 September 1969 dan aku dilantik sebagai Setiausaha Agung OIC yang pertama.', 2),
(1807, 227, 1002, 'e10_n2_s7', 'Pejabat OIC terletak di Jeddah, Arab Saudi dan OIC dianggotai 57 buah negara. Bahasa rasminya ialah bahasa Arab, Inggeris dan Perancis.', 3),
(1808, NULL, 1002, 'e10_n2_s7', 'Aku akan pilih kad yang betul. Setiausaha Agung pertama, pejabat di Jeddah dan 57 negara.', 4),
(1809, 227, 1002, 'e10_n2_s7', 'Jangan salah kerana nanti Tunku tersinggung. Dan apakah yang dikukuhkan oleh OIC?', 5),
(1810, 229, 1002, 'e10_n2_s8', 'Aku Sukarelawan Kemanusiaan OIC. Bantu aku menyusun sumbangan Malaysia.', 1),
(1811, 227, 1002, 'e10_n2_s8', 'Malaysia membantu penubuhan Bank Pembangunan Islam pada tahun 1975. Malaysia menangani isu Bosnia dan Herzegovina pada tahun 1991.', 2),
(1812, 227, 1002, 'e10_n2_s8', 'Malaysia menubuhkan Universiti Islam Antarabangsa Malaysia atau UIAM pada tahun 1983. Malaysia menjadi tuan rumah Persidangan OIC pada tahun 1974 dan 2003.', 3),
(1813, 229, 1002, 'e10_n2_s8', 'Malaysia juga menyokong penuh perjuangan rakyat Palestin menentang kekejaman Israel.', 4),
(1814, NULL, 1002, 'e10_n2_s8', 'Aku akan padankan sumbangan itu dengan butirannya.', 5),
(1815, 229, 1002, 'e10_n2_s8', 'Cepat kerana laporan tahunan sudah dekat. Jadi mengapa penglibatan Malaysia dalam OIC penting?', 6),
(1816, 223, 1003, NULL, 'Tugasku membimbing pelawat melalui pameran dengan fakta yang tepat. Jika aku silap, pelawat akan membawa pulang cerita yang salah, {nama}.', 1),
(1817, 223, 1003, NULL, 'Aku belajar bahawa pengiktirafan antarabangsa perlu dikekalkan dan hubungan baik menjadikan negara dihormati serta disegani.', 2),
(1818, 223, 1003, NULL, 'Jiwamu kutarik ke dalam jasad {peranan}, pemandu pameran UNESCO. Sambut pelawat dengan hormat. Lihat melalui matanya dan bercakaplah dengan suaranya.', 3),
(1819, 223, 1003, 'e10_n3_s1', 'Selamat datang ke Pameran Malaysia dan Dunia. Bilik ini menyimpan misi pasukan pengaman PBB, tetapi kad-kadnya bertaburan.', 1),
(1820, 222, 1003, 'e10_n3_s1', 'Aku Penjaga Keamanan PBB. Pada tahun 1961 Malaysia menghantar pasukan pengaman PBB ke Congo. Pada tahun 1965 Malaysia menjadi ahli tidak tetap Majlis Keselamatan PBB.', 2),
(1821, 222, 1003, 'e10_n3_s1', 'Pada tahun 1989 pasukan pengaman dihantar ke Namibia. Pada tahun 1990 pasukan pemerhati PBB dihantar ke sempadan Iran-Iraq.', 3),
(1822, 222, 1003, 'e10_n3_s1', 'Pada tahun 1992 pasukan pengaman dihantar ke Somalia dan Bosnia dan Herzegovina. Pada tahun 2007 pasukan pengaman Malaysia bertugas di Lubnan.', 4),
(1823, NULL, 1003, 'e10_n3_s1', 'Aku akan susun misi itu mengikut tahun.', 5),
(1824, 223, 1003, 'e10_n3_s1', 'Betulkan urutannya kerana ini sejarah negara. Apakah yang dilakukan oleh pasukan pengaman itu untuk dunia dan Malaysia?', 6),
(1825, 225, 1003, 'e10_n3_s2', 'Aku Wakil PBB. Pandangan Malaysia sering didengar di dewan ini dan aku mahu kamu padankan sumbangannya.', 1),
(1826, 225, 1003, 'e10_n3_s2', 'Mengenai konflik Palestin-Israel, Malaysia mencari penyelesaian yang adil dan berkekalan. Mengenai penyalahgunaan dadah, ada Persidangan Antarabangsa Dadah di Vienna pada Jun 1987.', 2),
(1827, 225, 1003, 'e10_n3_s2', 'Presiden persidangan dadah 1987 ialah Tun Dr. Mahathir Mohamad, Perdana Menteri keempat. Dalam mutu pendidikan, Malaysia memperjuangkan prinsip Pendidikan untuk Semua melalui UNESCO.', 3),
(1828, 225, 1003, 'e10_n3_s2', 'Malaysia ahli tidak tetap Majlis Keselamatan PBB pada tahun 1965, 1989 hingga 1990, 1999 hingga 2000 dan 2015 hingga 2016.', 4),
(1829, NULL, 1003, 'e10_n3_s2', 'Aku akan padankan isu, tokoh dan penggal itu.', 5),
(1830, 223, 1003, 'e10_n3_s2', 'Teliti kerana pelawat menunggu. Bagaimanakah pandangan Malaysia disuarakan di PBB?', 6),
(1831, 223, 1003, 'e10_n3_s3', 'Kad-kad ini bertanya apa faedah Malaysia menyertai PBB.', 1),
(1832, 225, 1003, 'e10_n3_s3', 'Penyertaan dalam PBB membolehkan Malaysia memelihara dan mempertahankan kepentingan negara dalam sebarang keputusan yang diambil oleh PBB.', 2),
(1833, 225, 1003, 'e10_n3_s3', 'Malaysia juga meneruskan peranan aktif dengan menyumbang pendapat dan pandangan dalam pelbagai isu global serta meningkatkan komitmen menangani pelbagai isu.', 3),
(1834, NULL, 1003, 'e10_n3_s3', 'Aku akan pilih faedah yang betul. Mempertahankan kepentingan negara dan menyumbang pandangan dalam isu global.', 4),
(1835, 223, 1003, 'e10_n3_s3', 'Pilih dengan teliti. Jadi apakah yang diperoleh apabila kita aktif dalam PBB?', 5),
(1836, 225, 1003, 'e10_n3_s4', 'Tiga tokoh dan satu pasukan ini mengharumkan nama Malaysia di PBB.', 1),
(1837, 225, 1003, 'e10_n3_s4', 'Tan Sri Razali Ismail menjadi Pengerusi Majlis Keselamatan PBB pada tahun 1989 hingga 1990, dan Pengerusi Perhimpunan Agung PBB sesi ke-51 pada tahun 1996 hingga 1997.', 2),
(1838, 225, 1003, 'e10_n3_s4', 'Datuk Dr. Mazlan Othman menjadi Pengarah Hal Ehwal Angkasa Lepas PBB. Pasukan Pengaman PBB pula diiktiraf melalui sijil dan pingat perkhidmatan PBB.', 3),
(1839, NULL, 1003, 'e10_n3_s4', 'Aku akan padankan tokoh dan pasukan itu dengan jawatan mereka.', 4),
(1840, 223, 1003, 'e10_n3_s4', 'Teliti kerana ini pengiktirafan antarabangsa. Mengapakah pengiktirafan itu perlu dikekalkan?', 5),
(1841, 223, 1003, 'e10_n3_s5', 'Ini ruang UNESCO. Dalam kaca-kaca ini ada empat tapak warisan dunia Malaysia. Cari semuanya.', 1),
(1842, 222, 1003, 'e10_n3_s5', 'Gunung dalam kaca ialah Taman Kinabalu di Sabah, warisan alam 2000. Gua batu kapur ialah Taman Negara Gunung Mulu di Sarawak, warisan 2000 juga.', 2),
(1843, 223, 1003, 'e10_n3_s5', 'Peta bandar dalam kaca ialah Melaka dan George Town, warisan 2008. Hologram di tengah ialah Warisan Arkeologi Lembah Lenggong, 2012.', 3),
(1844, NULL, 1003, 'e10_n3_s5', 'Taman Kinabalu, Gunung Mulu, Melaka dan George Town serta Lembah Lenggong. Aku akan cari keempat-empatnya.', 4),
(1845, 223, 1003, 'e10_n3_s5', 'Teliti dan jangan terlepas. Jadi apa yang perlu kita lakukan terhadap warisan dunia itu?', 5),
(1846, 223, 1003, 'e10_n3_s6', 'UNESCO mengiktiraf warisan Malaysia dalam empat kategori. Boleh padankan?', 1),
(1847, 223, 1003, 'e10_n3_s6', 'Tapak Warisan Dunia Alam Semula Jadi ialah Taman Negara Gunung Mulu dan Taman Kinabalu. Tapak Warisan Dunia Kebudayaan ialah Melaka, George Town dan Lembah Lenggong.', 2),
(1848, 223, 1003, 'e10_n3_s6', 'Daftar Memori Dunia ialah Hikayat Hang Tuah, Sulalatus Salatin dan Batu Bersurat Terengganu. Daftar Warisan Budaya Tidak Ketara ialah Makyung, Dondang Sayang, Silat dan Wangkang.', 3),
(1849, NULL, 1003, 'e10_n3_s6', 'Aku akan padankan kategori dengan contohnya.', 4),
(1850, 225, 1003, 'e10_n3_s6', 'Teliti kerana ini pengiktirafan PBB. Apakah yang ditunjukkan oleh pengiktirafan UNESCO itu?', 5),
(1851, 223, 1003, 'e10_n3_s7', 'Tarikh-tarikh pengiktirafan UNESCO ini bertaburan di lantai. Siapa boleh susun?', 1),
(1852, 223, 1003, 'e10_n3_s7', 'Pada tahun 2000 Taman Negara Gunung Mulu dan Taman Kinabalu diiktiraf. Pada tahun 2001 Hikayat Hang Tuah diiktiraf Daftar Memori Dunia.', 2),
(1853, 223, 1003, 'e10_n3_s7', 'Pada tahun 2005 Makyung diiktiraf. Pada tahun 2008 Melaka dan George Town diiktiraf, dan pada tahun 2012 Warisan Arkeologi Lembah Lenggong diiktiraf.', 3),
(1854, 223, 1003, 'e10_n3_s7', 'Pada tahun 2018 Dondang Sayang diiktiraf, pada tahun 2019 Silat diiktiraf dan pada tahun 2020 Wangkang diiktiraf.', 4),
(1855, NULL, 1003, 'e10_n3_s7', 'Aku akan susun pengiktirafan itu mengikut tahun.', 5),
(1856, 225, 1003, 'e10_n3_s7', 'Teliti kerana ada banyak tahun. Dan apakah yang perlu kita usahakan terhadap pengiktirafan itu?', 6),
(1857, 225, 1003, 'e10_n3_s8', 'Kad penutup ini bertanya, mengapa hubungan baik dengan negara luar penting?', 1),
(1858, 223, 1003, 'e10_n3_s8', 'Malaysia mengamalkan dasar berbaik-baik dengan semua negara dan bertanggungjawab memastikan kestabilan politik, kemajuan ekonomi serta keharmonian rakyatnya.', 2),
(1859, 223, 1003, 'e10_n3_s8', 'Hubungan baik dengan negara luar penting bagi menjamin keselamatan dan kemakmuran rakyat serta negara.', 3),
(1860, NULL, 1003, 'e10_n3_s8', 'Aku akan pilih jawapan yang betul. Menjamin keselamatan dan kemakmuran rakyat serta negara.', 4),
(1861, 225, 1003, 'e10_n3_s8', 'Fikir tentang keselamatan dan kemakmuran. Jadi bagaimanakah negara lain memandang negara yang berbaik-baik dengan semua?', 5),
(1862, 223, 1003, 'e10_n3_s9', 'Pameran ini hampir tamat. Satu soalan terakhir, apakah peranan diri, masyarakat dan negara?', 1),
(1863, 225, 1003, 'e10_n3_s9', 'Diri memelihara hubungan baik dengan jiran supaya keharmonian dapat dipupuk.', 2),
(1864, 225, 1003, 'e10_n3_s9', 'Masyarakat membentuk perpaduan dan hubungan baik mendatangkan faedah kepada semua. Negara pula menikmati kesepakatan yang menjadikan negara dihormati serta disegani.', 3),
(1865, NULL, 1003, 'e10_n3_s9', 'Aku akan padankan diri, masyarakat dan negara dengan peranannya.', 4),
(1866, 223, 1003, 'e10_n3_s9', 'Jangan campur aduk. Apakah yang dipastikan oleh pandangan dan sumbangan Malaysia kepada dunia?', 5);
