INSERT INTO `narrative` (`narrativeID`, `narrativeTitle`, `eraID`, `summary`) VALUES
(1, 'Perjalanan Sang Arsitek', 1, 'Masuki peranan Tunku Abdul Rahman. Daripada idea lama sejak 1887 hingga Pemasyhuran 16 September 1963, kau menjelaskan sebab, mengatur langkah, mendengar Borneo dan Singapura, lalu menghadapi cabaran dalam dan luar negara.'),
(2, 'Suara dari Borneo', 1, 'Masuki peranan Donald Stephens, pemimpin UNKO di Sabah. Dengar kebimbangan rakyat, bawa suara Borneo ke JSKM, Cobbold, JAK dan UNMM, hingga Pemasyhuran 16 September 1963 dan cabaran selepasnya.'),
(3, 'Pegawai di Sebalik Tabir', 1, 'Masuki peranan Ghazali Shafie, pegawai kanan yang menyusun kerja di sebalik tabir. Susun idea, sebab, jawatankuasa dan perjanjian, hingga Pemasyhuran 16 September 1963 dan cabaran selepasnya.'),
(201, 'Buku Asal Usul', 2, 'Masuki peranan Tok Penglipur Lara yang membawa Buku Asal Usul dari negeri ke negeri. Di setiap tempat kau mencatat nama, ibu negeri, lagu dan ketua negeri, hingga Pesta Warisan Negara.'),
(202, 'Tiga Hari Sebelum Istiadat', 2, 'Sebagai Pegawai Istiadat Negara, kau ada tiga hari untuk menyiapkan Istiadat Pembukaan Pesta Warisan Negara. Seseorang menukar kad, kaset dan fail. Kumpul bukti sebelum tirai dibuka.'),
(203, 'Pasport Warisan', 2, 'Sebagai Pengembara Warisan, kau membawa buku pasport dari Borneo ke Semenanjung dan mengumpul satu cop di setiap wilayah. Halaman terakhir koyak dan misterinya terungkap di Pesta Warisan Negara.'),
(301, 'Arahan dari Bilik Gerakan', 3, 'Masuki peranan Tun Abdul Razak, Pengarah MAGERAN. Selepas 13 Mei 1969 kau menenangkan negara, mencari punca perpecahan, menubuhkan MAPEN dan merangka Rukun Negara hingga ia diisytiharkan pada 31 Ogos 1970.'),
(302, 'Pintu Rumah Rakyat', 3, 'Masuki peranan Tun V. T. Sambanthan, wakil rakyat yang mengetuk pintu rumah dan mendengar suara semua kaum. Daripada punca rusuhan hingga lima prinsip dan enam peranan, ceritakan Rukun Negara dari sisi rakyat biasa.'),
(303, 'Ikrar Satu Malaysia', 3, 'Masuki peranan Tunku Abdul Rahman pada hari Rukun Negara diisytiharkan. Ikuti tarikh, wakil, matlamat, prinsip dan peranan yang menjadikan ikrar itu pegangan seluruh rakyat Malaysia.'),
(401, 'Rentak Seribu Kaum', 4, 'Masuki peranan seorang pemuzik tua yang mengembara dari kampung ke kampung membawa gambus, sape dan gendang. Dalam setiap rentak kau mengenali kaum, alat muzik dan tarian tradisional Malaysia.'),
(402, 'Peti Cerita Nenek', 4, 'Masuki peranan Nenek Segala Kaum yang membuka peti cerita lamanya. Dari laci ke laci, kau mengajar cucu-cucu tentang petempatan dan ekonomi dahulu serta kini, dan tiga cerita rakyat.'),
(403, 'Gelanggang Seribu Kaum', 4, 'Masuki peranan Tok Permainan yang menjaga gelanggang tempat semua kaum bermain bersama. Setiap pusingan mengajarmu permainan tradisional, legenda Nunuk Ragang dan nilai toleransi.'),
(501, 'Nota Lapangan Tujuh Pintu', 5, 'Masuki peranan seorang pengkaji budaya dengan buku nota lapangan. Dalam setiap misi kau mengenali agama dan ajaran di Malaysia, pengasas, kitab suci dan rumah ibadat.'),
(502, 'Persidangan Para Penjaga Adat', 5, 'Masuki peranan Bobohizan yang dijemput ke persidangan para penjaga adat. Kau belajar tentang animisme dan kepercayaan Orang Asli, Iban, Bisaya, Bajau dan Kadazandusun.'),
(503, 'Syair Seribu Kepercayaan', 5, 'Masuki peranan Lemambang yang melagukan syair di Pesta Kepercayaan Sekolah. Dalam setiap bait kau mengenali kedudukan agama dalam Perlembagaan, rumah ibadat dan adab di dalamnya.'),
(601, 'Bengkel Kraf Seribu Perayaan', 6, 'Masuki peranan penggiat kraf perayaan yang membuat hiasan untuk semua kaum. Dalam bengkelmu kau mengenali perayaan utama, tarikh dan maknanya.'),
(602, 'Pulang Beraya Bersama Nenek', 6, 'Masuki peranan seorang ibu moden yang membawa anak pulang beraya ke kampung. Bersama Nenek Dahulu, kau mengenali tujuan perayaan, cara sambutan dahulu dan kini, serta amalan yang kekal.'),
(603, 'Kedai Seribu Perayaan', 6, 'Masuki peranan peniaga rumah kedai yang menjual kad, kuih dan hiasan untuk semua perayaan. Setiap pelanggan membawa cerita tentang perayaan, Rumah Terbuka Malaysia dan nilai menghormati.'),
(701, 'Siaran Khas dari Pejabat Perdana Menteri', 7, 'Masuki peranan wartawan muda yang menemu bual Yang di-Pertuan Agong dan Perdana Menteri yang awal. Kau mengenali jawatan Perdana Menteri, biodata dan pencapaian Tunku, Tun Razak dan Tun Hussein.'),
(702, 'Perdana Menteri Keluar dari Buku Teks', 7, 'Masuki peranan guru Sejarah yang buku teksnya tiba-tiba menghidupkan para Perdana Menteri. Kau mengenali tugas Perdana Menteri serta biodata dan pencapaian Tun Dr. Mahathir hingga Dato'' Seri Ismail Sabri.'),
(703, 'Album Kad Koleksi Perdana Menteri', 7, 'Masuki peranan murid penyelidik yang membuat album kad koleksi Perdana Menteri. Kau mengumpul maklumat tentang jawatan, urutan, pencapaian, ciri kepimpinan berwibawa dan cara menghargai pemimpin.'),
(801, 'Dari Cangkul ke Jentera: Kembara Juruteknik', 8, 'Masuki peranan juruteknik mesin ladang yang mengembara dari sawah bercangkul ke ladang moden. Kau mengenali ekonomi tradisional dan komersial dalam pertanian dan perlombongan serta industri getah dan kelapa sawit.'),
(802, 'Pemeriksaan Mutu Ekonomi Negara', 8, 'Masuki peranan inspektor kilang yang memeriksa mutu ekonomi negara dengan borang dan cop LULUS. Kau mengenali industri petroleum dan gas, automotif dan pelancongan yang menjana pendapatan negara.'),
(803, 'Kedai Jenama Malaysia: Cerita Setiap Rak', 8, 'Masuki peranan pemilik kedai jenama Malaysia yang menceritakan kisah di sebalik setiap rak. Kau mengenali barangan buatan Malaysia, pencapaian pembangunan, perhubungan dan perdagangan serta kepentingan kemajuan ekonomi.'),
(901, 'Siaran Langsung Stadium Kebanggaan Negara', 9, 'Masuki peranan pengulas sukan yang membuat siaran langsung dari stadium ke stadium. Kau mengenali persatuan sukan, pencapaian badminton, bola sepak, olahraga dan hoki serta legenda sukan terdahulu.'),
(902, 'Latihan Pagi Jurulatih Sekolah', 9, 'Masuki peranan jurulatih sekolah yang melatih murid di padang, trek dan dewan. Kau mengenali atlet kebanggaan negara, atlet paralimpik, e-sukan dan faedah penganjuran sukan antarabangsa.'),
(903, 'Buku Skrap Peminat Sukan Negara', 9, 'Masuki peranan murid peminat sukan yang mengumpul kad dan keratan akhbar. Dalam buku skrapmu kau menyimpan program sukan perpaduan, penganjuran sukan antarabangsa dan tokoh inspirasi sukan negara.'),
(1001, 'Sidang Serantau Wakil Muda ASEAN', 10, 'Masuki peranan wakil muda ASEAN yang menghadiri sidang di bilik mesyuarat dunia. Kau mengenali pertubuhan serantau yang disertai Malaysia dan sumbangan Malaysia dalam ASEAN.'),
(1002, 'Rondaan Keamanan Penjaga Topi Biru', 10, 'Masuki peranan penjaga keamanan PBB yang meronda dari bilik mesyuarat ke bilik mesyuarat. Kau mengenali PBB, Komanwel, NAM dan OIC serta sumbangan Malaysia di setiap pertubuhan.'),
(1003, 'Lawatan Pameran Malaysia dan Dunia', 10, 'Masuki peranan pemandu pameran UNESCO yang membawa pelawat melawat bilik demi bilik. Kau mengenali sumbangan Malaysia dalam PBB, pengiktirafan PBB dan UNESCO serta nilai menjaga hubungan baik.');
INSERT INTO `npc` (`npcID`, `name`, `biography`, `contribution`, `asset`) VALUES
(1, 'Tunku Abdul Rahman Putra Al-Haj', 'Perdana Menteri pertama Persekutuan Tanah Melayu dan Bapa Kemerdekaan.', 'Meyakinkan lima wilayah bersatu tanpa paksaan: mendengar Borneo, menandatangani perjanjian dan mengisytiharkan Malaysia.', 'tunku_abdul_rahman.png'),
(2, 'Tun Temenggong Jugah anak Barieng', 'Pemimpin utama masyarakat Iban dari Sarawak dan pengerusi parti PESAKA.', 'Menegaskan perlindungan hak adat Sarawak dalam rundingan pembentukan Malaysia.', 'tun_temenggung_jugah.png'),
(3, 'Donald Stephens (Tun Fuad Stephens)', 'Tokoh utama Sabah dan Pengerusi Jawatankuasa Setia Kawan Malaysia (JSKM).', 'Membawa suara rakyat Borneo ke meja perundingan supaya hak mereka ditulis dalam Perlembagaan.', 'tun_muhammad_fuad_stephens.png'),
(4, 'Lee Kuan Yew', 'Perdana Menteri Singapura yang menyokong penggabungan dengan Malaysia.', 'Memimpin referendum Singapura dan menangani ancaman pengaruh komunis.', 'lee_kuan_yew.png'),
(5, 'Tun Abdul Razak bin Dato\' Hussein', 'Timbalan Perdana Menteri Persekutuan Tanah Melayu dan Pengerusi JAK.', 'Merangka hak perlembagaan dan perlindungan khas bagi Sabah dan Sarawak.', 'tun_abdul_razak.png'),
(6, 'Tan Sri Stephen Kalong Ningkan', 'Ketua Menteri Sarawak yang pertama dan pengasas Perikatan Sarawak.', 'Memimpin Sarawak menyertai Malaysia dan membaca Pemasyhuran di Kuching.', 'tan_sri_dato_amar_stephen_kalong.png'),
(7, 'Wakil SUPP / Pembangkang', 'Wakil gerakan politik tempatan di Sarawak yang menentang idea gabungan awal.', 'Menuntut kemerdekaan Sarawak secara berasingan sebelum cadangan persekutuan.', 'orang_sarawak.png'),
(8, 'Orang Kampung', 'Penduduk kampung Borneo yang ingin tahu apa untungnya Malaysia.', 'Mewakili suara rakyat biasa yang bertanya dan perlu diyakinkan.', 'orang_bajau.png'),
(9, 'Tun Datu Mustapha bin Datu Harun', 'Pengasas USNO dan Pemimpin Utama Sabah.', 'Memimpin penyatuan rakyat Sabah dan menyokong pembentukan Malaysia.', 'tun_dato_mustapha.png'),
